package org.jdal.log;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.aspectj.lang.ProceedingJoinPoint;

/**
 * A Log method tracer to use as around advice to avoid "in code" debug
 * Enter/Exit method traces.
 * 
 * Example: 
 * 
 *		<aop:aspect id="methodTracerAspect" ref="methodTracer">
 *			<aop:pointcut id="anyMethod" expression="execution(* a.b.c.*(..))"/>
 *			<aop:around pointcut-ref="anyMethod" method="traceMethod"/>
 *		
 *  
 * 
 * <bean id="methodTracer" class="info.joseluismartin.log.MethodTracer"/>
 * 
 * @author  - (
 */

public class MethodTracer {
	/** log */
	private static Log log = LogFactory.getLog(MethodTracer.class);

	/**
	 * Simple Around Advice for trace in/out method execution
  	 * 
	 * @param pjp the joint point
	 * @return returned object.
	 * @throws Throwable for the method
	 */
	public Object traceMethod(ProceedingJoinPoint  pjp) throws Throwable {
		log.debug("Enter method: " + pjp.getSignature().toLongString());
		Object result = pjp.proceed();
		log.debug("Exit method: " + pjp.toShortString());
		return result;
	}
}

public class ICalendarResourceClient extends RestApiClient<ICalendarResourceClient> {
    public ICalendarResourceClient(JIRAEnvironmentData environmentData) {
        super(environmentData);
    }

    /**
     * @return Response with QueryOptions as a body
     */
    public Response<QueryOptions> getQueryOptions() {
        return toResponse(() -> createResource().path("config").path("query").path("options").get(ClientResponse.class), QueryOptions.class);
    }

    /**
     * @return Response with null body
     */
    public Response validateJql(String jql) {
        MultivaluedMap<String, String> body = new MultivaluedMapImpl();
        body.put("jql", Collections.singletonList(jql));

        return toResponse(() -> createResource().path("util").path("jql").path("validate").type("application/x-www-form-urlencoded").post(ClientResponse.class, body));
    }

    /**
     * @return Response with Set of available dates fields as a body
     */
    public Response<? extends Set> getConfigFields(String jql) {
        return toResponse(() -> createResource().path("config").path("fields").queryParam("jql", jql).get(ClientResponse.class), HashSet.class);
    }

    /**
     * @return Response with null body
     */
    public Response searchWithJql(String jql, String... dateFieldNames) {
        WebResource part = createResource().path("search").path("jql").path("events.ics").queryParam("jql", jql);
        final WebResource resource = applyDateFieldNameQueryParams(part, dateFieldNames);
        return toResponse(() -> resource.get(ClientResponse.class));
    }

    /**
     * @return Response with null body
     */
    public Response searchWithFilter(String filterId, String... dateFieldNames) {
        WebResource part = createResource().path("search").path("filter").path("events.ics").queryParam("searchFilterId", filterId);
        final WebResource resource = applyDateFieldNameQueryParams(part, dateFieldNames);
        return toResponse(() -> resource.get(ClientResponse.class));
    }

    @Override
    protected WebResource createResource() {
        return resourceRoot(getEnvironmentData().getBaseUrl().toExternalForm()).path("rest").path("ical").path("1.0").path("ical");
    }

    private WebResource applyDateFieldNameQueryParams(WebResource part, String[] dateFieldNames) {
        if (dateFieldNames != null) {
            for (String name : dateFieldNames) {
                part = part.queryParam("dateFieldName", name);
            }
        }
        return part;
    }


    /**
     * Mapping classes copied from jira-ical-feed plugin
     */
    @XmlRootElement
    public static class QueryOptions
    {
        @XmlElement
        public List<SimpleProject> projects;

        @XmlElement
        public List<SearchFilter> searchFilters;

        @XmlElement
        public String visibleFieldNames;

        @XmlElement
        public String visibleFunctionNamesJson;

        @XmlElement
        public String jqlReservedWordsJson;

        @XmlElement
        public boolean dateRangeSupported = true;
    }

    @XmlRootElement
    public static class SimpleProject implements Comparable<SimpleProject>
    {
        @XmlElement
        public String key;

        @XmlElement
        public String name;

        @Override
        public int compareTo(SimpleProject simpleProject)
        {
            int result = StringUtils.defaultString(name).compareTo(StringUtils.defaultString(simpleProject.name));
            return 0 == result
                    ? key.compareTo(simpleProject.key)
                    : result;
        }
    }

    @XmlRootElement
    public static class SearchFilter implements Comparable<SearchFilter>
    {
        @XmlElement
        public long id;

        @XmlElement
        public String name;

        @XmlElement
        public String description;

        @Override
        public int compareTo(SearchFilter searchFilter)
        {
            int result = StringUtils.defaultString(name).compareTo(StringUtils.defaultString(searchFilter.name));
            return 0 == result
                    ? (int) (id - searchFilter.id)
                    : result;
        }
    }

}

protected void checkIsSplitToJobsAllowed(GridifyRangeArgument arg, GridifySetToSet ann) throws GridException {
        if (arg.getInputSize() == UNKNOWN_SIZE && ann.threshold() <= 0 && ann.splitSize() <= 0) {
            throw new GridException("Failed to split input method argument to jobs with unknown input size and " +
                "invalid annotation parameter 'splitSize' [mtdName=" + arg.getMethodName() + ", inputTypeCls=" +
                arg.getMethodParameterTypes()[arg.getParamIndex()].getName() +
                ", threshold=" + ann.threshold() + ", splitSize=" + ann.splitSize() + ']');
        }
    }

package Feb2021Leetcode;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class _0438FindAllAnagramsInAString {

	public static void main(String[] args) {
		System.out.println(findAnagrams("cbaebabacd", "abc"));
		System.out.println(findAnagrams("abab", "ab"));
		System.out.println(findAnagrams("aaaaaaa", "a"));
	}

	public static List findAnagrams(String s, String p) {
		List out = new ArrayList
		if (p.length() > s.length())
			return out;

		HashMap<Character, Integer> pMap = new HashMap<Character, Integer>();
		for (int i = 0; i < p.length(); i++) {
			pMap.compute(p.charAt(i), (k, v) -> v == null ? 1 : v + 1);
		}

		int left = 0, right = 0;
		HashMap<Character, Integer> sMap = new HashMap<Character, Integer>();
		while (right < s.length()) {
			char c = s.charAt(right);
			sMap.compute(c, (k, v) -> v == null ? 1 : v + 1);
			if (right >= p.length()-1) {
				if (mapEquals(sMap, pMap)) {
					out.add(left);
				}
				char leftChar = s.charAt(left);
				sMap.put(leftChar, sMap.get(leftChar) - 1);
				if (sMap.get(leftChar) == 0)
					sMap.remove(leftChar);

				left++;
			}
			right++;
		}
		return out;
	}

	public static boolean mapEquals(HashMap<Character, Integer> sMap, HashMap<Character, Integer> pMap) {
		for (Map.Entry<Character, Integer> entry : pMap.entrySet()) {
			if (!sMap.containsKey(entry.getKey()) || sMap.get(entry.getKey()).intValue() != entry.getValue().intValue())
				return false;
		}
		return true;
	}

}

private static void spatialSearch(String searchText, String q, double longitude, double latitude, double width)
			throws IOException, ParseException, SQLException {
		Connection conn = null;
		double dist;
		int counter = 0;
		try {
			conn = DbManager.getConnection(true);
		} catch (SQLException ex) {
			System.out.println(ex);
		}
		Statement stmt = conn.createStatement();
		System.out.println("Running spatial search on (" + searchText + ") with longitude: " + longitude + " latitude: "
				+ latitude + " and width: " + width);
		/* calculate the lat long values with the given width */
		double longitudeD = (Math.asin((width / 2) / (6371.04 * Math.cos(Math.PI * latitude / 180)))) * 180 / Math.PI;
		double latitudeD = (Math.asin((double) (width / 2) / (double) 6371.04)) * 180 / Math.PI;
		double latitudeMax = latitude + (latitudeD);
		double latitudeMin = latitude - (latitudeD);
		double longitudeMax = longitude + (longitudeD);
		double longitudeMin = longitude - (longitudeD);
		String topRight = latitudeMax + " " + longitudeMax;
		String topLeft = latitudeMin + " " + longitudeMax;
		String botRight = latitudeMax + " " + longitudeMin;
		String botLeft = latitudeMin + " " + longitudeMin;
		Path path = Paths.get("indexes");
		Directory directory = FSDirectory.open(path);
		IndexReader indexReader = DirectoryReader.open(directory);
		IndexSearcher indexSearcher = new IndexSearcher(indexReader);
		QueryParser queryParser = new QueryParser(q, new SimpleAnalyzer());
		Query query = queryParser.parse(searchText);
		TopDocs topDocs = indexSearcher.search(query, 19532);
		System.out.println("Number of Hits: " + topDocs.totalHits);
		for (ScoreDoc scoreDoc : topDocs.scoreDocs) {
			Document document = indexSearcher.doc(scoreDoc.doc);
			String sqlId = "SELECT ItemID, AsText(Location) AS l, X(Location) AS x, Y(Location) AS y FROM ItemLocation AS iloc WHERE iloc.ItemID="
					+ document.get("item_id") + ";";
			ResultSet rsID = stmt.executeQuery(sqlId);
			if (rsID.next()) {
				dist = Haversine.haversine(latitude, longitude, Double.valueOf(rsID.getString("x")),
						Double.valueOf(rsID.getString("y")));
				String sqlp = "SELECT MBRContains(GeomFromText('Polygon((" + botLeft + "," + topLeft + "," + topRight
						+ "," + botRight + "," + botLeft + "))'), GeomFromText('" + rsID.getString("l") + "')) AS p;";
				ResultSet rs = stmt.executeQuery(sqlp); 
				if (rs.next()) {
					if (rs.getString("p").equals("1")) { 
						IndexDoc doc = new IndexDoc();
						doc.setId(document.get("item_id"));
						doc.setName(document.get("item_name"));
						doc.setPrice(document.get("item_curr_price"));
						doc.setScore(scoreDoc.score);
						doc.setDistance(dist);
						indexDocs.add(doc);
						counter++;
						doc = null; 
					}
				}
			}
		}
		System.out.println("Number of Hits inside Bounding Box: " + counter);
		/**
		 * ordered by decreasing Lucene-score for items with equal Lucene score,
		 * order them by decreasing distance from the geo-location given by the
		 * latitude and longitude numbers for items with equal Lucene score and
		 * equal distance, order them by decreasing price, where price is
		 * defined as before.
		 */
		Collections.sort(indexDocs, new Comparator<IndexDoc>() {
			@Override
			public int compare(IndexDoc o1, IndexDoc o2) {
				if (o1.score == o2.score) {
					if (o1.getDistance() == o2.getDistance())
						return o1.getPrice().compareTo(o2.getPrice());
					else
						return Double.compare(o1.getDistance(), o2.getDistance());
				} else if (o1.score < o2.score)
					return 1;
				else
					return -1;
			}
		});
		/* print the sorted ArrayList */
		for (IndexDoc element : indexDocs) {
			System.out.println(element.getId() + ", " + element.getName() + ", score:" + element.getScore() + ", "
					+ element.getDistance() + ", " + element.getPrice());
		}
		indexDocs.clear();
	}

package main

import (
	"syscall/js"
)

func fib(n int) int {
	if n <= 1 {
		return n
	}
	prev, curr := 0, 1
	for i := 2; i <= n; i++ {
		prev, curr = curr, prev+curr
	}
	return curr
}

func fibWrapper() js.Func {
	return js.FuncOf(func(this js.Value, args []js.Value) interface{} {
		if len(args) != 2 {
			return "Invalid number of arguments"
		}

		n := args[0].Int()
		callback := args[1]

		go func() {
			result := fib(n)
			callback.Invoke(result)
		}()

		return nil
	})
}

func main() {
	js.Global().Set("fib", fibWrapper())
	select {} // Block forever
}

def rename_files(files_or_path: Union[seq, Path], has: str, what: str, to: str):
    if isinstance(files_or_path, Path):
        if files_or_path.is_dir():
            return rename_files(files(files_or_path), has, what, to)
        else:
            return rename_files(seq(files_or_path), has, what, to)
    else:
        return files_or_path.map(lambda p: p if has not in p.name else p.rename(Path(p.parent, p.name.replace(what, to))))

