﻿using Cantarus.Modules.PolyDeploy.Components.DataAccess.Models;
using DotNetNuke.Data;
using System.Collections.Generic;
using System.Linq;

namespace Cantarus.Modules.PolyDeploy.Components.DataAccess.DataControllers
{
    internal class SettingDataController
    {
        /// 
        /// Retrieve a setting from the database by its group and key.
        /// 
        /// <param name="group">
        /// <param name="key">
        /// 
        public Setting GetSetting(string group, string key)
        {
            using (IDataContext context = DataContext.Instance())
            {
                var repo = context.GetRepository

                return repo.Find("WHERE [Group] = @0 AND [Key] = @1", group, key).FirstOrDefault
            }
        }

        /// 
        /// Return all settings belonging to a group.
        /// 
        /// <param name="group">
        /// 
        public IEnumerable GetSettings(string group)
        {
            using (IDataContext context = DataContext.Instance())
            {
                var repo = context.GetRepository

                return repo.Find("WHERE [Group] = @0", group);
            }
        }

        /// 
        /// Create a new setting.
        /// 
        /// <param name="setting">
        public void Create(Setting setting)
        {
            using (IDataContext context = DataContext.Instance())
            {
                var repo = context.GetRepository

                repo.Insert(setting);
            }
        }

        /// 
        /// Update an existing setting.
        /// 
        /// <param name="setting">
        public void Update(Setting setting)
        {
            using (IDataContext context = DataContext.Instance())
            {
                var repo = context.GetRepository

                repo.Update(setting);
            }
        }

        /// 
        /// Delete a setting.
        /// 
        /// <param name="setting">
        public void Delete(Setting setting)
        {
            using (IDataContext context = DataContext.Instance())
            {
                var repo = context.GetRepository

                repo.Delete(setting);
            }
        }
    }
}

