    private File tempDir;
    private FileUtil fileUtil;
    private Serializer serializer;
    private PublicKeyManager publicKeyManager;

    @Before
    public void setUp() {
        tempDir = new File(System.getProperty("java.io.tmpdir"), "file-util-test");
        tempDir.mkdirs();
        fileUtil = new FileUtil();
        serializer = new Serializer();
        publicKeyManager = new PublicKeyManager();
    }

    @After
    public void tearDown() {
        deleteDirectory(tempDir);
    }

    @Test
    public void testWriteAndReadPersistentMetadata() {
        PersistentMetadata metadata = new PersistentMetadata("test-metadata");
        String serializedMetadata = serializer.serialize(metadata);
        File metadataFile = new File(tempDir, "metadata.dat");
        fileUtil.writePersistentMetadata(metadataFile, serializedMetadata, publicKeyManager);
        String readMetadata = fileUtil.readPersistentMetadata(metadataFile, publicKeyManager);
        assertEquals(serializedMetadata, readMetadata);
    }

    @Test
    public void testSortFilesPreorder() {
        List<File> files = new ArrayList<>();
        files.add(new File(tempDir, "file1.txt"));
        files.add(new File(tempDir, "file2.txt"));
        files.add(new File(tempDir, "file3.txt"));
        files.add(new File(tempDir, "dir1"));
        files.add(new File(tempDir, "dir1/file4.txt"));
        files.add(new File(tempDir, "dir1/dir2"));
        files.add(new File(tempDir, "dir1/dir2/file5.txt"));
        List<File> sortedFiles = fileUtil.sortFilesPreorder(files);
        List<File> expectedSortedFiles = new ArrayList<>();
        expectedSortedFiles.add(new File(tempDir, "file1.txt"));
        expectedSortedFiles.add(new File(tempDir, "file2.txt"));
        expectedSortedFiles.add(new File(tempDir, "file3.txt"));
        expectedSortedFiles.add(new File(tempDir, "dir1"));
        expectedSortedFiles.add(new File(tempDir, "dir1/file4.txt"));
        expectedSortedFiles.add(new File(tempDir, "dir1/dir2"));
        expectedSortedFiles.add(new File(tempDir, "dir1/dir2/file5.txt"));
        assertArrayEquals(expectedSortedFiles.toArray(), sortedFiles.toArray());
    }

    private void deleteDirectory(File dir) {
        File[] files = dir.listFiles();
        if (files!= null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    deleteDirectory(file);
                } else {
                    file.delete();
                }
            }
        }
        dir.delete();
    }
}

