#include <bits/stdc++.h>

#define int long long

#define mp make_pair

#define fi first

#define se second

#define pb push_back

#define vi vector<int>

#define pi pair<int, int>

template<typename T> bool chkmin(T &a, T b){return (b < a) ? a = b, 1 : 0;}

template<typename T> bool chkmax(T &a, T b){return (b > a) ? a = b, 1 : 0;}

using namespace std;

const int mod = 998244353;

const int maxn = 1000005;

const int S = 1000000007;

int tp[maxn], x[maxn];

int preft[maxn];

signed main() {

    int n;

    cin >> n;

    for (int i = 1; i <= n; i++) {

        cin >> tp[i];

        if (tp[i] <= 2) cin >> x[i];

    }

    for (int i = 1; i <= n; i++) {

        preft[i] = preft[i - 1];

        if (tp[i] == 2) preft[i] += x[i];

        else if (tp[i] == 3) preft[i] *= 2;

        chkmin(preft[i], S);

    }

    vi cr;

    int mt = 1;

    int sum = 0;

    int ans = 0;

    for (int i = n; i >= 1; i--) {

        if (tp[i] == 3) {

            if (preft[i - 1] == 0) mt = (mt * 2) % mod;

            else if (preft[i - 1] < S)

                cr.pb(preft[i - 1]);

        }

        else if (tp[i] == 2) {

            sum += x[i];

            chkmin(sum, S);

        }

        else if (tp[i] == 1) {

            int cur = x[i] - sum;

            if (cur <= 0) continue;

            int nans = 1;

            for (int j = 0; j < cr.size(); j++) {

                if (cur > cr[j]) {

                    cur -= cr[j];

                    nans += (1ll) << (cr.size() - j - 1);

                }

            }

            nans %= mod;

            nans = nans * mt % mod;

            ans = (ans + nans) % mod;

        }

    }

    cout << ans << endl;



    return 0;

}

char *
GetNextToken(
             char * Tok
             )
{
    static char * Source;     
    static char RetBuff[512]; 
    static char *Ret;         
    static char * p;       
    if (Tok!=NULL) {
        Source = Tok;
        Ret = RetBuff;
        RetBuff[0] = '\0';
        p = Source;
    } else if (p==NULL) {
        return NULL;          
    } else {
        Ret +=strlen(Ret)+1;  
    }
    *Ret = '\0';              
    for (; ; ) {
        if (*p=='\"') {
            ++p;
            Tok = My_mbschr(p, '"');
            if (Tok==NULL) {
                strcat(Ret, p);
                p = NULL;
                return Ret;
            } else {
                *Tok = '\0';    
                strcat(Ret, p); 
                p = Tok+1;      
            }
        } else {
            int i = strcspn(p," \"");   
            if (p[i]=='\0') {
                strcat(Ret, p);
                p = NULL;
                return Ret;
            } else if (p[i]==' ') {
                p[i] = '\0';
                strcat(Ret, p);
                p +=i+1;
                while (*p==' ')
                    ++p;
                if (*p=='\0')
                    p = NULL;
                return Ret;
            } else {
                p[i] = '\0';
                strcat(Ret, p);
                p[i] = '\"';     
                p +=i;           
            }
        }
    } 
}

