export default function generateUserPage(user) {
  const userName = user.name || 'Guest';
  const userEmail = user.email || 'noemail@example.com';

  const html = `
    <div id="userPage">
      ${head.js()}
      <div class="user-content">
        <h2>User Profile</h2>
        <p>Name: ${userName}</p>
        <p>Email: ${userEmail}</p>
        <button id="fetchContentButton">Fetch User Content</button>
        <div id="userContent"></div>
      </div>
      ${footer.js()}
    </div>
  `;

  const fetchContentButton = document.getElementById('fetchContentButton');

  fetchContentButton.addEventListener('click', async () => {
    const data = { hello: 'hello' };
    try {
      const response = await fetch('/fetchUserContent', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const content = await response.text();
      document.getElementById('userContent').innerHTML = content;

    } catch (error) {
      alert(`Error fetching content: ${error.message}`);
    }
  });

  return html;
}

