template<typename T>
class PriorityQueue {
    // ... [previous members]

    std::vector<T> heap;
    std::vector<int> locator;
    std::function<bool(const T&, const T&)> comparator;

public:
    PriorityQueue(const std::function<bool(const T&, const T&)>& comp = std::less<>())
        : comparator(comp) {}

    // ... [other methods]

    T get_top() {
        if (heap.empty()) return -1;
        T top = heap.front();
        heap.erase(heap.begin());
        locator.erase(locator.begin());
        bubble_down(0);
        return top;
    }

    void bubble_down(int index) {
        int child_index = 2 * index + 1;
        while (child_index < locator.size()) {
            if (child_index + 1 < locator.size() && comparator(heap[child_index + 1], heap[child_index])) {
                child_index++;
            }
            if (comparator(heap[child_index], heap[index])) {
                std::swap(heap[index], heap[child_index]);
                locator[index] = child_index;
                index = child_index;
                child_index = 2 * index + 1;
            } else {
                break;
            }
        }
    }
};

