TEST_CASE("Generate all combinations (even)") {
    constexpr int N = 6;
    constexpr int K = 3;
    int cnt = 0;
    auto lst = std::vector 0);
    std::fill_n(lst.begin(), K, 1);
    for ([[maybe_unused]] auto& l : ecgen::EMK(N, K, lst)) {
        ++cnt;
    }
    CHECK(cnt == ecgen::Combination<N, K>());
}

