public class FileStore<TName, TValue>
        where TValue : class
    {
        private AsyncReaderWriterLock storeLock = new AsyncReaderWriterLock();
        public static Func<Stream, TName, TValue, CancellationToken, Task> JsonSerialize =
            (stream, name, value, canel) =>
            {
                using (var writer = new StreamWriter(stream))
                using (var jtw = new JsonTextWriter(writer) { Formatting = Formatting.Indented })
                {
                    var ser = new JsonSerializer();
                    ser.Serialize(jtw, value);
                    jtw.Flush();
                    return Task.CompletedTask;
                }
            };
        public static Func<Stream, TName, CancellationToken, Task<TValue>> JsonDeserialize =
            (stream, name, cancel) =>
            {
                using (var reader = new StreamReader(stream))
                using (var jtr = new JsonTextReader(reader))
                {
                    var ser = new JsonSerializer();
                    return Task.FromResult(ser.Deserialize<TValue>(jtr));
                }
            };
        public string Folder { get; set; }
        public Func<TName, string> NameToKey { get; set; }
        public Func<string, TName> KeyToName { get; set; }
        public Func<Stream, TName, TValue, CancellationToken, Task> Serialize
            { get; set; } = JsonSerialize;
        public Func<Stream, TName, CancellationToken, Task<TValue>> Deserialize
            { get; set; } = JsonDeserialize;
        public async Task<TValue> TryGetAsync(TName name, CancellationToken cancel = default(CancellationToken))
        {
            var path = GetPath(name);
            using (await storeLock.ReaderLockAsync().ConfigureAwait(false))
            {
                if (!File.Exists(path))
                {
                    return null;
                }
                using (var content = File.OpenRead(path))
                {
                    return await Deserialize(content, name, cancel).ConfigureAwait(false);
                }
            }
        }
        public async Task<TValue> GetAsync(TName name, CancellationToken cancel = default(CancellationToken))
        {
            var value = await TryGetAsync(name, cancel).ConfigureAwait(false);
            if (value == null)
                throw new KeyNotFoundException($"Missing '{name}'.");
            return value;
        }
        public async Task PutAsync(TName name, TValue value, CancellationToken cancel = default(CancellationToken))
        {
            var path = GetPath(name);
            using (await storeLock.WriterLockAsync(cancel).ConfigureAwait(false))
            using (var stream = File.Create(path))
            {
                try
                {
                    await Serialize(stream, name, value, cancel).ConfigureAwait(false);
                }
                catch (Exception)
                {
                    try
                    {
                        stream.Dispose();
                        File.Delete(path);
                    }
                    catch (Exception)
                    {
                    }
                    throw;  
                }
            }
        }
        public async Task RemoveAsync(TName name, CancellationToken cancel = default(CancellationToken))
        {
            var path = GetPath(name);
            using (await storeLock.WriterLockAsync(cancel).ConfigureAwait(false))
            {
                File.Delete(path);
            }
        }
        public async Task<long?> LengthAsync(TName name, CancellationToken cancel = default(CancellationToken))
        {
            var path = GetPath(name);
            using (await storeLock.ReaderLockAsync().ConfigureAwait(false))
            {
                var fi = new FileInfo(path);
                long? length = null;
                if (fi.Exists)
                    length = fi.Length;
                return length;
            }
        }
        public async Task<bool> ExistsAsync(TName name, CancellationToken cancel = default(CancellationToken))
        {
            var path = GetPath(name);
            using (await storeLock.ReaderLockAsync().ConfigureAwait(false))
            {
                return File.Exists(path);
            }
        }
        public IEnumerable<TValue> Values
        {
            get
            {
                return Directory
                    .EnumerateFiles(Folder)
                    .Select(path =>
                    {
                        using (var content = File.OpenRead(path))
                        {
                            var name = KeyToName(Path.GetFileName(path));
                            return Deserialize(content, name, CancellationToken.None)
                                .ConfigureAwait(false)
                                .GetAwaiter()
                                .GetResult();
                        }
                    });
            }
        }
        public IEnumerable<TName> Names
        {
            get
            {
                return Directory
                    .EnumerateFiles(Folder)
                    .Select(path => KeyToName(Path.GetFileName(path)));
            }
        }
        public string GetPath(TName name)
        {
            return Path.Combine(Folder, NameToKey(name));
        }
    }

def check_deprecated_semver(removal_version):
  if not isinstance(removal_version, six.string_types):
    raise BadRemovalVersionError('The removal_version must be a semver version string.')
  try:
    removal_semver = Revision.semver(removal_version)
  except Revision.BadRevision as e:
    raise BadRemovalVersionError('The given removal version {} is not a valid semver: '
                                 '{}'.format(removal_version, e))
  if removal_semver <= _PANTS_SEMVER:
    raise PastRemovalVersionError('The removal version must be greater than the current pants '
                                  'version of {} - given {}'.format(VERSION, removal_version))

public void SaveTo(Stream stream)
        {
            if (stream is null)
                throw new ArgumentNullException(nameof(stream));
            if (!stream.CanWrite)
                throw new ArgumentException(ErrorMessages.StreamNotWritable, nameof(stream));
            using var writer = new StreamWriter(stream);
            SaveTo(writer);
        }

def serialize(configs, regret, meta_features, output_file, config_path):
    output_file = Path(output_file)
    try:
        output_file.unlink()
    except FileNotFoundError:
        pass
    meta_features_norm, preferences, proc = config_predictor_tuple(
        regret.columns, configs, meta_features, regret
    )
    portfolio = [load_json(config_path.joinpath(m + ".json")) for m in configs]
    regret = regret.loc[configs]
    from flaml import __version__
    meta_predictor = {
        "version": __version__,
        "meta_feature_names": list(meta_features.columns),
        "portfolio": portfolio,
        "preprocessing": proc,
        "neighbors": [
            {"features": tuple(x), "choice": _filter(preferences[y], regret[y])}
            for x, y in zip(
                meta_features_norm.to_records(index=False), preferences.columns
            )
        ],
        "configsource": list(configs),
    }
    with open(output_file, "w+") as f:
        json.dump(meta_predictor, f, indent=4)
    return meta_predictor

