    width: 100,
  },
});

export default TimePicker;

/**
   * Returns a boolean property from the provided property map. If the provided property map does not contain the
   * property name provided, the provided default value is returned instead.
   *
   * @param propertyName the name of the property
   * @param defaultValue the default value
   * @throws JoiseException if there is an error with the retrieval
   */
public boolean getBooleanProperty(Map<String, Object> propertyMap, String propertyName, boolean defaultValue) {
    Object propertyValue = propertyMap.get(propertyName);

    if (propertyValue == null) {
        return defaultValue;
    }

    if (propertyValue instanceof Boolean) {
        return (Boolean) propertyValue;
    } else if (propertyValue instanceof String) {
        String stringValue = (String) propertyValue;
        return stringValue != null && stringValue.equalsIgnoreCase("true");
    } else {
        throw new IllegalArgumentException("Property value for " + propertyName + " is not a boolean or string.");
    }
}

