func (q *MinPriorityQueue) ExtractMin() (string, error) {
    if q.size == 0 {
        return "", errors.New("queue is empty")
    }
    minNode := q.Nodes[0]
    q.Nodes[0] = q.Nodes[q.size-1]
    q.size--
    q.percolateDown(0)
    return minNode.name, nil
}

