'use strict';

const express = require('express');
const Storage = require('./storage'); // Assuming storage is in a separate file
const CoreExtensions = require('./core-extensions'); // Assuming core-extensions is in a separate file

let serverInstance = null;
let storageInstance = null;
let coreInstance = null;
let authKey = null;

module.exports = {
  start: async (config) => {
    if (serverInstance) {
      console.log('Server is already running.');
      return;
    }

    try {
      storageInstance = new Storage(config.storage);
      coreInstance = new CoreExtensions(config.coreExtensions);

      const app = express();

      // Add middleware or routes as needed

      const port = config.port || 3000;
      serverInstance = app.listen(port, () => {
        console.log(`Server listening on port ${port}`);
      });

    } catch (error) {
      console.error('Initialization failed:', error);
      process.exit(1);
    }
  },

  generateAuthKey: () => {
    if (!serverInstance) {
      console.log('Server is not running.');
      return null;
    }

    authKey = 'generated_auth_key_' + Math.random().toString(36).substring(2, 15); // Simple key generation
    console.log('Authentication key generated:', authKey);
    return authKey;
  },

  deleteAuthKey: () => {
    if (!serverInstance) {
      console.log('Server is not running.');
      return;
    }

    authKey = null;
    console.log('Authentication key deleted.');
  },

  getServerStatus: () => {
    return !!serverInstance;
  }
};

def __analyze_neighbors(neighbors, excluded_nodes, weight):
        node_weights = {}
        for n in neighbors:
            if n not in excluded_nodes:
                if n in node_weights.keys():
                    node_weights[n] = min(node_weights[n] + weight, 1.0)
                else:
                    node_weights[n] = weight
        return node_weights

