public <R> StreamableResource<R> expand(IOStreamTransform<? extends R> transform) {
    return new StreamableResource<R>() {
        @Override
        public Iterator<R> iterator() {
            return new Iterator<R>() {
                private final Iterator<StreamableResource<? extends R>> iterator = transform.apply(getStreamableResource()).iterator();
                private Iterator<? extends R> currentIterator;

                @Override
                public boolean hasNext() {
                    while (iterator.hasNext() && (currentIterator == null ||!currentIterator.hasNext())) {
                        currentIterator = iterator.next().iterator();
                    }
                    return currentIterator!= null && currentIterator.hasNext();
                }

                @Override
                public R next() {
                    if (!hasNext()) {
                        throw new NoSuchElementException();
                    }
                    return currentIterator.next();
                }

                @Override
                public void remove() {
                    throw new UnsupportedOperationException();
                }
            };
        }
    };
}

