import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class RedisLock implements Lock {

    private final String key;
    private final RedisTemplate redisTemplate;

    public RedisLock(String key, RedisTemplate redisTemplate) {
        this.key = key;
        this.redisTemplate = redisTemplate;
    }

    private Thread watchDogThread = null;

    @Override
    public void lock() throws InterruptedException {
        while (true) {
            if (redisTemplate.setNX(key, "1")) {
                if (watchDogThread == null) {
                    watchDogThread = new Thread(() -> {
                        try {
                            while (!Thread.currentThread().isInterrupted()) {
                                // Simulate lock renewal - replace with actual renewal logic
                                Thread.sleep(1000);
                                redisTemplate.watch(key);
                            }
                        } finally {
                            // Ensure watchDogThread is stopped when interrupted
                            if (watchDogThread != null) {
                                watchDogThread.interrupt();
                            }
                        }
                    });
                    watchDogThread.start();
                }
                return;
            }
        }
    }

    @Override
    public boolean tryLock() {
        return redisTemplate.setNX(key, "1");
    }

    @Override
    public void unlock() {
        redisTemplate.delete(key);
        if (watchDogThread != null) {
            watchDogThread.interrupt();
            watchDogThread = null;
        }
    }

    @Override
    public void lockInterruptibly() throws InterruptedException {
        throw new UnsupportedOperationException("lockInterruptibly() is not supported");
    }

    @Override
    public boolean tryLock(long time, TimeUnit unit) throws InterruptedException {
        return false;
    }

    @Override
    public Condition newCondition() {
        return null;
    }
}

