            List<T> dest,
            Collection<T> source) {
        source = source == null ? Collections.emptyList() : source;
        if (dest == null) {
            dest = new ArrayList<>(source);
        } else {
            dest.clear();
            dest.addAll(source);
        }
        return dest;
