	pts = []
	for i in range(n):
		(x, y) = input().strip().split(' ')
		pts.append((int(x), int(y)))

	def key(pt):
		(x, y) = pt
		a = math.atan2(y, x)
		if a < 0:
			a += 2 * math.pi
		d = math.sqrt(x * x + y * y)
		return (a, d)
	pts.sort(key=key)
	for pt in pts:
		print(*pt)
