import React, { useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import { Button, Grid, Typography, CircularProgress, Box } from '@material-ui/core';
import Header from './Header';
import axiosInstance from './axiosInstance';

function UserProfile() {
    const [userData, setUserData] = React.useState(null);
    const [loading, setLoading] = React.useState(false);

    useEffect(() => {
        setLoading(true);
        axiosInstance.get('/api/users/me')
            .then(response => {
                setUserData(response.data);
                setLoading(false);
            })
            .catch(error => {
                console.error(error);
                setLoading(false);
            });
    }, []);

    if (loading) {
        return <CircularProgress size={50} />;
    }

    if (!userData) {
        return null;
    }

    return (
        <div>
            <Header />
            <Grid container spacing={2}>
                <Grid item xs={12} sm={6} md={6} lg={6}>
                    <Typography variant="h4">Name: {userData.name}</Typography>
                </Grid>
                <Grid item xs={12} sm={6} md={6} lg={6}>
                    <Typography variant="h4">Email: {userData.email}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Typography variant="h5">Skills: {userData.skills}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Typography variant="h5">Education: {userData.education}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Typography variant="h5">Job Experience: {userData.jobExperience}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Typography variant="h5">Certifications: {userData.certifications}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Typography variant="h5">Address: {userData.address}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Typography variant="h5">Score Card: {userData.scoreCard}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Typography variant="h5">Social Media Links:</Typography>
                    <Typography variant="h6">{userData.socialMediaLinks}</Typography>
                </Grid>
                <Grid item xs={12}>
                    <Link to={"/"}>
                        <Button variant="contained">Back</Button>
                    </Link>
                    <Link to={"/user-profile-edit"}>
                        <Button variant="contained">Edit</Button>
                    </Link>
                </Grid>
            </Grid>
        </div>
    );
}

export default UserProfile;

class Solution:

	def prank(self, a, n):
		temp = [0] * n
		dic = {}
		for i in range(n):
			dic[a[i]] = i
		for i in range(n):
			ti = dic[i]
			temp[ti] = a[i]
		for i in range(n):
			a[i] = temp[i]

public static Bucket waitForBucket(CouchbaseCluster cluster, String bucket) throws InterruptedException {
    final Iterator<TimeValue> retryDelays = truncatedExponentialBackoff(
        TimeValue.timeValueSeconds(1), TimeValue.timeValueMinutes(1)).iterator();
    while (true) {
      try {
        return cluster.openBucket(bucket);
      } catch (Exception e) {
        if (!ThrowableHelper.hasCause(e,
            ConnectException.class, RequestCancelledException.class, TemporaryFailureException.class)) {
          LOGGER.warn("Failed to open bucket", e);
          throw e;
        }
        final TimeValue delay = retryDelays.next();
        LOGGER.debug("failed to open bucket", e);
        LOGGER.warn("Couchbase connection failure, couldn't open bucket. Retrying in {}", delay);
        MILLISECONDS.sleep(delay.millis());
      }
    }
  }

