class Solution:

	def areMirror(self, root1, root2):
		if root1 == None and root2 == None:
			return 1
		elif root1 == None and root2 != None:
			return 0
		elif root1 != None and root2 == None:
			return 0
		elif root1.data != root2.data:
			return 0
		elif root1.data == root2.data:
			l = self.areMirror(root1.left, root2.right)
			r = self.areMirror(root1.right, root2.left)
			return min(l, r)

