const EventEmitter = require('events');
const Agent = require('./Agent');
const Debugger = require('./Debugger');

class Profiler extends Agent {
  static supportedMethods = [
    'start',
    'stop',
    'takeHeapSnapshot',
    'startTrackingHeapObjects',
    'stopTrackingHeapObjects',
  ];

  constructor(debugger) {
    super();
    this.debugger = debugger;
    this.eventEmitter = new EventEmitter();
  }

  async start() {
    await this.debugger.startCpuProfiling();
  }

  async stop() {
    const profile = await this.debugger.stopCpuProfiling();
    return profile;
  }

  async takeHeapSnapshot(reportProgress) {
    await this.debugger.takeHeapSnapshot(reportProgress);
    this.eventEmitter.emit('heapSnapshot', 'Heap snapshot taken');
  }

  async startTrackingHeapObjects(trackAllocations) {
    await this.debugger.startTrackingHeapObjects(trackAllocations);
    this.eventEmitter.emit('trackingHeapObjects', 'Tracking heap objects started');
  }

  async stopTrackingHeapObjects(reportProgress) {
    await this.debugger.stopTrackingHeapObjects(reportProgress);
    this.eventEmitter.emit('trackingHeapObjects', 'Tracking heap objects stopped');
  }

  on(event, callback) {
    this.eventEmitter.on(event, callback);
  }
}

module.exports = Profiler;

