class Profiler {
public:
    using Id = std::string;
    using Clock = std::chrono::high_resolution_clock;
    using TimePoint = std::chrono::time_point<Clock>;

    Profiler(Id id) : id_(id), start_(Clock::now()) {}
    Profiler(std::string message) : id_(std::move(message)), start_(Clock::now()) {}

    ~Profiler() {
        auto end = Clock::now();
        auto duration = std::chrono::duration<float>(end - start_).count();
        if (!id_.empty()) {
            std::cout << "Task " << id_ << " took " << duration << " seconds." << std::endl;
            timers_[id_] = duration;
        }
    }

    float getDuration(Id id) const {
        auto it = timers_.find(id);
        if (it != timers_.end()) {
            return it->second;
        }
        return -1.0f; // Indicate not found
    }

    void resetDuration(Id id) {
        timers_[id] = 0.0f;
    }

private:
    Id id_;
    TimePoint start_;
    std::map<Id, float> timers_;
};

def walkExtended(self, root, recurse=0, dirPattern='*' , filePattern='*', followSoftLinks = True, dirs=True, files=True ):
        self.log('Scanning directory (walk) %s'%root,6)
        result = []
        try:
            names = os.listdir(root)
        except os.error:
            return result  
        dirPattern = dirPattern or '*'
        dirPatList = dirPattern.split(';')
        filePattern = filePattern or '*'
        filePatList = filePattern.split(';')
        for name in names:
            fullname = os.path.normpath(os.path.join(root, name))
            if self.isFile(fullname, followSoftLinks):
                fileOK = False
                dirOK = False
                for fPat in filePatList:
                    if (fnmatch.fnmatch(name,fPat)):
                        fileOK = True
                for dPat in dirPatList:
                    if (fnmatch.fnmatch(os.path.dirname(fullname),dPat)):
                        dirOK = True
                if fileOK and dirOK and files:
                    result.append(fullname)
            if self.isDir(fullname, followSoftLinks):
                for dPat in dirPatList:
                    if (fnmatch.fnmatch(name,dPat) and dirs):
                        result.append(fullname)
            if recurse:
                result = result + self.walkExtended(root            = fullname,
                                                    recurse         = recurse,
                                                    dirPattern      = dirPattern,
                                                    filePattern     = filePattern,
                                                    followSoftLinks = followSoftLinks,
                                                    dirs            = dirs,
                                                    files           = files )
        return result

private void fireActionEvent(final ActionEvent event, boolean split, ActionListener[] singleEventListeners) {
        SplitButtonActionListener[] jointEventListeners = listenerList.getListeners(SplitButtonActionListener.class);
        if (jointEventListeners.length != 0 || singleEventListeners.length != 0) {
            String actionCommand = event.getActionCommand();
            if (actionCommand == null) {
                actionCommand = getActionCommand();
            }
            ActionEvent e = new ActionEvent(JSplitButton.this,
                    ActionEvent.ACTION_PERFORMED,
                    actionCommand,
                    event.getWhen(),
                    event.getModifiers());
            if (jointEventListeners.length != 0) {
                for (int i = jointEventListeners.length - 1; i >= 0; i--) {
                    if (split) {
                        jointEventListeners[i].splitButtonClicked(e);
                    } else {
                        jointEventListeners[i].buttonClicked(e);
                    }
                }
            }
            if (singleEventListeners.length != 0) {
                for (int i = singleEventListeners.length - 1; i >= 0; i--) {
                    singleEventListeners[i].actionPerformed(e);
                }
            }
        }
    }

