def can_make_strings_equal(t, test_cases):
    results = []
    for case in test_cases:
        n, strings = case
        # Dictionary to store the count of each character
        char_count = {}

        # Count all characters in all strings
        for string in strings:
            for char in string:
                if char in char_count:
                    char_count[char] += 1
                else:
                    char_count[char] = 1

        # Check if each character's count is divisible by n
        possible = True
        for count in char_count.values():
            if count % n != 0:
                possible = False
                break

        # Append result for this test case
        if possible:
            results.append("YES")
        else:
            results.append("NO")

    return results

