public class SumAllPrimes {

    public static int sumOfPrimes(int n) {
        int sum = 0;

        for (int i = 2; i <= n; i++) {
            if (isPrime(i)) {
                sum += i;
            }
        }

        return sum;
    }

    private static boolean isPrime(int n) {
      // Corner case
        if (n <= 1) {
            return false;
        }

        // Check from 2 to n-1
        for (int i = 2; i < n; i++)
            if (n % i == 0) {
                return false;
            }

        return true;
    }
}

