                            final String value)
      throws ConverterException {
    // First determine which type we are using. The jsf page designer, will
    // have to pass a attribute with name 'typeName' with a a fqClassName
    // of the type to retrieve.
    String typeName = (String)component.getAttributes().get("typeName");
    Class type = PersistentBean.class;
    if (typeName != null || typeName.equals(EMPTY)) {
      try {
        type = Class.forName(typeName);
      }
      catch (LinkageError lErr) {
        throw new FacesException("Cannot convert String to Class", lErr);
      }
      catch (ClassNotFoundException cnfExc) {
        throw new FacesException("Cannot convert String to Class", cnfExc);
      }
    }

    Object result = null;
    if (value != null && !value.equals(EMPTY)) {
      Long id = Long.valueOf(value);
      LOG.debug("Recieving a request for a \"" + type + "\" with id \"" + id + "\".");
      HibernateDaoFactory daoFactory = new HibernateDaoFactory();
      HibernateAsyncCrudDao dao = (HibernateAsyncCrudDao)daoFactory.getDao(DaoFactory.ASYNC_CRUD);
      try {
        Session session = SessionInView.getSession(RobustCurrent.httpServletRequest());
        dao.setSession(session);
        result = dao.retrievePersistentBean(id, type);
        LOG.debug("\"" + type + "\" retrieved with id \"" + id + "\"");
      }
      catch (IdNotFoundException infExc) {
        LOG.error("No \"" + type + "\" found with id \"" + id + "\"");
        throw new ConverterException("No PersistentBean bean found with id " + id);
      }
      catch (TechnicalException tExc) {
        LOG.error("Failed to retrieve \"" + type + "\" due to technical problems", tExc);
        throw new ConverterException("Unable to retrieve PersistentBean due "
            + "to technical problems.");
      }
    }
    return result;
  }

  /**
   * The empty string.
   *
   * <strong>= &quot;&quot;</strong>
   */
  public static final String EMPTY = "";

  /**
   * @return    (value != null)
   *                ? (((PersistentBean)value).getId() != null)
   *                      ? ((PersistentBean)value).getId().toString
   *                      : ""
   *                : "";
   * @throws    ConverterException
   *            !(value instanceof PersistentBean))
   */
  public String getAsString(final FacesContext context,
                            final UIComponent component,
                            final Object value) throws ConverterException {
    if (value == null) {
      return EMPTY;
    }
    if (value.equals(EMPTY)) { // MUDO (jand) this is extremely weird; ask Abdul
      return EMPTY;
    }
    if (!(value instanceof PersistentBean)) {
      LOG.error("Unable to convert \"" + value + "\" because it is not a "
          + "subclass of PersistentBean.");
      throw new ConverterException("Value is not subclass of PersistentBean Class");
    }
    PersistentBean persistentBean = ((PersistentBean)value);
    return (persistentBean.getId() != null) ? persistentBean.getId().toString() : EMPTY;
  }

}

internal static void FindAdditionalBooks(Dictionary<int, string> bookIDNameMapping)
        {
            AssertCustomBooksImportEnabled();
            var ids = new Dictionary<string, int>();
            string idsPath = Path.Combine(mappingPath, "IDs.json");
            if (File.Exists(idsPath))
                ModManager._serializer.TryDeserialize(fsJsonParser.Parse(File.ReadAllText(idsPath)), ref ids);
            int idsCount = ids.Count;
            int currentId = 111;
            foreach (string mapContent in GetBooksMaps())
            {
                var map = new List<BookMappingEntry>();
                fsResult fsResult = ModManager._serializer.TryDeserialize(fsJsonParser.Parse(mapContent), ref map);
                if (fsResult.HasWarnings)
                    Debug.LogWarning(fsResult.FormattedMessages);
                if (fsResult.Succeeded)
                {
                    foreach (var book in map)
                    {
                        string name = book.Name + ".TXT";
                        int id;
                        if (!ids.TryGetValue(name, out id))
                            ids.Add(name, id = ++currentId != 10000 ? currentId : ++currentId);
                        bookIDNameMapping.Add(id, book.Title);
                        FileNames.Add(id, name);
                    }
                }
            }
            if (ids.Count > idsCount)
            {
                fsData fsData;
                ModManager._serializer.TrySerialize(ids, out fsData).AssertSuccessWithoutWarnings();
                Directory.CreateDirectory(mappingPath);
                File.WriteAllText(idsPath, fsJsonPrinter.PrettyJson(fsData));
            }
            if (FileNames.Count > 0)
                Debug.LogWarningFormat("Imported {0} custom books. Addition of custom books is EXPERIMENTAL and may introduce bugs! " +
                    "Breaking changes to this feature can also be expected until is considered stable.", FileNames.Count);
        }

