import com.google.appengine.api.datastore.*;
import com.google.appengine.api.datastore.Key;
import java.util.logging.Logger;

public class BlogOwnerSerializer {

    private static final Logger logger = Logger.getLogger(BlogOwnerSerializer.class.getName());

    public void serializeAndVerify() throws DataStoreException {
        Blog blog = new Blog();
        blog.setTitle("Java Programming Blog");
        saveAsSerializedModel(blog);

        BlogOwner blogOwner = new BlogOwner();
        blogOwner.setBlog(blog);
        blogOwner.setName("John Doe");
        saveAsSerializedModel(blogOwner);

        // Verify that it is possible to query both objects back, by their Java class type
        verifyQuery(blog);
        verifyQuery(blogOwner);
    }

    private void saveAsSerializedModel(Entity entity) throws DataStoreException {
        Key key = dsService.save(entity);
    }

    private void verifyQuery(Entity entity) {
        Query q = new Query(entity.getClass().getSimpleName());
        PreparedQuery pq = dsService.prepare(q);
        for (Entity result : pq.asIterable()) {
            if (result.getKey().equals(entity.getKey())) {
                logger.info("Entity retrieved successfully: " + result);
                return;
            }
        }
        logger.severe("Entity not found: " + entity);
    }
}

def _backtrack_visitors(self, i, maze, visited):
        wi = i - 1
        if wi >= 0 and wi % self._box_width != 0 and maze[wi] <= 0:
            vis = False
            if wi - self._box_width >= 0:
                visited[wi - self._box_width] = True
                vis = True
            if wi + self._box_width >= 0:
                visited[wi - self._box_width] = True
                vis = True
            if vis:
                return
        ei = i + 1
        if ei < self._size and ei % self._box_width != 0 and maze[ei] <= 0:
            vis = False
            if ei - self._box_width >= 0:
                visited[ei - self._box_width] = True
                vis = True
            if wi + self._box_width >= 0:
                visited[ei - self._box_width] = True
                vis = True
            if vis:
                return
        si = i - self._box_width
        if si >= 0 and maze[si] <= 0:
            vis = False
            if si - 1 >= 0 and (si - 1) % self._box_width != 0:
                visited[si - 1] = True
                vis = True
            if si + 1 < self._size and si % self._box_width != 0:
                visited[si + 1] = True
                vis = True
            if vis:
                return
        ni = i + self._box_width
        if ni < self._size and maze[ni] <= 0:
            vis = False
            if ni - 1 >= 0 and (ni - 1) % self._box_width != 0:
                visited[ni - 1] = True
                vis = True
            if ni + 1 < self._size and ni % self._box_width != 0:
                visited[ni + 1] = True
                vis = True
            if vis:
                return

func (ul *uciLogger) PrintPV(stats Stats, multiPV int, score int32, pv []Move) {
	// Write depth.
	now := time.Now()
	fmt.Fprintf(ul.buf, "info depth %d seldepth %d multipv %d ", stats.Depth, stats.SelDepth, multiPV)

	// Write score.
	if score > KnownWinScore {
		fmt.Fprintf(ul.buf, "score mate %d ", (MateScore-score+1)/2)
	} else if score < KnownLossScore {
		fmt.Fprintf(ul.buf, "score mate %d ", (MatedScore-score)/2)
	} else {
		fmt.Fprintf(ul.buf, "score cp %d ", score)
	}

	// Write stats.
	elapsed := uint64(maxDuration(now.Sub(ul.start), time.Microsecond))
	nps := stats.Nodes * uint64(time.Second) / elapsed
	millis := elapsed / uint64(time.Millisecond)
	fmt.Fprintf(ul.buf, "nodes %d time %d nps %d ", stats.Nodes, millis, nps)

	// Write principal variation.
	fmt.Fprintf(ul.buf, "pv")
	for _, m := range pv {
		fmt.Fprintf(ul.buf, " %v", m.UCI())
	}
	fmt.Fprintf(ul.buf, "\n")

	ul.flush()
}

package com.github.design.flyweight;

import java.util.Vector;

public class LocationFractory {

  private final static int MAX_CAPACITY = 5;

  private static Vector sPool = new Vector<>(MAX_CAPACITY);

  /**
   * 提供从缓存池中获取对象的方法
   */
  public static ILocation obtain() {
    ILocation location;
    if (sPool.size() > 0) {
      // TODO: 2020-03-10 判定缓存中的对象是否在使用中，不再使用中则返回。
      location = sPool.remove(0);
    } else {
      location = new Location();
      // 缓存对象
      if (sPool.size() < MAX_CAPACITY) {
        sPool.add(location);
      }
    }
    return location;
  }
}

