def collect_images(args):
    from settings import TARGET_DIRECTORY as source_dir 
    target_dir = args.target if os.path.isabs(args.target) else os.path.join(source_dir, args.target)
    if os.path.isdir(source_dir):
        if os.path.isdir(target_dir) == False:
            os.makedirs(target_dir)
        if args.purge:
            g = glob(os.path.join(target_dir, "*"))
            count = len(g)
            if count > 0:
                if args.silent == False:
                    print("All files in target directory {} will be deleted.".format(
                        target_dir))
                    print("Do you want to continue? (y/n)")
                    if input().lower() != 'y':
                        print("Operation cancelled.")
                        return
                for file in g:
                    os.remove(file)
        pattern = os.path.join(source_dir, args.subdir, "*{:+d}.jpg".format(args.offset))
        files = sorted(glob(pattern), key=os.path.getmtime)
        count = len(files)
        perform_operation = shutil.copyfile if args.copy else os.symlink
        if count > 0:
            for index, path in enumerate(files):
                target_path = os.path.join(target_dir, "{:d}.jpg".format(index))
                print(target_path)
                perform_operation(path, target_path)
            if args.copy:
                print("Successfully copied {} files to {}.".format(count, target_dir))
            else:
                print("Successfully created {} symlinks to {}.".format(count, target_dir))
        else:
            print("No files found to be processed.")
    else:
        print("Source directory defined in settings does not exist.".format(source_dir))

import com.google.gson.Gson;
import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonSerializationContext;
import com.google.gson.JsonSerializer;
import com.google.gson.reflect.TypeToken;

import timber.log.Timber;

import java.lang.reflect.Type;

public class ClassHierarchyAdapter<T> implements JsonSerializer<T>, JsonDeserializer<T> {

    private final Class<T> baseClass;

    public ClassHierarchyAdapter(Class<T> baseClass) {
        this.baseClass = baseClass;
    }

    @Override
    public JsonElement serialize(T src, Type typeOfSrc, JsonSerializationContext context) {
        JsonObject json = new JsonObject();
        json.addProperty("__class__", src.getClass().getName());
        json.add("data", context.serialize(src));
        return json;
    }

    @Override
    public T deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
        JsonObject jsonObject = json.getAsJsonObject();
        String className = jsonObject.get("__class__").getAsString();
        JsonElement data = jsonObject.get("data");

        try {
            Class<?> clazz = Class.forName(className);
            if (!baseClass.isAssignableFrom(clazz)) {
                throw new JsonParseException("Invalid class: " + className);
            }
            return context.deserialize(data, clazz);
        } catch (ClassNotFoundException e) {
            Timber.e(e, "Error deserializing object");
            throw new JsonParseException("Class not found: " + className, e);
        } catch (Exception e) {
            Timber.e(e, "Error deserializing object");
            throw new JsonParseException("Error deserializing object", e);
        }
    }
}

