int stringToInt(const std::string& str) {
    int sign = 1;
    int result = 0;
    int i = 0;
    int n = str.length();

    // Skip leading whitespace
    while (i < n && std::isspace(str[i])) {
        i++;
    }

    // Determine sign
    if (i < n && (str[i] == '+' || str[i] == '-')) {
        sign = (str[i] == '-') ? -1 : 1;
        i++;
    }

    // Parse numeric part
    while (i < n && std::isdigit(str[i])) {
        int digit = str[i] - '0';

        // Overflow check
        if (result > INT_MAX / 10 || (result == INT_MAX / 10 && digit > 7)) {
            return (sign == 1) ? INT_MAX : INT_MIN;
        }

        result = result * 10 + digit;
        i++;
    }

    return result * sign;
}

def factrize(x):
	f = {}
	tmp = x
	i = 2
	while i ** 2 <= tmp:
		cnt = 0
		while tmp % i == 0:
			cnt += 1
			tmp = tmp // i
		if cnt > 0:
			f[i] = cnt
		i += 1
	if tmp != 1 or f == {}:
		f[tmp] = 1
	return f
