function removePipelineExtras(object) {
    if (defined(object) && typeof object === 'object') {
        if (defined(object.extras) && defined(object.extras._pipeline)) {
            delete object.extras._pipeline;
            if (Object.keys(object.extras).length === 0) {
                delete object.extras;
            }
        }
        for (var propertyId in object) {
            if (object.hasOwnProperty(propertyId)) {
                removePipelineExtras(object[propertyId]);
            }
        }
    }
    return object;
}

void project_regions_along_parameters(list l_reg, list l_param)
{
    debug_on("REGIONS_OPERATORS_DEBUG_LEVEL");
    debug_regions_consistency(l_reg);
    if (must_regions_p())
    {
      FOREACH(EFFECT, reg, l_reg) {
	if(store_effect_p(reg))
	    region_exact_projection_along_parameters(reg, l_param);
	}
    }
    else
    {
      FOREACH(EFFECT, reg, l_reg) {
	if(store_effect_p(reg))
	    region_non_exact_projection_along_parameters(reg, l_param);
	}
    }
    debug_regions_consistency(l_reg);
    debug_off();
}

