def can(m, a, b):
	mini = min(a, b)
	maxi = max(a, b)
	if m <= mini and maxi - 2 * m >= 0:
		return True
	return False

def maxteams(a, b):
	lb = 0
	ub = 1000000000
	while lb <= ub:
		mid = lb + (ub - lb) // 2
		if can(mid, a, b):
			if can(mid + 1, a, b) == False:
				return mid
			else:
				lb = mid + 1
		else:
			ub = mid - 1
	return 0
