def verify_data(conn, table, pubkey, benchmark=False, include_table=False, conf=VisibilityFieldConfig()):
    success = True
    count = 0
    verifier = AccumuloVerifier(pubkey, conf=conf)
    if benchmark:
        print "Starting verification..."
        start = time.clock()
    for entry in conn.scan(table):
        count += 1
        try:
            if include_table:
                verifier.verify_entry(entry, table)
            else:
                verifier.verify_entry(entry)
        except VerificationException as ve:
            print "Verification error:", ve.msg
            success = False
    if benchmark:
        print "Verification finished!"
        end = time.clock()
    if success and count > 0:
        print "Verification of all (%d) entries succeeded." %count
    elif count <= 0:
        print "WARNING: no entries to verify"
    else:
        print "FAILURE: some entries failed to verify."
    if benchmark:
        return (success, start, end)
    else:
        return success

public boolean createWatermarkedDerivative( String src, String dst, String watermark )
            throws Exception
    {
        if (StringUtils.isBlank(watermark)) {
            watermark = defaultImageWatermark();
        }
        ArrayList<String> cmd = new ArrayList<String>();
        cmd.add( command );
        cmd.add( src );            
        cmd.add( "(" );
        cmd.add( watermark ); 
        cmd.add( "-background" );  
        cmd.add( "none" );
        BufferedImage img = ImageIO.read(new File(src));
        int iw = img.getWidth();
        int ih = img.getHeight();
        BufferedImage imgWatermark = ImageIO.read(new File(watermark));
        int iwWatermark = imgWatermark.getWidth();
        String gravity = "South";
        if (iw < ih) {
            gravity = "West";
            if (iwWatermark > ih) {
                cmd.add( "-geometry" ); 
                cmd.add( ih*100/iwWatermark + "%" );
            }
            cmd.add( "-rotate" );   
            cmd.add( "90" );
        } else if (iwWatermark > iw) {
            cmd.add( "-geometry" ); 
            cmd.add( iw*100/iwWatermark + "%" );
        }
        cmd.add( ")" );
        cmd.add( "-gravity" );       position
        cmd.add( gravity );
        cmd.add( "-compose" );      
        cmd.add( "over" );
        cmd.add( "-composite" );    
        cmd.add( dst );             
        return execute(cmd);
    }

public static Tuple<Dictionary<string, AdalUserInfo>, List<AdalUserInfo>> GetAllAdalUsersForMsal
            (ILegacyCachePersistence legacyCachePersistence, string clientId)
        {
            Dictionary<string, AdalUserInfo> clientInfoToAdalUserMap = new Dictionary<string, AdalUserInfo>();
            List<AdalUserInfo> adalUsersWithoutClientInfo = new List<AdalUserInfo>();
            try
            {
                IDictionary<AdalTokenCacheKey, AdalResultWrapper> dictionary =
                    AdalCacheOperations.Deserialize(legacyCachePersistence.LoadCache());
                List<KeyValuePair<AdalTokenCacheKey, AdalResultWrapper>> listToProcess =
                    dictionary.Where(p =>
                        p.Key.ClientId.Equals(clientId, StringComparison.OrdinalIgnoreCase)).ToList();
                foreach (KeyValuePair<AdalTokenCacheKey, AdalResultWrapper> pair in listToProcess)
                {
                    if (!string.IsNullOrEmpty(pair.Value.RawClientInfo))
                    {
                        clientInfoToAdalUserMap[pair.Value.RawClientInfo] = pair.Value.Result.UserInfo;
                    }
                    else
                    {
                        adalUsersWithoutClientInfo.Add(pair.Value.Result.UserInfo);
                    }
                }
            }
            catch (Exception ex)
            {
                CoreLoggerBase.Default.WarningPiiWithPrefix(ex, "An error occurred while reading accounts in ADAL format from the cache for MSAL. " +
                             "For details please see https://aka.ms/net-cache-persistence-errors. ");
                return Tuple.Create(new Dictionary<string, AdalUserInfo>(), new List<AdalUserInfo>());
            }
            return Tuple.Create(clientInfoToAdalUserMap, adalUsersWithoutClientInfo);
        }

public void CreateListing(Address contract, ulong tokenId)
    {
        ulong listingID = GenerateNewListingID();
        Assert(ContractOwner == GetTokenOwner(contract, tokenId), "The exchange contract is not owner of the token.");
        var listing = GetListing(contract, tokenId);
        Assert(!listing.IsActive, "The token is already on listing.");
        listing = new ListingInfo
        {
            ListingID = listingID,
            Seller = Message.Sender,
            Contract = contract,
            TokenId = tokenId,
            IsActive = true
        };
        SetListing(contract, tokenId, listing);
        Log(new LogMessage { Action = "AcceptOffer", Message = "Successfully created listing" });
    }

