private Dimension calculateProperDimension(Dimension sourceDimension, Dimension destinationDimension) {
		Dimension newDimension = new Dimension();
		newDimension.setvSize(destinationDimension.getvSize());
		int newHsize = destinationDimension.getvSize() * sourceDimension.gethSize() / sourceDimension.getvSize();
		newDimension.sethSize(newHsize);
		newDimension.setvPos(0);
		int newHpos = (destinationDimension.gethSize() - newHsize) / 2;
		newDimension.sethPos(newHpos);
		if (newDimension.gethSize() > destinationDimension.gethSize() || newDimension.getvSize() > destinationDimension.getvSize()) {
			newDimension = new Dimension();
			newDimension.sethSize(destinationDimension.gethSize());
			int newVsize = destinationDimension.gethSize() * sourceDimension.getvSize() / sourceDimension.gethSize();
			newDimension.setvSize(newVsize);
			newDimension.sethPos(0);
			int newVPos = (destinationDimension.getvSize() - newVsize) / 2;
			newDimension.setvPos(newVPos);
		}
		return newDimension;
	}

public void reset(Map<String, Object> options)  {
        _options = options;
        _nodeKey    = _seqComp.getNodeKey();
        _dataObject = _seqComp.getDataObject();
        ArrayList<IConfigBuilder> childBuilders;
        List<ISPSeqComponent> childList = _seqComp.getSeqComponents();
        if (childList == null || (childList.size() == 0)) {
            childBuilders = new ArrayList<>(0);
        } else {
            childBuilders = new ArrayList<>(childList.size());
            for (ISPSeqComponent seqComp: childList) {
                IConfigBuilder cb = (IConfigBuilder) seqComp.getClientData(IConfigBuilder.USER_OBJ_KEY);
                if (cb != null) {
                    childBuilders.add(cb);
                }
            }
            childBuilders.trimToSize();
        }
        _childBuilders = childBuilders;
        _firstChildBuilder();
        thisReset(_options);
        _firstTime = true;
        _isReset = true;
        _applyThisIterator = thisHasNext();
    }

def add_to_graph(graph_str, wf, parent, children):
        _parent = parent.replace(' ', '_').replace('-', '_')
        for n in children:
            _n = n.replace(' ', '_').replace('-', '_')
            graph_str += "  {} -> {};\n".format(_parent, _n)
            for M in wf.get_action(n).get('next', []):
                graph_str = add_to_graph(graph_str, wf, n, [M])
        return graph_str

namespace YGOCore
{
    public static class Password
    {
        public static string OnlyName(string namepassword)
        {
            if (string.IsNullOrEmpty(namepassword))
            {
                return namepassword;
            }

            string[] parts = namepassword.Split('$');
            return parts[0].Trim();
        }

        public static string GetPwd(string namepassword)
        {
            if (string.IsNullOrEmpty(namepassword))
            {
                return namepassword;
            }

            int index = namepassword.IndexOf('$');
            if (index > 0 && index < namepassword.Length - 1)
            {
                return namepassword.Substring(index + 1).Trim();
            }

            return string.Empty;
        }
    }
}

