import com.rbnb.sapi.*;
import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
import javax.swing.event.*;

public class DataExporter extends JFrame implements ActionListener, Runnable {
    private JComboBox<String> channelsList;
    private JCheckBox checkDataType;
    private JButton startButton, stopButton;
    private JProgressBar progressBar;
    private JLabel statusMessage;
    private boolean isExporting = false;
    private Thread exportThread;
    private RBNBReader rbnb;
    private DataFileWriter writer;

    public DataExporter() {
        // setup GUI components
        setLayout(new GridLayout(3, 2));
        channelsList = new JComboBox<String>();
        checkDataType = new JCheckBox("Select Data Type");
        startButton = new JButton("Start Export");
        stopButton = new JButton("Stop Export");
        progressBar = new JProgressBar();
        statusMessage = new JLabel();
        startButton.addActionListener(this);
        stopButton.addActionListener(this);

        // add GUI components to frame
        add(channelsList);
        add(checkDataType);
        add(startButton);
        add(stopButton);
        add(progressBar);
        add(statusMessage);

        pack();
    }

    public void actionPerformed(ActionEvent e) {
        if (e.getSource() == startButton) {
            if (!isExporting) {
                isExporting = true;
                startButton.setEnabled(false);
                stopButton.setEnabled(true);
                exportThread = new Thread(this);
                exportThread.start();
            }
        } else if (e.getSource() == stopButton) {
            if (isExporting) {
                isExporting = false;
                startButton.setEnabled(true);
                stopButton.setEnabled(false);
                exportThread.interrupt();
            }
        }
    }

    public void run() {
        try {
            // setup server connection and file writer 
            // implement this based on your actual requirement
            rbnb = new RBNBReader("channel_list");
            writer = new DataFileWriter("outputFile");

            int dataType = checkDataType.isSelected() ? 1 : 0; // change this based on your actual datatype
            String selectedChannel = (String) channelsList.getSelectedItem();

            while (isExporting) {
                // read from server and write to file
                // implement this based on your actual requirement
                Data[] data = rbnb.getData(selectedChannel, dataType); 
                writer.write(data);

                // update progress and status message 
                // implement this based on your actual requirement
                progressBar.setValue(progressBar.getValue() + 1);
                statusMessage.setText("Exported " + progressBar.getValue() + " items.");
            }
        } catch (ServerError e) {
            UIUtilities.error(this, "Server Error: " + e.getMessage());
        } catch (AcqError e) {
            UIUtilities.error(this, "Acquisition Error: " + e.getMessage());
        } catch (FileError e) {
            UIUtilities.error(this, "File Error: " + e.getMessage());
        } catch (Exception e) {
            UIUtilities.error(this, "Error: " + e.getMessage());
        } finally {
            if (rbnb != null) rbnb.closeRBNBConnection();
            if (writer != null) writer.closeFile();
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            public void run() {
                new DataExporter().setVisible(true);
            }
        });
    }
}

import java.util.Arrays;
import java.util.function.IntUnaryOperator;

class Solution {
    public static void main(String[] args) {
        new Solution().numberOfCombinations("327");
    }

    int mod = (int) 1e9 + 7;

//    public void update(long[] data, int l, int r, long x) {
//        if (l > r || l >= data.length) {
//            return;
//        }
//        data[l] += x;
//        if (r + 1 < data.length) {
//            data[r + 1] -= x;
//        }
//    }

    int[][] z;

    public int compare(int l, int len) {
        int ll = l + len;
        int first = z[l][ll - l];
        if (first >= len) {
            return 0;
        }
        return s[l + first] - s[ll + first];
    }

    char[] s;

    public int numberOfCombinations(String num) {
        s = num.toCharArray();
        int n = s.length;
        z = new int[n][];
        for (int i = 0; i < n; i++) {
            int finalI = i;
            z[i] = ZAlgorithm.generate(j -> s[finalI + j], n - i);
        }
        int[][] dp = new int[n][n];
        int[][] delta = new int[n][n];
        if (s[0] == '0') {
            return 0;
        }
        delta[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                delta[i][j] += delta[i][j - 1];
                if(delta[i][j] >= mod){
                    delta[i][j] -= mod;
                }
            }
            for (int j = 0; j < n; j++) {
                dp[i][j] = delta[i][j];
                if (dp[i][j] == 0 || j + 1 >= n || s[j + 1] == '0') {
                    continue;
                }
                int len = j - i + 1;
                int ll = j + 1;
                int rr = j + len;
                if (rr < n && compare(i, len) > 0) {
                    rr++;
                }
                if (rr < n) {
                    delta[ll][rr] += dp[i][j];
                    if(delta[ll][rr] >= mod){
                        delta[ll][rr] -= mod;
                    }
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans += dp[i][n - 1];
        }
        ans %= mod;
        if (ans < 0) {
            ans += mod;
        }

        boolean dbg = false;
        if (dbg) {
            System.out.println(Arrays.deepToString(dp));
            System.out.println(Arrays.deepToString(delta));
        }
        return (int) ans;
    }
}

class ZAlgorithm {
    public static int[] generate(IntUnaryOperator s, int n) {
        int[] ans = new int[n];
        generate(ans, s, n);
        return ans;
    }

    /**
     * Provide sequence : s(0), s(1), ... , s(n - 1), calculate their z function.<br>
     * z[i]: The longest substring start at i which is also a prefix of s
     */
    public static void generate(int[] z, IntUnaryOperator s, int n) {
        if (n == 0) {
            return;
        }

        int l = 0;
        int r = -1;
        z[0] = n;
        for (int i = 1; i < n; i++) {
            if (r < i) {
                l = r = i;
            } else {
                int t = i - l;
                int k = r - i + 1;
                if (z[t] < k) {
                    z[i] = z[t];
                    continue;
                }
                l = i;
                r++;
            }
            while (r < n && s.applyAsInt(r - l) == s.applyAsInt(r)) {
                r++;
            }
            r--;
            z[i] = r - l + 1;
        }
    }
}

import os, sys
from io import BytesIO, IOBase
from collections import Counter

def main():
	for _ in range(int(input())):
		n = int(input())
		w = Counter(map(int, input().split()))
		ans = 0
		for i in range(2, 101):
			ans1 = 0
			for x in range(1, i // 2 + 1):
				if w.get(i - x) and w.get(x):
					if 2 * x == i:
						ans1 += w[x] // 2
					else:
						ans1 += min(w[x], w[i - x])
			ans = max(ans, ans1)
		print(ans)
BUFSIZE = 8192

class FastIO(IOBase):
	newlines = 0

	def __init__(self, file):
		self._fd = file.fileno()
		self.buffer = BytesIO()
		self.writable = 'x' in file.mode or 'r' not in file.mode
		self.write = self.buffer.write if self.writable else None

	def read(self):
		while True:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			if not b:
				break
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines = 0
		return self.buffer.read()

	def readline(self):
		while self.newlines == 0:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			self.newlines = b.count(b'\n') + (not b)
			ptr = self.buffer.tell()
			(self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
		self.newlines -= 1
		return self.buffer.readline()

	def flush(self):
		if self.writable:
			os.write(self._fd, self.buffer.getvalue())
			(self.buffer.truncate(0), self.buffer.seek(0))

class IOWrapper(IOBase):

	def __init__(self, file):
		self.buffer = FastIO(file)
		self.flush = self.buffer.flush
		self.writable = self.buffer.writable
		self.write = lambda s: self.buffer.write(s.encode('ascii'))
		self.read = lambda : self.buffer.read().decode('ascii')
		self.readline = lambda : self.buffer.readline().decode('ascii')
(sys.stdin, sys.stdout) = (IOWrapper(sys.stdin), IOWrapper(sys.stdout))
input = lambda : sys.stdin.readline().rstrip('\r\n')
main()

