var ShareComponent = Backbone.View.extend({
    template: _.template(`
        <div class="share-component">
            <button class="share-twitter" title="Share on Twitter">Twitter</button>
            <button class="share-facebook" title="Share on Facebook">Facebook</button>
            <button class="share-diaspora" title="Share on Diaspora">Diaspora</button>
            <button class="share-email" title="Share via Email">Email</button>
        </div>
    `),

    initialize: function(options) {
        if (!options.model) {
            throw new Error("A configuration model is required.");
        }
        this.model = options.model;
        this.listenTo(this.model, 'change', this.render);
        this.render();
    },

    events: {
        'click .share-twitter': 'shareOnTwitter',
        'click .share-facebook': 'shareOnFacebook',
        'click .share-diaspora': 'shareOnDiaspora',
        'click .share-email': 'shareViaEmail'
    },

    render: function() {
        this.$el.html(this.template());
        return this;
    },

    shareOnTwitter: function() {
        this.openShareWindow(`https://twitter.com/intent/tweet?url=${encodeURIComponent(this.model.get('url'))}`);
    },

    shareOnFacebook: function() {
        this.openShareWindow(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(this.model.get('url'))}`);
    },

    shareOnDiaspora: function() {
        this.openShareWindow(`https://share.diasporafoundation.org/?url=${encodeURIComponent(this.model.get('url'))}`);
    },

    shareViaEmail: function() {
        const subject = encodeURIComponent(this.model.get('subject') || 'Check this out!');
        const body = encodeURIComponent(this.model.get('body') || `Check this link: ${this.model.get('url')}`);
        window.location.href = `mailto:?subject=${subject}&body=${body}`;
    },

    openShareWindow: function(url) {
        window.open(url, '_blank', 'width=600,height=400');
    }
});

