                                origin_one.GetURL("/")));
}

class Solution:
    def maxTotalFruits(self, fruits: List[List[int]], startPos: int, k: int) -> int:
        n = len(fruits)
        ans = 0
        pos = []
        for p, c in fruits:
            pos.append(p)

        id_r = bisect.bisect_left(pos, startPos)
        right = []
        if id_r < n and id_r >= 0 and fruits[id_r][0] - startPos <= k:
            tmp = fruits[id_r][0] - startPos
            right.append((tmp, fruits[id_r][1]))
            for i in range(id_r+1, n):
                tmp += fruits[i][0] - fruits[i-1][0]
                if tmp > k:
                    break
                right.append((tmp, right[-1][1] + fruits[i][1]))

        left = []
        id_l = bisect.bisect_right(pos, startPos) - 1
        if id_l >= 0 and id_l < n and startPos - fruits[id_l][0] <= k:
            tmp = startPos - fruits[id_l][0]
            left.append((tmp, fruits[id_l][1]))
            for i in range(id_l-1, -1, -1):
                tmp += fruits[i+1][0] - fruits[i][0]
                if tmp > k:
                    break
                left.append((tmp, left[-1][1] + fruits[i][1]))

        sub = 0
        if left and left[0][0] == 0:
            sub = left[0][1]
        for left_dis, left_v in left:
            ans = max(ans, left_v)
            dis = k - 2*left_dis
            if dis > 0:
                p = bisect.bisect_right(right, (dis, float('inf'))) - 1
                if p >= 0 and p < len(right):
                    ans = max(ans, left_v + right[p][-1] - sub)

        for right_dis, right_v in right:
            ans = max(ans, right_v)
            dis = k - 2*right_dis
            if dis > 0:
                p = bisect.bisect_right(left, (dis, float('inf'))) - 1
                if p >= 0 and p < len(left):
                    ans = max(ans, right_v + left[p][-1] - sub)

        return ans

public abstract partial class TranslatorBase : ITranslator
