        internal const string DATE = "date";
        internal const string TIME = "time";
        internal const string DATETIME = "dateTime";
        internal const string TIMESTAMP = "timeStamp";
        #endregion Keys
        public TranslatorBase()
        {
            TypeMap = new Dictionary<string, string>
            {
                { "bool", "BOOL" },
                { "blob", "BLOB" },
                { "char", "CHAR" },
                { "text", "TEXT" },
                { "varchar", "VARCHAR" },
                { "int", "INT" },
                { "bigInt", "BIGINT" },
                { "mediumInt", "MEDIUMINT" },
                { "smallInt", "SMALLINT" },
                { "tinyInt", "TINYINT" },
                { "float", "FLOAT" },
                { "double", "DOUBLE" },
                { "decimal", "DECIMAL" },
                { "date", "DATE" },
                { "time", "TIME" },
                { "dateTime", "DATETIME" },
                { "timeStamp", "TIMESTAMP" },
            };
        }
        protected IDictionary<string, string> TypeMap { get; set; }
        public static string ConvertToString(SchemaType type)
        {
            switch (type)
            {
                default:
                    return null;
                case SchemaType.BOOL:
                    return BOOL;
                case SchemaType.BLOB:
                    return BLOB;
                case SchemaType.CHAR:
                    return CHAR;
                case SchemaType.TEXT:
                    return TEXT;
                case SchemaType.VARCHAR:
                    return VARCHAR;
                case SchemaType.INT:
                    return INT;
                case SchemaType.BIGINT:
                    return BIGINT;
                case SchemaType.MEDIUMINT:
                    return MEDIUMINT;
                case SchemaType.SMALLINT:
                    return SMALLINT;
                case SchemaType.TINYINT:
                    return TINYINT;
                case SchemaType.FLOAT:
                    return FLOAT;
                case SchemaType.DOUBLE:
                    return DOUBLE;
                case SchemaType.DECIMAL:
                    return DECIMAL;
                case SchemaType.DATE:
                    return DATE;
                case SchemaType.TIME:
                    return TIME;
                case SchemaType.DATETIME:
                    return DATETIME;
                case SchemaType.TIMESTAMP:
                    return TIMESTAMP;
            }
        }
        public virtual string ExpandVariables(string name) => name;
		public virtual string Escape(string objectName) => objectName;
        public virtual string ConvertToString(ReferentialAction action)
        {
            switch (action)
            {
                default:
                case ReferentialAction.Cascade:
                    return "CASCADE";
                case ReferentialAction.NoAction:
                    return "NO ACTION";
                case ReferentialAction.Restrict:
                    return "RESTRICT";
                case ReferentialAction.SetNull:
                    return "SET NULL";
                case ReferentialAction.SetDefault:
                    return "SET DEFAULT";
            }
        }
        public abstract string ConvertToString(DataType dataType);
        public virtual string GetDefaultValue(string typeName)
        {
            if (typeName == null) return NULL;
            switch (typeName)
            {
                default: return "''";
                case INT:
                case TINYINT:
                case SMALLINT:
                case MEDIUMINT:
                case BIGINT:
                case FLOAT:
                case DOUBLE:
                case DECIMAL:
                case BOOL: return "0";
            }
        }
        internal struct PlaceholderPattern
        {
            public const string NOW = @"(?i)\$\(now\)";
        }
    }

@com.gigaspaces.api.InternalApi
public class AesEncrypter {
    Cipher ecipher;
    Cipher dcipher;

    /**
     * Constructs an AES Encrypter instance with the provided secret key.
     *
     * @param key a secret key to use to construct the {@link Cipher}s needed to encrypt and
     *            decrypt.
     */
    public AesEncrypter(SecretKey key) {

        // Create an 8-byte initialization vector
        byte[] iv = new byte[]{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d,
                0x0e, 0x0f};

        AlgorithmParameterSpec paramSpec = new IvParameterSpec(iv);

        try {
            ecipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            dcipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

            // CBC requires an initialization vector
            ecipher.init(Cipher.ENCRYPT_MODE, key, paramSpec);
            dcipher.init(Cipher.DECRYPT_MODE, key, paramSpec);
        } catch (Exception e) {
            throw new EncodingException("Failed to create AES encrypter", e);
        }
    }
}

def filter_dataframe(df, start_date_dt, end_date_dt, lat_min, lat_max, lon_min, lon_max, ground_stations=None):
    dff = df[
        (df["timestamp"].dt.date >= dt.date(start_date_dt.year, start_date_dt.month, start_date_dt.day))
        & (df["timestamp"].dt.date <= dt.date(end_date_dt.year, end_date_dt.month, end_date_dt.day))
            ]
    if (lat_min != -90) or (lat_max != 90):
        dff = dff[
            (dff["lat"] >= lat_min)
            & (dff["lat"] <= lat_max)
               ]
    if (lon_min != -90) or (lon_max != 90):
        dff = dff[
            (dff["lon"] >= lon_min)
            & (dff["lon"] <= lon_max)
                ]
    if (ground_stations is not None) and (ground_stations != []):
        dff = dff[
            (dff["station_name"].isin(ground_stations))
            ]
    return dff

def _get_feature_parser(shape, dtype, compress_image=False):
  shape = _validate_shape(shape)
  dtype = _validate_dtype(dtype)
  if compress_image and len(shape) == 3 and dtype == tf.uint8:
    return (tf.io.FixedLenFeature(shape=[], dtype=tf.string), tf.io.decode_jpeg)
  if dtype == tf.float32:
    return (tf.io.FixedLenFeature(shape=shape, dtype=tf.float32), lambda x: x)
  elif dtype == tf.int64:
    return (tf.io.FixedLenFeature(shape=shape, dtype=tf.int64), lambda x: x)
  def decode(x):
    return tf.reshape(tf.io.decode_raw(x, dtype), shape)
  return (tf.io.FixedLenFeature(shape=[], dtype=tf.string), decode)

def _validate_dep_overrides_format(self, key):
        if not self.data.get(key):
            return
        invalid_override_msg = (
            'The "{}" parameter must be an object with the keys as module '
            "names and the values as arrays of streams".format(key)
        )
        if not isinstance(self.data[key], dict):
            raise ValidationError(invalid_override_msg)
        for streams in self.data[key].values():
            if not isinstance(streams, list):
                raise ValidationError(invalid_override_msg)
            for stream in streams:
                if not isinstance(stream, string_types):
                    raise ValidationError(invalid_override_msg)

