def home():
    user = current_user()
    if not user:
        return redirect(url_for('eproms.landing'))
    if (not Coredata().initial_obtained(user) or
            'next' in session and session['next']):
        return next_after_login()
    if user.has_role(ROLE.STAFF_ADMIN.value):
        return redirect(url_for('staff.staff_index'))
    if user.has_role(
            ROLE.INTERVENTION_STAFF.value,
            ROLE.STAFF.value):
        return redirect(url_for('patients.patients_root'))
    if user.has_role(ROLE.CLINICIAN.value):
        return redirect(url_for('patients.patients_substudy'))
    if user.has_role(ROLE.RESEARCHER.value):
        return redirect(url_for('portal.research_dashboard'))
    if not user.has_role(ROLE.PATIENT.value):
        abort(404, "no /home view for user with roles: {}".format(
            str([r.name for r in user.roles])))
    interventions = Intervention.query.order_by(
        Intervention.display_rank).all()
    consent_agreements = {}
    return render_template(
        'eproms/portal.html',
        user=user,
        assessment_engine_view=assessment_engine_view,
        interventions=interventions,
        consent_agreements=consent_agreements)

public static <T extends XSerializable> List<T> parseList(XElement container, 
            String itemName, Supplier<T> creator) {
        List<T> result = new ArrayList<>();
        for (XElement e : container.childrenWithName(itemName)) {
            T obj = creator.get();
            obj.load(e);
            result.add(obj);
        }
        return result;
    }

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def sortedMerge(head1, head2):
    if not head1:
        return head2
    if not head2:
        return head1

    if head1.data < head2.data:
        new_head = head1
        new_head.next = sortedMerge(head1.next, head2)
    else:
        new_head = head2
        new_head.next = sortedMerge(head1, head2.next)
    return new_head

def printList(node):
    while node:
        print(node.data, end=" ")
        node = node.next
    print()

# Driver code
if __name__ == "__main__":
    head1 = Node(5)
    head1.next = Node(10)
    head1.next.next = Node(15)
    head1.next.next.next = Node(40)

    head2 = Node(2)
    head2.next = Node(3)
    head2.next.next = Node(20)

    head = sortedMerge(head1, head2)
    printList(head)

class OrgService extends AmplifyServiceDispatcher {
	/**
	 * Wires up the organization service endpoints.
