protected async Task TransitionAsync(int stateHash, int layer)
        {
            //Ensure Animator is Initialized
            while (Application.isPlaying && (!animator.isInitialized || !animator.gameObject.activeInHierarchy))
            {
                await Task.Yield();
            }

            if (animator != null)
            {
                animator.Play(stateHash);
            }

            //Wait until we're in the target state
            while (Application.isPlaying && animator.GetCurrentAnimatorStateInfo(layer).shortNameHash != stateHash)
            {
                await Task.Yield();
            }

            float normalizedTime = 0;
            while (Application.isPlaying && normalizedTime < 1 && !Mathf.Approximately(normalizedTime, 1f))
            {
                var info = animator.GetCurrentAnimatorStateInfo(0);
                if (normalizedTime <= info.normalizedTime)
                {
                    normalizedTime = info.normalizedTime;
                }
                else
                {
                    //If suddenly normalized time is less than 1 we've looped back around or something.
                    normalizedTime = 1f;
                }

                await Task.Yield();
            }
        }

private void modifyDatastreamControlGroupAction(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String actionLabel = "modifying datastream control group";
        Context context =
                ReadOnlyContext.getContext(Constants.HTTP_REQUEST.REST.uri,
                                           request);
        File fedoraHome = new File(Constants.FEDORA_HOME);
        if (!Server.hasInstance(fedoraHome)) {
            throw new Unavailable503Exception(request,
                                              actionLabel,
                                              "server not available",
                                              new String[0]);
        }
        Server server = null;
        try {
            server = Server.getInstance(fedoraHome, false);
        } catch (Throwable t) {
            throw new InternalError500Exception(request,
                                                actionLabel,
                                                "error performing action0",
                                                new String[0]);
        }
        if (server == null) {
            throw new InternalError500Exception(request,
                                                actionLabel,
                                                "error performing action1",
                                                new String[0]);
        }
        ManagementModule apimDefault = (ManagementModule) server.getModule("org.fcrepo.server.management.Management");
        String pid = request.getParameter("pid");
        String dsID = request.getParameter("dsID");
        String controlGroup = request.getParameter("controlGroup");
        boolean addXMLHeader = getParameterAsBoolean(request, "addXMLHeader", false);
        boolean reformat = getParameterAsBoolean(request, "reformat", false);
        boolean setMIMETypeCharset = getParameterAsBoolean(request, "setMIMETypeCharset", false);
        String[] datastreams = dsID.split(",");
        boolean singlePID;
        Iterable<String> pids = null;
        if (pid.startsWith(PROTOCOL_FILE)) {
            File pidFile = new File(pid.substring(PROTOCOL_FILE.length()));
            pids = new PIDStreamIterableWrapper(new FileInputStream(pidFile));
            singlePID = false;
        } else { 
            String[] pidList = pid.split(",");
            pids = new ArrayList<String>(Arrays.asList(pidList));
            singlePID = (pidList.length == 1);
        }
        try {
            response.setStatus(HttpServletResponse.SC_OK);
            response.setCharacterEncoding("UTF-8");
            PrintWriter pw = response.getWriter();
            if (singlePID && datastreams.length == 1) {
                response.setContentType("text/xml; charset=UTF-8");
                Date[] versions = apimDefault.modifyDatastreamControlGroup(context, pid, dsID, controlGroup, addXMLHeader, reformat, setMIMETypeCharset);
                pw.write("<versions>\n");
                    for (Date version : versions) {
                        pw.write("<version>" + version.toString() + "</version>\n");
                    }
                pw.write("</versions>\n");
            } else { 
                response.setContentType("text/plain; charset=UTF-8");
                ServerUtilitySerializer ser = new ServerUtilitySerializer(pw);
                for (String curpid : pids) {
                    ser.startObject(curpid);
                    for (String curdsID : datastreams) {
                        ser.startDatastream(curdsID);
                        Date[] versions;
                        try {
                            versions = apimDefault.modifyDatastreamControlGroup(context, curpid, curdsID, controlGroup, addXMLHeader, reformat, setMIMETypeCharset);
                        } catch (DatastreamNotFoundException e) {
                            versions = null;
                        }
                        ser.writeVersions(versions);
                        ser.endDatastream();
                    }
                    ser.endObject();
                }
                ser.finish();
            }
            pw.flush();
        } catch (ObjectNotFoundException e) {
            logger.error("Object not found: " + pid + " - " + e.getMessage());
            throw new NotFound404Exception(request,
                                           actionLabel,
                                           e.getMessage(),
                                           new String[0]);
        } catch (DatastreamNotFoundException e) {
            logger.error("Datastream not found: " + pid + "/" + dsID + " - " + e.getMessage());
            throw new NotFound404Exception(request,
                                           actionLabel,
                                           e.getMessage(),
                                           new String[0]);
        } catch (GeneralException e) {
            logger.error(e.getMessage());
            throw new InternalError500Exception(request,
                                                actionLabel,
                                                e.getMessage(),
                                                new String[0]);
        } catch (AuthzOperationalException aoe) {
            throw new Forbidden403Exception(request,
                                            actionLabel,
                                            "authorization failed",
                                            new String[0]);
        } catch (AuthzDeniedException ade) {
            throw new Forbidden403Exception(request,
                                            actionLabel,
                                            "authorization denied",
                                            new String[0]);
        } catch (AuthzPermittedException ape) {
            throw new Continue100Exception(request,
                                           actionLabel,
                                           "authorization permitted",
                                           new String[0]);
        } catch (ServerException e) {
            logger.error(e.getMessage(),e);
            throw new InternalError500Exception(request,
                                                actionLabel,
                                                "Unexpected error: " + e.getMessage(),
                                                new String[0]);
        }
    }

const WebSocket = require('ws');

class WebSocketClient {
  constructor(url, options) {
    this.ws = new WebSocket(url);
    this.counter = 0;
    this.results = {};
    this.options = options;
  }

  connect() {
    this.ws.on('open', () => {
      console.log('WebSocket client connected to', this.ws.url);
    });

    this.ws.on('message', (message) => {
      const data = JSON.parse(message);
      const { id, result, error } = data;

      if (this.results[id]) {
        if (result) {
          this.results[id].resolve(result);
        } else if (error) {
          this.results[id].reject(error);
        }
        delete this.results[id];
      }
    });
  }

  sendRequest(pairCode, data) {
    const id = this.counter++;
    const promise = new Promise((resolve, reject) => {
      this.results[id] = { resolve, reject };
    });

    const message = JSON.stringify({ id, pairCode, data });
    this.ws.send(message);

    return promise;
  }

  static createClient(url, options) {
    return new WebSocketClient(url, options);
  }
}

module.exports = WebSocketClient;

public class InclusionList<T extends TypedLink> {

    private Set<String> requiredTerms, excludedTerms;
    private Set<T> requiredRelations, excludedRelations;

    public InclusionList() {
        this.requiredTerms = new HashSet<>();
        this.excludedTerms = new HashSet<>();
        this.requiredRelations = new HashSet<>();
        this.excludedRelations = new HashSet<>();
    }

    public InclusionList(Set<String> requiredTerms, Set<String> excludedTerms,
            Set<T> requiredRelations, Set<T> excludedRelations) {
        this.requiredTerms = requiredTerms;
        this.excludedTerms = excludedTerms;
        this.requiredRelations = requiredRelations;
        this.excludedRelations = excludedRelations;
    }

    public Set<String> getRequiredTerms() {
        return requiredTerms;
    }

    public Set<String> getExcludedTerms() {
        return excludedTerms;
    }

    public Set<T> getRequiredRelations() {
        return requiredRelations;
    }

    public Set<T> getExcludedRelations() {
        return excludedRelations;
    }

    public void setRequiredTerms(Set<String> requiredTerms) {
        this.requiredTerms = requiredTerms;
    }

    public void setExcludedTerms(Set<String> excludedTerms) {
        this.excludedTerms = excludedTerms;
    }

    public void setRequiredRelations(Set<T> requiredRelations) {
        this.requiredRelations = requiredRelations;
    }

    public void setExcludedRelations(Set<T> excludedRelations) {
        this.excludedRelations = excludedRelations;
    }

    public static <T extends TypedLink> InclusionList<T> from(List<Term> allTerms, SaffronGraph<T> kg) {

        Set<String> termAllowanceList = new HashSet<>();
        Set<String> termDenialList = new HashSet<>();

        for (Term term : allTerms) {
            if (term.getStatus().equals(Status.accepted)) {
                termAllowanceList.add(term.getString());

                if (term.getOriginalTerm() != null && !term.getString().equals(term.getOriginalTerm())) {
                    termDenialList.add(term.getOriginalTerm());
                }
            } else if (term.getStatus().equals(Status.rejected)) {
                termDenialList.add(term.getString());
            }
        }
        termDenialList.removeAll(termAllowanceList);

        return new InclusionList(termAllowanceList, termDenialList,
                kg.getRelationsByStatus(Status.accepted), new HashSet<TypedLink>());
    }
}

public boolean queueSpawn(RemoteEntity inEntity, Location inLocation, boolean inSetupGoals)
	{
		EntityLoadData spawnData = new EntityLoadData(inEntity, inLocation, inSetupGoals);
		if(this.canSpawnAt(inLocation))
		{
			this.spawn(spawnData);
			return false;
		}
		this.m_toSpawn.add(spawnData);
		return true;
	}

private int handleFor( ForStatement startNode, ASTNode endNode, int childnum)
	{
		int errno = 0;

		switch (childnum)
		{
			case 0: // init child: ExpressionList or null node
				if( endNode instanceof NullNode)
					startNode.addChild(endNode);
				else
					// Note: can only cast to Expression instead of the more specific ExpressionList
					// because in C world, a ForInit node is used instead (also an Expression)
					startNode.setForInitExpression((Expression)endNode);
				break;
			case 1: // cond child: ExpressionList or null node
				if( endNode instanceof NullNode)
					startNode.addChild(endNode);
				else
					// Note: can only cast to Expression instead of the more specific ExpressionList
					// because in C world, a Condition node is used instead (also an Expression)
					startNode.setCondition((Expression)endNode);
				break;
			case 2: // loop child: ExpressionList or null node
				if( endNode instanceof NullNode)
					startNode.addChild(endNode);
				else
					// Note: can only cast to Expression instead of the more specific ExpressionList
					// because in C world, an Expression node is used instead
					startNode.setForLoopExpression((Expression)endNode);
				break;
			case 3: // stmts child: Statement or Expression or null node
				if( endNode instanceof NullNode)
					startNode.addChild(endNode);
				else if( endNode instanceof Expression) // the child is an expression used as a statement
					startNode.setStatement(createExpressionStatement((Expression)endNode));
				else
					startNode.setStatement((Statement)endNode);
				break;

			default:
				errno = 1;
		}

		return errno;
	}

public int read(byte[] buf, int n) throws IOException {
            int wr = 0, wrOffset = 0;
            while (n > 0) {
                if (bufCount <= 0) {
                    int ret = getBody(inputStream);
                    if (ret < 0) throw new IOException("Ogg decoding error");
                    if (ret == 0) break;
                    bufCount = ret;
                    offset = 0;
                }
                int rd = (bufCount < n) ? bufCount : n;
                System.arraycopy(convBuf, offset, buf, wrOffset, rd);
                bufCount -= rd;
                offset += rd;
                wr += rd;
                wrOffset += rd;
                n -= rd;
            }
            return (wr <= 0) ? -1 : wr;
        }

void nfc_hal_prm_process_timeout(void* p_tle) {
  NFC_HAL_PRM_STATE("nfc_hal_prm_process_timeout");
  if (nfc_hal_cb.prm.state == NFC_HAL_PRM_ST_SPD_AUTH_DONE) {
    if (!(nfc_hal_cb.prm.flags & NFC_HAL_PRM_FLAGS_BCM20791B3)) {
      HAL_TRACE_ERROR0("Timeout waiting for RESET NTF after patch download");
      nfc_hal_prm_spd_handle_download_complete(NFC_HAL_PRM_ABORT_EVT);
    } else {
      nfc_hal_prm_nfcc_ready_to_continue();
    }
  } else if (nfc_hal_cb.prm.state == NFC_HAL_PRM_ST_SPD_GET_PATCH_HEADER) {
    HAL_TRACE_DEBUG0(
        "Delay after PreI2C patch download...proceeding to download firmware "
        "patch");
    nfc_hal_prm_spd_handle_next_patch_start();
  } else if (nfc_hal_cb.prm.state == NFC_HAL_PRM_ST_W4_GET_VERSION) {
    HAL_TRACE_DEBUG0("get patch version timeout???");
    nfc_hal_prm_spd_handle_download_complete(NFC_HAL_PRM_COMPLETE_EVT);
  } else {
    HAL_TRACE_ERROR1("Patch download: command timeout (state=%i)",
                     nfc_hal_cb.prm.state);
    nfc_hal_prm_spd_handle_download_complete(NFC_HAL_PRM_ABORT_EVT);
  }
  NFC_HAL_PRM_STATE("nfc_hal_prm_process_timeout");
}

public bool Remove(Interval<TKey> interval)
    {
        if (this.values.Count == 0 || this.Comparer.IsEmpty(interval)) return false;
        var (from, to) = this.IntersectingRange(interval);
        if (from == to) return false;
        if (to - from == 1)
        {
            var existing = this.values[from];
            var existingLower = this.intervalSelector(existing).Lower;
            var existingUpper = this.intervalSelector(existing).Upper;
            var lowerCompare = this.BoundComparer.Compare(existingLower, interval.Lower);
            var upperCompare = this.BoundComparer.Compare(existingUpper, interval.Upper);
            if (lowerCompare >= 0 && upperCompare <= 0)
            {
                this.values.RemoveAt(from);
            }
            else if (lowerCompare >= 0)
            {
                var newInterval = new Interval<TKey>(interval.Upper.Touching!, existingUpper);
                this.values[from] = this.intervalMover(existing, newInterval);
            }
            else if (upperCompare <= 0)
            {
                var newInterval = new Interval<TKey>(existingLower, interval.Lower.Touching!);
                this.values[from] = this.intervalMover(existing, newInterval);
            }
            else
            {
                var newInterval1 = new Interval<TKey>(existingLower, interval.Lower.Touching!);
                var newInterval2 = new Interval<TKey>(interval.Upper.Touching!, existingUpper);
                this.values[from] = this.intervalMover(existing, newInterval1);
                this.values.Insert(from + 1, this.intervalMover(existing, newInterval2));
            }
        }
        else
        {
            var lowerExisting = this.values[from];
            var upperExisting = this.values[to - 1];
            var lowerExistingLower = this.intervalSelector(lowerExisting).Lower;
            var upperExistingUpper = this.intervalSelector(upperExisting).Upper;
            var lowerCompare = this.BoundComparer.Compare(lowerExistingLower, interval.Lower);
            var upperCompare = this.BoundComparer.Compare(upperExistingUpper, interval.Upper);
            var deleteFrom = from;
            var deleteTo = to;
            if (lowerCompare < 0)
            {
                var newLower = new Interval<TKey>(lowerExistingLower, interval.Lower.Touching!);
                this.values[from] = this.intervalMover(lowerExisting, newLower);
                ++deleteFrom;
            }
            if (upperCompare > 0)
            {
                var newUpper = new Interval<TKey>(interval.Upper.Touching!, upperExistingUpper);
                this.values[to - 1] = this.intervalMover(upperExisting, newUpper);
                --deleteTo;
            }
            this.values.RemoveRange(deleteFrom, deleteTo - deleteFrom);
        }
        return true;
    }

public static void initialize(ilex.util.Logger ilexLogger, boolean _doForward, String ... paths)
	{
		if (initialized)
			return;
		initialized = true;
		doForward = _doForward;
		JavaLoggerAdapter.ilexLogger = ilexLogger;
		java.util.logging.Logger globalLogger = LogManager.getLogManager().getLogger(globalName);
		Handler handlers[] = globalLogger.getHandlers();
		while (handlers != null && handlers.length > 0)
		{
			globalLogger.removeHandler(handlers[0]);
			handlers = globalLogger.getHandlers();
		}
		globalLogger.addHandler(instance());
		globalLogger.setLevel(Level.ALL);
		for(String path : paths)
		{
			java.util.logging.Logger logger = java.util.logging.Logger.getLogger(path);
			if (logger == null)
				Logger.instance().debug3("logger is null for path '" + path + "'.");
			else if (logger == globalLogger)
				continue;
			else
			{
				handlers = logger.getHandlers();
				if (handlers == null || handlers.length == 0)
					Logger.instance().debug3("Path '" + path + "' No loggers present.");
				while (handlers != null && handlers.length > 0)
				{
					Logger.instance().debug3("Path '" + path + "': Removing " + handlers[0].getClass().getName());
					logger.removeHandler(handlers[0]);
					handlers = logger.getHandlers();
				}
				logger.addHandler(instance());
				logger.setLevel(Level.ALL);
			}
		}
	}

public final class ResourcePool extends AbstractResource implements AutoCloseable {

    private final List<ResourceReference> resources = new ArrayList<>();
    private final ContainerBuilder builder;

    /**
     * <p>Creates a new instance of this class without a backing {@link ContainerBuilder}. A ResourcePool created with
     * this constructor will throw a NullPointerException if either {@link #get(Class)} or {@link #get(Key)} is
     * called.</p>
     */
    public ResourcePool() {
        this(null);
    }

    /**
     * <p>Creates a new instance of this class. All calls to {@link #get(Class)} and {@link #get(Key)} are forwarded to
     * the {@link ContainerBuilder} given to this constructor.</p>
     *
     * @param builder The ContainerBuilder that provides the injection functionality for this ResourcePool.
     */
    public ResourcePool(ContainerBuilder builder) {
        this.builder = builder;
    }

    /**
     * <p>Adds the given {@link SharedResource} to this ResourcePool. Note that this DOES NOT call {@link
     * SharedResource#refer()}, as opposed to {@link #retain(SharedResource)}. When this ResourcePool is
     * destroyed, it will release the main reference to the resource (by calling {@link SharedResource#release()}).</p>
     *
     * @param t   The SharedResource to add.
     * @param <T> The class of parameter <code>t</code>.
     * @return The parameter <code>t</code>, to allow inlined calls to this function.
     */
    public <T extends SharedResource> T add(T t) {
        try {
            resources.add(References.fromResource(t));
        } catch (IllegalStateException e) {
            // Ignore. TODO(bakksjo): Don't rely on ISE to detect duplicates; handle that in this class instead.
        }
        return t;
    }

    /**
     * <p>Returns the appropriate instance for the given injection key. Note that this DOES NOT call {@link
     * SharedResource#refer()}. This is the equivalent of doing:</p>
     * <pre>
     * t = containerBuilder.getInstance(key);
     * resourcePool.add(t);
     * </pre>
     *
     * <p>When this ResourcePool is destroyed, it will release the main reference to the resource
     * (by calling {@link SharedResource#release()}).</p>
     *
     * @param key The injection key to return.
     * @param <T> The class of the injection type.
     * @return The appropriate instance of T.
     * @throws NullPointerException If this pool was constructed without a ContainerBuilder.
     */
    public <T extends SharedResource> T get(Key<T> key) {
        return add(builder.getInstance(key));
    }

    /**
     * <p>Returns the appropriate instance for the given injection type. Note that this DOES NOT call {@link
     * SharedResource#refer()}. This is the equivalent of doing:</p>
     * <pre>
     * t = containerBuilder.getInstance(type);
     * resourcePool.add(t);
     * </pre>
     *
     * <p>When this ResourcePool is destroyed, it will release the main reference to the resource
     * (by calling {@link SharedResource#release()}).</p>
     *
     * @param type The injection type to return.
     * @param <T>  The class of the injection type.
     * @return The appropriate instance of T.
     * @throws NullPointerException If this pool was constructed without a ContainerBuilder.
     */
    public <T extends SharedResource> T get(Class<T> type) {
        return add(builder.getInstance(type));
    }

    /**
     * <p>Retains and adds the given {@link SharedResource} to this ResourcePool. Note that this DOES call {@link
     * SharedResource#refer()}, as opposed to {@link #add(SharedResource)}.
     *
     * <p>When this ResourcePool is destroyed, it will release the resource reference returned by the
     * {@link SharedResource#refer()} call.</p>
     *
     * @param t   The SharedResource to retain and add.
     * @param <T> The class of parameter <code>t</code>.
     * @return The parameter <code>t</code>, to allow inlined calls to this function.
     */
    public <T extends SharedResource> T retain(T t) {
        resources.add(t.refer(this));
        return t;
    }

    @Override
    protected void destroy() {
        for (ResourceReference resource : resources) {
            resource.close();
        }
    }

    @Override
    public void close() throws Exception {
        release();
    }
}

public class MainActivity extends AppCompatActivity implements NewsAdapter.OnNewsListener, CategoryAdapter.OnCategoryListener {

    private RecyclerView news_rv, category_rv;
    private ProgressBar progressBar;
    private ArrayList<CategoryModel> categoryModelArrayList;
    private ArrayList<Articles> articlesArrayList;
    private CategoryAdapter categoryAdapter;
    private NewsAdapter newsAdapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        news_rv = findViewById(R.id.rv_news);
        category_rv = findViewById(R.id.rv_categories);
        progressBar = findViewById(R.id.progressBar);
        categoryModelArrayList = new ArrayList<>();
        articlesArrayList = new ArrayList<>();
        categoryAdapter = new CategoryAdapter(categoryModelArrayList,this,this::OnCategoryClick);
        newsAdapter = new NewsAdapter(articlesArrayList,this,this::OnNewsClick);
        news_rv.setAdapter(newsAdapter);
        category_rv.setAdapter(categoryAdapter);
        getCategories();
        getNews("All"); //by default data for 'All' news category will be shown
        newsAdapter.notifyDataSetChanged();

    }


    private void getCategories(){
        categoryModelArrayList.add(new CategoryModel("All",""));
        categoryModelArrayList.add(new CategoryModel("Technology","https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?ixlib=rb-1.2.1&ixid=MnwxMjA3fDB8MHxzZWFyY2h8MTN8fHRlY2hub2xvZ3l8ZW58MHx8MHx8&auto=format&fit=crop&w=600&q=60"));
        categoryModelArrayList.add(new CategoryModel("Science","https://images.unsplash.com/photo-1564325724739-bae0bd08762c?ixid=MnwxMjA3fDB8MHxzZWFyY2h8M3x8c2NpZW5jZXxlbnwwfHwwfHw%3D&ixlib=rb-1.2.1&auto=format&fit=crop&w=600&q=60"));
        categoryModelArrayList.add(new CategoryModel("Sports","https://images.unsplash.com/photo-1484482340112-e1e2682b4856?ixid=MnwxMjA3fDB8MHxzZWFyY2h8MTJ8fHNwb3J0c3xlbnwwfHwwfHw%3D&ixlib=rb-1.2.1&auto=format&fit=crop&w=600&q=60"));
        categoryModelArrayList.add(new CategoryModel("General","https://images.unsplash.com/photo-1500462918059-b1a0cb512f1d?ixid=MnwxMjA3fDB8MHxzZWFyY2h8NTN8fGdlbmVyYWx8ZW58MHx8MHx8&ixlib=rb-1.2.1&auto=format&fit=crop&w=600&q=60"));
        categoryModelArrayList.add(new CategoryModel("Business","https://images.unsplash.com/39/lIZrwvbeRuuzqOoWJUEn_Photoaday_CSD%20(1%20of%201)-5.jpg?ixid=MnwxMjA3fDB8MHxzZWFyY2h8Mnx8YnVzaW5lc3N8ZW58MHx8MHx8&ixlib=rb-1.2.1&auto=format&fit=crop&w=600&q=60"));
        categoryModelArrayList.add(new CategoryModel("Entertainment","https://images.unsplash.com/photo-1617870236116-d99becf1c6c0?ixid=MnwxMjA3fDB8MHxzZWFyY2h8Mnx8ZW50ZXJ0YWlubWVudCUyMGRpc3RyaWN0fGVufDB8fDB8fA%3D%3D&ixlib=rb-1.2.1&auto=format&fit=crop&w=600&q=60"));
        categoryModelArrayList.add(new CategoryModel("Health","https://images.unsplash.com/photo-1505751172876-fa1923c5c528?ixid=MnwxMjA3fDB8MHxzZWFyY2h8Nnx8aGVhbHRofGVufDB8fDB8fA%3D%3D&ixlib=rb-1.2.1&auto=format&fit=crop&w=600&q=60"));
        categoryAdapter.notifyDataSetChanged();  //to notify adapter that data has been changed
    }


    private void getNews(String category){
        progressBar.setVisibility(View.VISIBLE);
        articlesArrayList.clear();
        String categoryURL = "https://newsapi.org/v2/top-headlines?country=in&category="+ category +"&apiKey=7443ff471d264f37a74a7f3d7fd8f92e";
        String url = "https://newsapi.org/v2/top-headlines?country=in&excludeDomains=stackoverflow.com&sortBy=publishedAt&language=en&apiKey=7443ff471d264f37a74a7f3d7fd8f92e";
        String BASE_URL = "https://newsapi.org/";

        //creating object of retrofit and adding the url
        Retrofit retroFit = new Retrofit.Builder().baseUrl(BASE_URL).addConverterFactory(GsonConverterFactory.create()).build();

        //The JSON data will be converted to 'RetrofitAPI.class' type
        RetrofitAPI api = retroFit.create(RetrofitAPI.class);

        //creating a call of NewsModel class
        Call<NewsModel> call;

        if(category=="All"){
            //passing the method declared in the interface
            call = api.getNewsFeed(url);
        }
        else {
            call = api.getNewsByCategory(categoryURL);
        }

        //enqueuing the call and receiving the response
        call.enqueue(new Callback<NewsModel>() {                                                 
            @Override
            public void onResponse(Call<NewsModel> call, Response<NewsModel> response) {
                NewsModel newsModel = response.body();
                progressBar.setVisibility(View.GONE);
                ArrayList<Articles> articles = newsModel.getArticles();
                for(int i=0;i<articles.size();i++){
                    articlesArrayList.add(new Articles(articles.get(i).getTitle(),
                            articles.get(i).getDescription(),articles.get(i).getUrl(),
                            articles.get(i).getUrlToImage(),articles.get(i).getContent(),articles.get(i).getPublishedAt()));
                }
                newsAdapter.notifyDataSetChanged();
            }

            @Override
            public void onFailure(Call<NewsModel> call, Throwable t) {
                Toast.makeText(MainActivity.this,"Failed to get news",Toast.LENGTH_SHORT).show();
            }
        });
    }


    //method of 'OnNewsListener' interface of 'NewsAdapter' class
    @Override
    public void OnNewsClick(int position) {
        Intent intent = new Intent(this,NewsDetailActivity.class);
        intent.putExtra("title", articlesArrayList.get(position).getTitle());
        intent.putExtra("content", articlesArrayList.get(position).getContent());
        intent.putExtra("desc", articlesArrayList.get(position).getDescription());
        intent.putExtra("url", articlesArrayList.get(position).getUrl());
        intent.putExtra("urlImage", articlesArrayList.get(position).getUrlToImage());
        startActivity(intent);
    }

    //method of 'OnCategoryListener' interface of 'CategoryAdapter' class
    @Override
    public void OnCategoryClick(int position) {
        String category = categoryModelArrayList.get(position).getCategoryName();
        getNews(category);
    }
}

class LoopUntilSuccess
        : public Decorator
    {
        typedef Decorator BaseClass;
    public:
        struct RuntimeData
        {
            uint8 failedAttemptCountSoFar;
            bool childWasRunningLastTick;
            RuntimeData()
                : failedAttemptCountSoFar(0)
                , childWasRunningLastTick(false)
            {
            }
        };
        LoopUntilSuccess()
            : m_maxAttemptCount(0)
        {
        }
        virtual LoadResult LoadFromXml(const XmlNodeRef& xml, const LoadContext& context) override
        {
            IF_UNLIKELY (BaseClass::LoadFromXml(xml, context) == LoadFailure)
            {
                return LoadFailure;
            }
            m_maxAttemptCount = 0; 
            xml->getAttr("attemptCount", m_maxAttemptCount);
            return LoadSuccess;
        }
#ifdef USING_BEHAVIOR_TREE_XML_DESCRIPTION_CREATION
        virtual XmlNodeRef CreateXmlDescription() override
        {
            XmlNodeRef xml = BaseClass::CreateXmlDescription();
            xml->setTag("LoopUntilSuccess");
            if (m_maxAttemptCount)
            {
                xml->setAttr("attemptCount", m_maxAttemptCount);
            }
            return xml;
        }
#endif
#ifdef USING_BEHAVIOR_TREE_SERIALIZATION
        virtual void Serialize(Serialization::IArchive& archive) override
        {
            archive(m_maxAttemptCount, "repeatCount", "Attempt count (0 means infinite)");
            BaseClass::Serialize(archive);
        }
#endif
    protected:
        virtual Status Update(const UpdateContext& context) override
        {
            RuntimeData& runtimeData = GetRuntimeData<RuntimeData>(context);
            Status childStatus = m_child->Tick(context);
            if (childStatus == Failure)
            {
                const bool finiteLoop = (m_maxAttemptCount > 0);
                if (finiteLoop)
                {
                    if (runtimeData.failedAttemptCountSoFar + 1 >= m_maxAttemptCount)
                    {
                        return Failure;
                    }
                    ++runtimeData.failedAttemptCountSoFar;
                }
                if (runtimeData.childWasRunningLastTick)
                {
                    childStatus = m_child->Tick(context);
                }
            }
            runtimeData.childWasRunningLastTick = (childStatus == Running);
            if (childStatus == Success)
            {
                return Success;
            }
            return Running;
        }
    private:
        uint8 m_maxAttemptCount; 
    }

disconnect() {
		this.tryConnect = false;
		if (this.ws) {
			let ws = this.ws;
			let err = { code: 'system.disconnect', message: "Disconnect called" };
			ws.onclose = null;
			this._handleOnclose(err);
			ws.close();
			this._connectReject(err);
		}
	}

uint32_t getAck(const TcpSegment& segment) {
    // If the segment has payload, ACK is current sequence number + payload size
    if (segment.payload().size() > 0) {
        return segment.sequence_number() + segment.payload().size();
    }

    // For SYN/FIN segments, ACK is sequence number + 1 (they consume 1 sequence number)
    if (segment.syn() || segment.fin()) {
        return segment.sequence_number() + 1;
    }

    // For pure ACK segments or empty segments, return the current sequence number
    return segment.sequence_number();
}

public class SpoutOutputCollector implements ISpoutOutputCollector {
    ISpoutOutputCollector _delegate;

    public SpoutOutputCollector(ISpoutOutputCollector delegate) {
        _delegate = delegate;
    }

    /**
     * Emits a new tuple to the specified output stream with the given message ID.
     * When Storm detects that this tuple has been fully processed, or has failed
     * to be fully processed, the spout will receive an ack or fail callback respectively
     * with the messageId as long as the messageId was not null. If the messageId was null,
     * Storm will not track the tuple and no callback will be received. 
     * Note that Storm's event logging functionality will only work if the messageId
     * is serializable via Kryo or the Serializable interface. The emitted values must be immutable.
     *
     * @return the list of task ids that this tuple was sent to
     */
    public List<Integer> emit(String streamId, List<Object> tuple, Object messageId) {
        return _delegate.emit(streamId, tuple, messageId);
    }

    /**
     * Emits a new tuple to the default output stream with the given message ID.
     * When Storm detects that this tuple has been fully processed, or has failed
     * to be fully processed, the spout will receive an ack or fail callback respectively
     * with the messageId as long as the messageId was not null. If the messageId was null,
     * Storm will not track the tuple and no callback will be received.
     * Note that Storm's event logging functionality will only work if the messageId
     * is serializable via Kryo or the Serializable interface. The emitted values must be immutable.
     *
     * @return the list of task ids that this tuple was sent to
     */
    public List<Integer> emit(List<Object> tuple, Object messageId) {
        return _delegate.emit(Utils.DEFAULT_STREAM_ID, tuple, messageId);
    }

    /**
     * Emits a tuple to the default output stream with a null message id. Storm will
