public async Task<Event> FindEventAsync(int id, bool render = false, string permalinkId = null, CancellationToken cancellationToken = default)
{
    // Implement your logic to find the event using the provided parameters

    // Assuming you have an in-memory collection (events) and a method to find events (FindEventById)
    Event eventToReturn;
    if (permalinkId != null)
    {
        eventToReturn = events.FirstOrDefault(e => e.PermalinkId == permalinkId || e.Id == id);
    }
    else
    {
        eventToReturn = events.FirstOrDefault(e => e.Id == id);
    }

    if (eventToReturn != null)
    {
        if (render)
        {
            eventToReturn.RenderMessage();
        }

        return eventToReturn;
    }

    throw new EventNotFoundException("Event not found with the provided id.");
}

