private static ForEach parseForEach(Element forEachElement)
	{
		String path = null;
		String listName = null;
		String var;
		List<Action> nestedActions = new ArrayList<>();
		String limit;
		boolean parallel;
		if(!forEachElement.hasAttributeWithName("path") && !forEachElement.hasAttributeWithName("list"))
			throw new RuntimeException("forEach must have either a path or a list attribute");
		else if(forEachElement.hasAttributeWithName("path") && forEachElement.hasAttributeWithName("list"))
			throw new RuntimeException("forEach cannot have a path and a list attribute");
		if(forEachElement.hasAttributeWithName("path"))
			path = forEachElement.getAttribute("path");
		else
			listName = forEachElement.getAttribute("list");
		if(!forEachElement.hasAttributeWithName("var"))
			throw new RuntimeException("forEach has no var attribute");
		else
			var = forEachElement.getAttribute("var");
		if(forEachElement.hasAttributeWithName("limit"))
			limit = forEachElement.getAttribute("limit");
		else
			limit = null;
		parallel = forEachElement.hasAttributeWithName("parallel") && forEachElement.getAttributeAsBoolean("parallel");
		forEachElement.getElements().forEach(actionElement -> nestedActions.add(parse(actionElement)));
		if(path != null)
			return new ForEachPath(path, var, nestedActions, limit, parallel);
		else
			return new ForEachList(listName, var, nestedActions, limit, parallel);
	}

internal class SSPIHandler : IDisposable
    {
        #region constants and structs
        private const int SECBUFFER_VERSION = 0;
        private const int SECBUFFER_TOKEN = 2;
        private const int SEC_E_OK = 0x00000000;
        private const int SEC_I_CONTINUE_NEEDED = 0x00090312;
        private const int ISC_REQ_ALLOCATE_MEMORY=0x00000100;
        private const int SECURITY_NETWORK_DREP=0x00000000;
        private const int SECPKG_CRED_OUTBOUND=0x00000002;
        [StructLayout(LayoutKind.Sequential)]
        private struct SecHandle
        {
            public int dwLower;
            public int dwUpper;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct SecBuffer
        {
            public int cbBuffer;
            public int BufferType;
            public IntPtr pvBuffer;
        }
        [StructLayout(LayoutKind.Sequential)]
        private struct SecBufferDesc
        {
            public int ulVersion;
            public int cBuffers;
            public IntPtr pBuffer;
        }
        #endregion
        #region p/invoke methods
        [DllImport("Secur32.dll")]
        private extern static int AcquireCredentialsHandle(
            string pszPrincipal,
            string pszPackage,
            int fCredentialUse,
            IntPtr pvLogonID,
            IntPtr pAuthData,
            IntPtr pGetKeyFn,
            IntPtr pvGetKeyArgument,
            ref SecHandle phCredential,
            out SecHandle ptsExpiry
        );
        [DllImport("secur32", CharSet=CharSet.Auto, SetLastError=true)]
        static extern int InitializeSecurityContext(
            ref SecHandle phCredential,
            ref SecHandle phContext,
            string pszTargetName,
            int fContextReq,
            int Reserved1,
            int TargetDataRep,
            ref SecBufferDesc pInput,
            int Reserved2,
            out SecHandle phNewContext,
            out SecBufferDesc pOutput,
            out int pfContextAttr,
            out SecHandle ptsExpiry);
        [DllImport("secur32", CharSet=CharSet.Auto, SetLastError=true)]
        static extern int InitializeSecurityContext(
            ref SecHandle phCredential,
            IntPtr phContext,
            string pszTargetName,
            int fContextReq,
            int Reserved1,
            int TargetDataRep,
            IntPtr pInput,
            int Reserved2,
            out SecHandle phNewContext,
            out SecBufferDesc pOutput,
            out int pfContextAttr,
            out SecHandle ptsExpiry);
        [DllImport("Secur32.dll")]
        private extern static int FreeContextBuffer(
            IntPtr pvContextBuffer
        );
        [DllImport("Secur32.dll")]
        private extern static int FreeCredentialsHandle(
            ref SecHandle phCredential
        );
        [DllImport("Secur32.dll")]
        private extern static int DeleteSecurityContext(
            ref SecHandle phContext
        );
        #endregion
        private bool disposed;
        private string sspitarget;
        private SecHandle sspicred;
        private SecHandle sspictx;
        private bool sspictx_set;
        public SSPIHandler(string pghost, string krbsrvname)
        {
            if (pghost == null)
                throw new ArgumentNullException("pghost");
            if (krbsrvname == null)
                krbsrvname = String.Empty;
            sspitarget = String.Format("{0}/{1}", krbsrvname, pghost);
            SecHandle expire;
            int status = AcquireCredentialsHandle(
                "",
                "negotiate",
                SECPKG_CRED_OUTBOUND,
                IntPtr.Zero,
                IntPtr.Zero,
                IntPtr.Zero,
                IntPtr.Zero,
                ref sspicred,
                out expire
            );
            if (status != SEC_E_OK)
            {
                throw new Win32Exception();
            }
        }
        public string Continue(byte[] authData)
        {
            if (authData == null && sspictx_set)
                throw new InvalidOperationException("The authData parameter con only be null at the first call to continue!");
            int status;
            SecBuffer OutBuffer;
            SecBuffer InBuffer;
	        SecBufferDesc inbuf;
	        SecBufferDesc outbuf;
            SecHandle newContext;
            SecHandle expire;
            int contextAttr;
            OutBuffer.pvBuffer = IntPtr.Zero;
            OutBuffer.BufferType = SECBUFFER_TOKEN;
            OutBuffer.cbBuffer = 0;
            outbuf.cBuffers = 1;
            outbuf.ulVersion = SECBUFFER_VERSION;
            outbuf.pBuffer = Marshal.AllocHGlobal(Marshal.SizeOf(OutBuffer));
            try
            {
                Marshal.StructureToPtr(OutBuffer, outbuf.pBuffer, false);
                if (sspictx_set)
                {
                    inbuf.pBuffer = IntPtr.Zero;
                    InBuffer.pvBuffer = Marshal.AllocHGlobal(authData.Length);
                    try
                    {
                    Marshal.Copy(authData, 0, InBuffer.pvBuffer, authData.Length);
                    InBuffer.cbBuffer = authData.Length;
                    InBuffer.BufferType = SECBUFFER_TOKEN;
                    inbuf.ulVersion = SECBUFFER_VERSION;
                    inbuf.cBuffers = 1;
                    inbuf.pBuffer = Marshal.AllocHGlobal(Marshal.SizeOf(InBuffer));
                    Marshal.StructureToPtr(InBuffer, inbuf.pBuffer, false);
                        status = InitializeSecurityContext(
                            ref sspicred,
                            ref sspictx,
                            sspitarget,
                            ISC_REQ_ALLOCATE_MEMORY,
                            0,
                            SECURITY_NETWORK_DREP,
                            ref inbuf,
                            0,
                            out newContext,
                            out outbuf,
                            out contextAttr,
                            out expire
                        );
                    }
                    finally
                    {
                        if (InBuffer.pvBuffer != IntPtr.Zero)
                            Marshal.FreeHGlobal(InBuffer.pvBuffer);
                        if (inbuf.pBuffer != IntPtr.Zero)
                            Marshal.FreeHGlobal(inbuf.pBuffer);
                    }
                }
                else
                {
                    status = InitializeSecurityContext(
                        ref sspicred,
                        IntPtr.Zero,
                        sspitarget,
                        ISC_REQ_ALLOCATE_MEMORY,
                        0,
                        SECURITY_NETWORK_DREP,
                        IntPtr.Zero,
                        0,
                        out newContext,
                        out outbuf,
                        out contextAttr,
                        out expire
                    );
                }
                if (status != SEC_E_OK && status != SEC_I_CONTINUE_NEEDED)
                {
                    throw new Win32Exception();
                }
                if (!sspictx_set)
                {
                    sspictx.dwUpper = newContext.dwUpper;
                    sspictx.dwLower = newContext.dwLower;
                    sspictx_set = true;
                }
                if (outbuf.cBuffers > 0)
                {
                    if (outbuf.cBuffers != 1)
                    {
                        throw new InvalidOperationException("SSPI returned invalid number of output buffers");
                    }
                    OutBuffer = (SecBuffer)Marshal.PtrToStructure(outbuf.pBuffer, typeof(SecBuffer));
                    if (OutBuffer.cbBuffer > 0)
                    {
                        byte[] buffer = new byte[OutBuffer.cbBuffer];
                        Marshal.Copy(OutBuffer.pvBuffer, buffer, 0, buffer.Length);
                        return System.Text.Encoding.ASCII.GetString(buffer);
                    }
                }
                return String.Empty;
            }
            finally
            {
                if (OutBuffer.pvBuffer != IntPtr.Zero)
                    FreeContextBuffer(OutBuffer.pvBuffer);
                if (outbuf.pBuffer != IntPtr.Zero)
                    Marshal.FreeHGlobal(outbuf.pBuffer);
            }
        }
        #region resource cleanup
        private void FreeHandles()
        {
            if (sspictx_set)
            {
                FreeCredentialsHandle(ref sspicred);
                DeleteSecurityContext(ref sspictx);
            }
        }
        ~SSPIHandler()
        {
            FreeHandles();
        }
        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
        protected virtual void Dispose(bool disposing)
        {
            if (!disposed)
            {
                if (disposing)
                {
                    FreeHandles();
                }
                disposed = true;
            }
        }
        #endregion
    }

def transform_numerical_to_quantiles(TRAIN, TEST=None, n_quantiles=10):
    numerical = TRAIN.select_dtypes(exclude=["object"]).columns
    if TEST is not None:
        if len(numerical) > 0:
            for col in numerical:
                TRAIN[col], bins = pd.qcut(TRAIN[col], n_quantiles,
                                           labels=False, retbins=True)
                TEST["_bins_" + col] = np.nan
                for idx, item in enumerate(bins):
                    if idx <= 1:
                        TEST["_bins_" + col] = np.where(TEST[col] <= item, 0,
                                                        TEST["_bins_" + col])
                    if idx >= (n_quantiles - 1):
                        TEST["_bins_" + col] = np.where(TEST[col] > item,
                                                        (n_quantiles - 1),
                                                        TEST["_bins_" + col])
                    if (1 < idx) & (idx <= (n_quantiles - 1)):
                        TEST["_bins_" + col] = np.where((float(bins[idx - 1]) <
                                                         TEST[col]) &
                                                        (TEST[col] <= item),
                                                        idx - 1,
                                                        TEST["_bins_" + col])
            TEST = TEST.drop(numerical, axis=1)
            TEST.columns = TEST.columns.str.replace("_bins_", "")
        return (TRAIN, TEST)
    else:
        if len(numerical) > 0:
            for col in numerical:
                TRAIN[col] = pd.qcut(TRAIN[col], n_quantiles, labels=False)
        return TRAIN

