node * find_the_node_most_suitable (long long parent)
{
    node *min_size_node = nullptr;
    long long min_size = n;
    for(auto & elem : graph[parent])
        if (graph[elem].size() < min_size)
        {
            if (nullptr == min_size_node)
            {
                min_size_node = new node;
                min_size_node->size = n - graph[elem].size();
                min_size_node->book.insert({pair<long long,node*>({parent, nullptr})});
            }
            else min_size_node->size = min(min_size_node->size, static_cast<long long>(n - graph[elem].size()));
        }
    return min_size_node;
}

