public class CustomOauth2AuthenticationOptions : RemoteAuthenticationOptions
{
    public string AuthorizationEndpoint { get; set; }
    public string ApiKey { get; set; }
    public string[] AllowedUrls { get; set; }
    public int ExpiryMinutes { get; set; }
    public string UserField { get; set; }
    public string OriginField { get; set; }
    public StateDataFormat StateDataFormat { get; set; }

    public CustomOauth2AuthenticationOptions()
    {
        // Initialize with default values
