#include <iostream>
#include <string>

// Define a base class for behaviors
class Behavior {
public:
    virtual std::string Execute() = 0;
};

// Define a decorator class
class Decorator : public Behavior {
private:
    Behavior* behavior;

public:
    Decorator(Behavior* behavior) : behavior(behavior) {}

    std::string Execute() override {
        // Execute the child behavior
        std::string result = behavior->Execute();

        // Validate the result
        if (IsValid(result)) {
            // Modify the result if valid
            result = ModifyResult(result);
            return "Success: " + result;
        } else {
            return "Failed: Invalid result";
        }
    }

    // Method to validate the result
    bool IsValid(const std::string& result) {
        // Add validation logic here
        // For demonstration purposes, assume any non-empty string is valid
        return!result.empty();
    }

    // Method to modify the result
    std::string ModifyResult(const std::string& result) {
        // Add modification logic here
        // For demonstration purposes, convert the result to uppercase
        std::string modifiedResult = result;
        for (char& c : modifiedResult) {
            c = std::toupper(c);
        }
        return modifiedResult;
    }
};

// Example usage
class ConcreteBehavior : public Behavior {
public:
    std::string Execute() override {
        return "Hello, World!";
    }
};

int main() {
    ConcreteBehavior* behavior = new ConcreteBehavior();
    Decorator decorator(behavior);
    std::cout << decorator.Execute() << std::endl;

    delete behavior;
    return 0;
}

private static void forEachDemoAccessingMore() {
        List<Integer> aList = new ArrayList<>(Arrays.asList(1, 2, 4, 2, 5, 2, 5, 1, 4, 21));
        System.out.println("below is enhanced for each with indexes");
        long s1 = System.currentTimeMillis();
        for (int i = 0; i < aList.size(); i++) {
            System.out.print(aList.get(i) + ", ");
        }
        long e1 = System.currentTimeMillis();
        System.out.println("Total execution time: " + (e1 - s1) + "ms");
        System.out.println("\nbelow is enhanced for each without indexes");
        long s2 = System.currentTimeMillis();
        for (Integer element : aList) {
            System.out.print(element + ", ");
        }
        long e2 = System.currentTimeMillis();
        System.out.println("Total execution time: " + (e2 - s2) + "ms");
        System.out.println("\nbelow is foreach lambda");
        long s3 = System.currentTimeMillis();
        aList.forEach(e -> System.out.print(e + ", "));
        long e3 = System.currentTimeMillis();
        System.out.println("Total execution time: " + (e3 - s3) + "ms");
    }

