TEST_P(BindGroupTests, ReadonlyStorage) {
    utils::ComboRenderPipelineDescriptor pipelineDescriptor(device);
    pipelineDescriptor.vertexStage.module =
        utils::CreateShaderModule(device, utils::SingleShaderStage::Vertex, R"(
            #version 450
            void main() {
                const vec2 pos[3] = vec2[3](vec2(-1.f, 1.f), vec2(1.f, 1.f), vec2(-1.f, -1.f));
                gl_Position = vec4(pos[gl_VertexIndex], 0.f, 1.f);
            })");
    pipelineDescriptor.cFragmentStage.module =
        utils::CreateShaderModule(device, utils::SingleShaderStage::Fragment, R"(
            #version 450
            layout(set = 0, binding = 0) readonly buffer buffer0 {
                vec4 color;
            };
            layout(location = 0) out vec4 fragColor;
            void main() {
                fragColor = color;
            })");
    constexpr uint32_t kRTSize = 4;
    utils::BasicRenderPass renderPass = utils::CreateBasicRenderPass(device, kRTSize, kRTSize);
    pipelineDescriptor.cColorStates[0].format = renderPass.colorFormat;
    wgpu::BindGroupLayout bgl = utils::MakeBindGroupLayout(
        device, {{0, wgpu::ShaderStage::Fragment, wgpu::BindingType::StorageBuffer}});
    pipelineDescriptor.layout = utils::MakeBasicPipelineLayout(device, &bgl);
    wgpu::RenderPipeline renderPipeline = device.CreateRenderPipeline(&pipelineDescriptor);
    wgpu::CommandEncoder encoder = device.CreateCommandEncoder();
    wgpu::RenderPassEncoder pass = encoder.BeginRenderPass(&renderPass.renderPassInfo);
    std::array<float, 4> greenColor = {0, 1, 0, 1};
    wgpu::Buffer storageBuffer = utils::CreateBufferFromData(
        device, &greenColor, sizeof(greenColor), wgpu::BufferUsage::Storage);
    pass.SetPipeline(renderPipeline);
    pass.SetBindGroup(0, utils::MakeBindGroup(device, bgl, {{0, storageBuffer}}));
    pass.Draw(3);
    pass.EndPass();
    wgpu::CommandBuffer commands = encoder.Finish();
    queue.Submit(1, &commands);
    EXPECT_PIXEL_RGBA8_EQ(RGBA8::kGreen, renderPass.color, 0, 0);
}

private static void EnsureCache(int size)
        {
            if (freezableCache == null) {
                lock (cacheMutex) {
                    if (freezableCache == null) {
                        freezableCache = new List<Freezable>(size);
                        for (int i = 0; i < size; ++i)
                            freezableCache.Add(null);
                    }
                }
            }
            Debug.Assert(freezableCache.Count == size, "The cache size does not match the requested amount.");
        }

void ht2_dump_stats(hashtbl2_t * tbl) {
  size_t empty = 0;
  int avg_len = 0, maxlen = 0;
  int i;
  for (i = 0; i < tbl->arrsz; i++) {
    if ((!tbl->arr[i]) || tbl->arr[i]->nnodes == 0)
      empty++;
    else {
      avg_len += tbl->arr[i]->nnodes;
      if (tbl->arr[i]->nnodes > maxlen)
        maxlen = tbl->arr[i]->nnodes;
    }
  }
  if (tbl->arrsz != empty)
    avg_len = avg_len / (tbl->arrsz - empty);
  fprintf(stderr,
          "size:\t%zd\nempty:\t%zd\naverage length (nonempty only): %d\nmax length:\t%d\ntotal elems:\t%zd\n",
          tbl->arrsz, empty, avg_len, maxlen, tbl->nelems);
}

public TestCaseData Until(DateTimeOffset datetime)
        {
            if (_prevRunState != RunState.NotRunnable)
            {
                if (datetime > DateTimeOffset.UtcNow)
                {
                    RunState = RunState.Ignored;
                    string reason = (string)Properties.Get(PropertyNames.SkipReason);
                    Properties.AddIgnoreUntilReason(datetime, reason);
                }
                else
                {
                    RunState = _prevRunState;
                }
                Properties.Set(PropertyNames.IgnoreUntilDate, datetime.ToString("u") );
            }
            return this;
        }

