        #endregion
        #region Object Overrides
        public override string ToString()
        {
            return $"{nameof(ApiMutableScalarType)} [{nameof(this.ApiName)}={this.ApiName} {nameof(this.ApiDescription)}='{this.ApiDescription}' {nameof(this.ClrScalarType)}={this.ClrScalarType.Name}]";
        }
        #endregion
    }

function posts(state={}, action){
  var type, category, post, posts
  ({ type, category, post, posts } = action)
  switch(type) {
    case RECEIVE_POSTS:
      return {
        ...state,
        allPosts: posts
      }
    case RECEIVE_POSTS_PER_CATEGORY:
      return {
        ...state,
        [category]: posts.map((post) => post.id),
        allPosts: Object.assign({}, state.allPosts, posts)
      }
    case RECEIVE_NEW_POST:
      return {
        ...state,
        allPosts: {
          ...state.allPosts,
          [post.id]: post
        }
      }
    case RECEIVE_EDITED_POST:
      return {
        ...state,
        allPosts: {
          ...state.allPosts,
          [post.id]: post
        },
        selectedPost: post
      }
    case RECEIVE_POST:
      return {
        ...state,
        selectedPost: post
      }
    default:
      return state
  }
}

