def create_radio(text,id_attribute,options,values,classes="",required=0,validate=False):
    class_names = "mdl-radio mdl-js-radio mdl-js-ripple-effect"       
    options,values = format_options_values(options,values)
    required = get_required_string(required)
    meta = parse_meta(text,options)
    if validate == True:
        print("Testing question %s with text %s" %(id_attribute,text))
    if len(options) == len(values):
        radio_html = '<p id="%s_options">%s</p>' %(id_attribute,text)
        for n in range(len(options)):
            option_id = "%s_%s" %(id_attribute,n)
            radio_html = '%s\n<label class="%s" for="option-%s">\n<input type="radio" id="option-%s" class="mdl-radio__button %s %s" name="%s_options" value="%s" %s>\n<span class="mdl-radio__label">%s</span>\n</label>' %(radio_html,class_names,option_id,option_id,required,classes,id_attribute,values[n],meta,options[n])
        return "%s<br><br><br><br>" %(radio_html)
    else:   
        error_message = "ERROR: %s options provided, and only %s values. Must define one option per value." %(len(options),len(values))
        if validate == True:
            raise ValueError(error_message)
        else:
            print(error_message)
        return ""

def analyze_normal(self,duplicate_data,errortype,cclib_data):
		atom_types,cartesians = cclib_atoms_coords(cclib_data)
		if errortype == 'none':
			E_dup = cclib_data['properties']['energy']['total']
			E_dup = cclib.parser.utils.convertor(E_dup, "eV", "hartree")
			try:
				H_dup = cclib_data['properties']['enthalpy']
				G_dup = cclib_data['properties']['energy']['free energy']
			except (AttributeError,KeyError):
				if cclib_data['properties']['number of atoms'] == 1:
					if cclib_data['metadata']['keywords line'].find('freq') == -1:
						errortype = 'sp_calc'
						cclib_data['metadata']['ground or transition state'] = 'SP calculation'
					H_dup = E_dup
					G_dup = E_dup
			for i,_ in enumerate(duplicate_data['Energies']):
				E_diff = abs(E_dup - duplicate_data['Energies'][i])
				H_diff = abs(H_dup - duplicate_data['Enthalpies'][i])
				G_diff = abs(G_dup - duplicate_data['Gibbs'][i])
				if max([E_diff,H_diff,G_diff]) < abs(float(self.args.dup_threshold)):
					errortype = 'duplicate_calc'
		if errortype == 'none':
			duplicate_data['Energies'].append(E_dup)
			duplicate_data['Enthalpies'].append(H_dup)
			duplicate_data['Gibbs'].append(G_dup)
			initial_ifreqs = 0
			for freq in cclib_data['vibrations']['frequencies']:
				if float(freq) < 0 and abs(float(freq)) > abs(float(self.args.ifreq_cutoff)):
					initial_ifreqs += 1
			if cclib_data['metadata']['ground or transition state'] == 'transition_state':
				initial_ifreqs -= 1
			if initial_ifreqs > 0:
				errortype = 'extra_imag_freq'
			elif initial_ifreqs < 0:
				errortype = 'ts_no_imag_freq'
			if len(atom_types) in [3,4]:
				errortype = detect_linear(errortype,atom_types,cclib_data)
		if errortype in ['extra_imag_freq','freq_no_conv','linear_mol_wrong']:
			if errortype == 'extra_imag_freq':
				cartesians = self.fix_imag_freqs(cclib_data, cartesians)
			opt_found = False
			for keyword in cclib_data['metadata']['keywords line'].split():
				if keyword.lower().startswith('opt'):
					opt_found = True
			if not opt_found:
				cclib_data['metadata']['keywords line'] += ' opt'
			if errortype == 'linear_mol_wrong':
				cclib_data['metadata']['keywords line'] += ' symmetry=(PG=Cinfv)'
			elif errortype == 'freq_no_conv':
				new_keywords_line = ''
				for keyword in cclib_data['metadata']['keywords line'].split():
					if keyword.lower().startswith('opt'):
						keyword = self.args.freq_conv
						if cclib_data['metadata']['ground or transition state'] == 'transition_state':
							keyword= keyword.replace('=(','=(ts,noeigen,')
					new_keywords_line += keyword
					new_keywords_line += ' '
				cclib_data['metadata']['keywords line'] = new_keywords_line
		return atom_types,cartesians,duplicate_data,errortype,cclib_data

package main

import (
	"fmt"
	"time"
	"zap"
)

func addFields(logger *zap.Logger, fields map[string]interface{}) error {
	// Initialize an empty map to store the fields
	var zapFields map[string]interface{}
	// Iterate over each key-value pair in the fields map
	for key, value := range fields {
		// Check the type of the value
		switch value.(type) {
		case bool:
			zapFields[key] = value
		case float64:
			zapFields[key] = value
		case int:
			zapFields[key] = value
		case string:
			zapFields[key] = value
		case time.Time:
			zapFields[key] = value
		case time.Duration:
			zapFields[key] = value
		case zap.Marshaler:
			zapFields[key] = value
		case error:
			zapFields[key] = value.Error()
		case fmt.Stringer:
			zapFields[key] = value.String()
		default:
			return fmt.Errorf("unsupported type: %T", value)
		}
	}
	// Use the With method to add the fields to the logger
	return logger.With(zapFields).Write(zap.AddToLogFields(zapFields))
}

func main() {
	// Create a zap logger
	logger := zap.NewExample()
	// Create a map of fields
	fields := map[string]interface{}{
		"key1": "value1",
		"key2": 123,
		"key3": true,
		"key4": time.Now(),
		"key5": 10 * time.Second,
		"key6": "custom marshaler",
		"key7": fmt.Errorf("error"),
		"key8": fmt.Sprintf("stringer"),
	}
	// Call the addFields function
	if err := addFields(logger, fields); err != nil {
		fmt.Println(err)
	}
}

public class PropertySubqueryExpression extends SubqueryExpression {
	private String propertyName;

	protected PropertySubqueryExpression(String propertyName, String op, String quantifier, DetachedCriteria dc) {
		super( op, quantifier, dc );
		this.propertyName = propertyName;
	}

	@Override
	protected String toLeftSqlString(Criteria criteria, CriteriaQuery criteriaQuery) {
		return criteriaQuery.getColumn( criteria, propertyName );
	}

}

private boolean isUncompletedRenewal(int licenceId) throws SQLException {
		String sqlQuery = "Select * "
				+ "FROM renewals "
				+ "WHERE licences_id = ? AND status NOT LIKE ?";
		PreparedStatement statement = dbConnection.prepareStatement(sqlQuery);
		statement.setInt(1, licenceId);
		statement.setString(2, Status.COMPLETED.toString());
		ResultSet result = statement.executeQuery();
		if (result.next())
			return true;
		return false;
	}

def speed(point_distance, time):
    if point_distance != 0.0:
        point_distance = point_distance/1000
        time = time / 3600
        object_speed = point_distance/time
        object_speed = math.ceil(object_speed * 100) / 100
    else:
        object_speed = 0.00
    return object_speed

private async Task DoCreateSpriteAsync()
        {
            Stream outStream = null;
            void SaveSprite() => _spriteCodec.Save(_sprite, outStream);
            try
            {
                if (ContentState != ContentState.Unmodified)
                {
                    MessageResponse response = HostServices.MessageDisplay.ShowConfirmation(string.Format(Resources.GORSPR_CONFIRM_CLOSE, File.Name), allowCancel: true);
                    switch (response)
                    {
                        case MessageResponse.Yes:
                            ShowWaitPanel(Resources.GORSPR_TEXT_SAVING);
                            File.IsOpen = false;
                            outStream = ContentFileManager.OpenStream(File.Path, FileMode.Create);
                            await Task.Run(SaveSprite);
                            outStream.Dispose();
                            File.IsOpen = true;
                            HideWaitPanel();
                            break;
                        case MessageResponse.Cancel:
                            return;
                    }
                }
                (string newName, IContentFile textureFile, DX.Size2F size) = _contentServices.NewSpriteService.GetNewSpriteName(File, _textureFile, _sprite.Size);
                if (newName == null)
                {
                    return;
                }
                string spriteDirectory = Path.GetDirectoryName(File.Path).FormatDirectory('/');
                if (string.IsNullOrWhiteSpace(spriteDirectory))
                {
                    spriteDirectory = "/";
                }
                string spritePath = spriteDirectory + newName.FormatFileName();
                IContentFile existingFile = ContentFileManager.GetFile(spritePath);
                if (existingFile != null)
                {
                    if (existingFile.IsOpen)
                    {
                        HostServices.MessageDisplay.ShowConfirmation(string.Format(Resources.GORSPR_ERR_FILESYSTEM_ITEM_EXISTS, spritePath));
                        return;
                    }
                    if (HostServices.MessageDisplay.ShowConfirmation(string.Format(Resources.GORSPR_CONFIRM_SPRITE_EXISTS, spritePath)) != MessageResponse.Yes)
                    {
                        return;
                    }
                }
                ShowWaitPanel(Resources.GORSPR_TEXT_SAVING);
                outStream = ContentFileManager.OpenStream(spritePath, FileMode.Create);
                await Task.Run(SaveSprite);
                outStream.Dispose();
                IContentFile file = ContentFileManager.GetFile(spritePath);
                if (file == null)
                {
                    HostServices.MessageDisplay.ShowError(string.Format(Resources.GORSPR_ERR_SPRITE_NOT_FOUND, newName));
                    await CloseContentCommand.ExecuteAsync(new CloseContentArgs(false));
                    return;
                }
                ContentState = ContentState.Unmodified;
                if (Size != size)
                {
                    Size = size;
                    TextureCoordinates = new DX.RectangleF(TextureCoordinates.X, TextureCoordinates.Y, size.Width / _sprite.Texture.Width, size.Height / _sprite.Texture.Height);
                    ContentState = ContentState.Modified;
                }
                if (!string.Equals(textureFile.Path, _textureFile.Path, StringComparison.OrdinalIgnoreCase))
                {
                    if (await SetTextureAsync(file, textureFile, -1))
                    {
                        _originalTexture = _textureFile;
                        ContentState = ContentState.Modified;
                    }
                }
                if (ContentState == ContentState.Modified)
                {
                    outStream = ContentFileManager.OpenStream(spritePath, FileMode.Create);
                    await Task.Run(SaveSprite);
                    outStream.Dispose();
                    ContentState = ContentState.Unmodified;
                }
                File = file;
                _contentServices.UndoService.ClearStack();
            }
            catch (Exception ex)
            {
                HostServices.MessageDisplay.ShowError(ex, Resources.GORSPR_ERR_CREATE_SPRITE);
                await CloseContentCommand.ExecuteAsync(new CloseContentArgs(false));
            }
            finally
            {
                HideWaitPanel();
            }
        }

