internal override bool DecodeArgument(byte b)
        {
            switch (_receivedStep)
            {
                case Steps.Status: // receive status
                    _lastValue = new SharerReadVariableReturn();
                    Values.Add(_lastValue);

                    _lastValue.Status = (SharerReadVariableStatus)b;

                    // if the we have a value, go to next step to decode, else stay to have next variable
                    if (_lastValue.Status == SharerReadVariableStatus.OK)
                    {
                        _lastValueType = _types[Values.Count - 1];
                        _lastValueSize = SharerTypeHelper.Sizeof(_lastValueType);
                        _lastValueBytes.Clear();
                        _receivedStep = Steps.Value;
                    }
                    else if (Values.Count >= _types.Length)
                    {
                        _receivedStep = Steps.End;
                    }

                    break;
                case Steps.Value:
                    _lastValueBytes.Add(b); // add received byte

                    // if enought returned byte, decode it 
                    if (_lastValueBytes.Count >= _lastValueSize)
                    {
                        _lastValue.Value = SharerTypeHelper.Decode(_lastValueType, _lastValueBytes.ToArray());

                        if (Values.Count >= _types.Length)
                        {
                            _receivedStep = Steps.End;
                        }
                        else
                        {
                            _receivedStep = Steps.Status;
                        }
                    }
                    break;
            }

            return _receivedStep == Steps.End;
        }

public static Predicate<Connectivity> hasState(final NetworkInfo.State... states) {
    return new Predicate<Connectivity>() {
      @Override public boolean test(@NonNull Connectivity connectivity) throws Exception {
        for (NetworkInfo.State state : states) {
          if (connectivity.state() == state) {
            return true;
          }
        }
        return false;
      }
    };
  }

/**
 * Base class for GoogleAdsException. Provides a generic holder for GoogleAdsFailures which can be
 * replaced with statically typed subclasses for a specific version of GoogleAdsFailure.
 */
public abstract class GoogleAdsException extends RuntimeException {

    private final int errorCode;

    public GoogleAdsException(int errorCode) {
        super();
        this.errorCode = errorCode;
    }

    public int getErrorCode() {
        return errorCode;
    }

    // This class should be replaced with specific exceptions
    public static class RuntimeExceptionGoogleAdsException extends GoogleAdsException {
        public RuntimeExceptionGoogleAdsException(int errorCode) {
            super(errorCode);
        }
    }
}

def url(url, **param_mapping):
    def inner(handler):
        handler._appended_url = url
        if param_mapping:
            if hasattr(handler, '_param_mapping'):
                handler._param_mapping = handler._param_mapping.copy()
                handler._param_mapping.update(param_mapping)
            else:
                handler._param_mapping = param_mapping.copy()
        def fn_wrapper(fn):
            @functools.wraps(fn)
            def fn_inner(*args, **kwargs):
                if hasattr(handler, '_param_mapping'):
                    for key, value in kwargs.iteritems():
                        if key in handler._param_mapping:
                            kwargs[key] = handler._param_mapping[key](value)
                return fn(*args, **kwargs)
            return fn_inner
        full_url = ''
        for base in reversed(handler.mro()):
            try:
                if base._appended_url != '/':
                    full_url += base._appended_url
                elif base is handler:
                    full_url = base._appended_url
                    break
            except AttributeError:
                pass
            for method in webapp2.WSGIApplication.allowed_methods:
                method = method.lower()
                if base is handler:
                    break
                try:
                    if(getattr(base, method).im_func is
                       getattr(handler, method).im_func):
                        setattr(handler, method, None)
                except AttributeError:
                    pass
        for method in webapp2.WSGIApplication.allowed_methods:
            method = method.lower()
            try:
                setattr(handler, method, fn_wrapper(getattr(handler, method)))
            except AttributeError:
                pass
        _handlers.add(handler)
        handler.url = full_url
        return handler
    return inner

