private void UpdateSessionInfoLabel(ARFrame frame, ARTrackingState trackingState, ARTrackingStateReason trackingStateReason)
        {
            // Update the UI to provide feedback on the state of the AR experience.
            string message = null;

            switch (trackingState)
            {
                case ARTrackingState.Normal:
                    if (!frame.Anchors.Any() && !this.multipeerSession.ConnectedPeers.Any())
                    {
                        // No planes detected; provide instructions for this app's AR interactions.
                        message = "Move around to map the environment, or wait to join a shared session.";
                    }
                    else if (this.multipeerSession.ConnectedPeers.Any() && this.mapProvider == null)
                    {
                        var peerNames = this.multipeerSession.ConnectedPeers.Select(peer => peer.DisplayName);
                        message = $"Connected with {string.Join(", ", peerNames)}.";
                    }
                    break;

                case ARTrackingState.NotAvailable:
                    message = "Tracking unavailable.";
                    break;

                case ARTrackingState.Limited:
                    switch (trackingStateReason)
                    {
                        case ARTrackingStateReason.ExcessiveMotion:
                            message = "Tracking limited - Move the device more slowly.";
                            break;
                        case ARTrackingStateReason.InsufficientFeatures:
                            message = "Tracking limited - Point the device at an area with visible surface detail, or improve lighting conditions.";
                            break;

                        case ARTrackingStateReason.Initializing:
                            if (this.mapProvider != null)
                            {
                                message = $"Received map from {this.mapProvider.DisplayName}.";
                            }
                            else
                            {
                                message = "Initializing AR session.";
                            }
                            break;

                        case ARTrackingStateReason.Relocalizing:

                            if (this.mapProvider != null)
                            {
                                message = $"Received map from {this.mapProvider.DisplayName}.";
                            }
                            else
                            {
                                message = "Resuming session — move to where you were when the session was interrupted.";
                            }
                            break;

                        default:
                            break;
                    }

                    break;

                default:
                    // No feedback needed when tracking is normal and planes are visible.
                    // (Nor when in unreachable limited-tracking states.)
                    message = "";
                    break;
            }

            this.sessionInfoLabel.Text = message;
            this.sessionInfoView.Hidden = string.IsNullOrEmpty(message);
        }

'use strict';

const gulp = require('gulp');
const plumber = require('gulp-plumber');
const error = require('./../utility/error');
const postcss = require('gulp-postcss');
const atImport = require('postcss-import');
const willChange = require('postcss-will-change'); // fallback will-change
const autoprefixer = require('autoprefixer');
const csso = require('postcss-csso');
const flexbugs = require('postcss-flexbugs-fixes');

const name = 'style';
const files = 'source/*.css';
const wFiles = '{source,temp}/**/*.css'; // temp: стили для спрайта
const there = 'public';
const production = process.env.NODE_ENV === 'production';
const options = [atImport({path: ['source']})];
const browsers = [
  'ie >= 10',
  'ff >= 30',
  'chrome >= 34',
  'safari >= 7',
  'opera >= 23',
  'ios >= 7',
  'android >= 4.4'
];

if (production) {
  options.push(
    willChange,
    autoprefixer({browsers: browsers}),
    csso,
    flexbugs
  )
}

gulp.task(name, function() {
  return gulp.src(files)
  .pipe(plumber({errorHandler: error}))
  .pipe(postcss(options))
  .pipe(gulp.dest(there))
});

if (!production) {
  gulp.watch(wFiles, gulp.series(name));
}

using System;
using App.Metrics.AspNetCore.Tracking;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace Microsoft.AspNetCore.Hosting
{
    public static class CustomMetricsWebHostBuilderExtensions
    {
        /// <summary>
        /// Configures custom metrics web tracking with default settings.
        /// </summary>
        /// <param name="builder">The IWebHostBuilder instance.</param>
        /// <returns>The updated IWebHostBuilder instance.</returns>
        public static IWebHostBuilder UseCustomMetricsWebTracking(this IWebHostBuilder builder)
        {
            return UseCustomMetricsWebTracking(builder, null);
        }

        /// <summary>
        /// Configures custom metrics web tracking with a specific configuration.
        /// </summary>
        /// <param name="builder">The IWebHostBuilder instance.</param>
        /// <param name="configuration">An optional configuration for metrics.</param>
        /// <returns>The updated IWebHostBuilder instance.</returns>
        public static IWebHostBuilder UseCustomMetricsWebTracking(this IWebHostBuilder builder, IConfiguration configuration)
        {
            return builder.ConfigureServices(services =>
            {
                // Register default metrics setup
                services.AddMetricsTracking(configuration);
                services.AddSingleton<IMetricsTrackingStartupFilter, DefaultMetricsTrackingStartupFilter>();

                // Add custom middleware
                services.AddTransient<CustomMetricsMiddleware>();
            });
        }

        /// <summary>
        /// Configures custom metrics web tracking with a defined options delegate.
        /// </summary>
        /// <param name="builder">The IWebHostBuilder instance.</param>
        /// <param name="setupAction">An action to configure metrics options.</param>
        /// <returns>The updated IWebHostBuilder instance.</returns>
        public static IWebHostBuilder UseCustomMetricsWebTracking(this IWebHostBuilder builder, Action<MetricsTrackingOptions> setupAction)
        {
            return builder.ConfigureServices(services =>
            {
                // Register metrics with custom configuration
                services.AddMetricsTracking(setupAction);
                services.AddSingleton<IMetricsTrackingStartupFilter, CustomMetricsTrackingStartupFilter>();

                // Add middleware
                services.AddTransient<CustomMetricsMiddleware>();
            });
        }

        /// <summary>
        /// Configures custom metrics web tracking with a combination of configuration and options delegate.
        /// </summary>
        /// <param name="builder">The IWebHostBuilder instance.</param>
        /// <param name="configuration">The configuration for metrics.</param>
        /// <param name="setupAction">An action to configure additional options.</param>
        /// <returns>The updated IWebHostBuilder instance.</returns>
        public static IWebHostBuilder UseCustomMetricsWebTracking(this IWebHostBuilder builder, IConfiguration configuration, Action<MetricsTrackingOptions> setupAction)
        {
            if (builder == null) throw new ArgumentNullException(nameof(builder));
            if (setupAction == null) throw new ArgumentNullException(nameof(setupAction));

            return builder.ConfigureServices(services =>
            {
                // Register metrics with both configuration and additional setups
                services.AddMetricsTracking(configuration, setupAction);
                services.AddSingleton<IMetricsTrackingStartupFilter, CustomMetricsTrackingStartupFilter>();

                // Add middleware
                services.AddTransient<CustomMetricsMiddleware>();
            });
        }
    }
}

public static String fixSourceIdForMapping(String fromDb, String fromId) {
    Assert.hasText(fromId, "fromId is empty");
    Assert.hasText(fromDb, "fromDb is empty");
    String id = fromId;
    String db = fromDb.toUpperCase();
    if (db.startsWith("UNIPROT") || db.contains("SWISSPROT") || db.contains("TREMBL")) {
      if (id.contains("-"))
        id = id.replaceFirst("-\\d+$", "");
    } else if (db.equals("REFSEQ") && id.contains(".")) {
      id = id.replaceFirst("\\.\\d+$", "");
    } else if (db.startsWith("KEGG") && id.matches(":\\d+$")) {
      id = id.substring(id.lastIndexOf(':') + 1); 
    } else if (db.contains("PUBCHEM") && (db.contains("SUBSTANCE") || db.contains("SID"))) {
      id = id.toUpperCase(); 
      if (!id.startsWith("SID:") && id.matches("^\\d+$"))
        id = "SID:" + id;
    } else if (db.contains("PUBCHEM") && (db.contains("COMPOUND") || db.contains("CID"))) {
      id = id.toUpperCase(); 
      if (!id.startsWith("CID:") && id.matches("^\\d+$"))
        id = "CID:" + id;
    }
    return id;
  }

DdNode *
cuddAddRoundOffRecur(DdManager *dd, DdNode *f, int precision)
{
    DdNode *res, *fv, *fvn, *T, *E;
    unsigned int index;
    double value;

    /* Check for terminal case */
    if (cuddIsConstant(f)) {
        value = cuddV(f);
        value = round(value * pow(10, precision)) / pow(10, precision);
        res = cuddUniqueConst(dd, value);
        return res;
    }

    /* Recursive step */
    fv = cuddT(f);
    fvn = cuddE(f);
    index = f->index;

    T = cuddAddRoundOffRecur(dd, fv, precision);
    if (T == NULL) return NULL;
    cuddRef(T);

    E = cuddAddRoundOffRecur(dd, fvn, precision);
    if (E == NULL) {
        Cudd_RecursiveDeref(dd, T);
        return NULL;
    }
    cuddRef(E);

    res = cuddUniqueInter(dd, index, T, E);
    if (res == NULL) {
        Cudd_RecursiveDeref(dd, T);
        Cudd_RecursiveDeref(dd, E);
        return NULL;
    }
    cuddDeref(T);
    cuddDeref(E);

    return res;
}

