#include <QHeaderView>
#include "QmitkBaseTreeWidget.h"
#include "QmitkBaseItemDelegate.h"
#include "QmitkNoEditItemDelegate.h"
#include "QmitkSceneTreeWidget.h"

QmitkBaseTreeWidget::QmitkBaseTreeWidget(QWidget* parent)
  : QTreeWidget(parent),
    m_Base(nullptr)
{
  this->setItemDelegateForColumn(0, new QmitkNoEditItemDelegate);
  this->setItemDelegateForColumn(1, new QmitkBaseItemDelegate);

  this->setSortingEnabled(true);
  this->header()->setSortIndicator(0, Qt::AscendingOrder);
}

QmitkBaseTreeWidget::~QmitkBaseTreeWidget()
{
}

void QmitkBaseTreeWidget::clear()
{
  m_Base = nullptr;
  m_GroupItemMap.clear();

  QTreeWidget::clear();
}

void QmitkBaseTreeWidget::OnSelectedBaseChanged(Base* base)
{
  this->clear();

  m_Base = base;

  if (base != nullptr)
    this->FillTreeWidget();
}

void QmitkBaseTreeWidget::FillTreeWidget()
{
  const Base::VecData& dataFields = m_Base->getDataFields();

  for (auto dataField = dataFields.begin(); dataField != dataFields.end(); ++dataField)
  {
    if (!(*dataField)->isDisplayed())
      continue;

    QString name = QString::fromStdString((*dataField)->getName());

    if (name.isEmpty())
      continue;

    QString group = (*dataField)->getGroup();

    if (!group.isEmpty() && !m_GroupItemMap.contains(group))
      m_GroupItemMap.insert(group, new QTreeWidgetItem(this, QStringList() << group));

    QTreeWidgetItem* item = new QTreeWidgetItem(QStringList() << name);
    item->setToolTip(0, (*dataField)->getHelp());

    item->setFlags(!(*dataField)->isReadOnly()
      ? item->flags() | Qt::ItemIsEditable
      : Qt::ItemIsSelectable);

    QString type = QString::fromStdString((*dataField)->getValueTypeString());

    if (type == "bool")
    {
      item->setFlags((item->flags() & ~Qt::EditRole) | Qt::ItemIsUserCheckable);
      item->setCheckState(1, (*dataField)->getValueString() == "1" ? Qt::Checked : Qt::Unchecked);
    }
    else
    {
      if (type == "double" || type == "float" || type == "int" || type == "string" || type == "unsigned int")
      {
        item->setData(1, Qt::DisplayRole, QVariant::fromValue(QString::fromStdString((*dataField)->getValueString())));
      }
      else
      {
        item->setData(1, Qt::DisplayRole, QVariant::fromValue("[" + type + "]"));
      }

      item->setData(1, Qt::UserRole, QVariant::fromValue(*dataField));
    }

    if (group.isEmpty())
    {
      this->addTopLevelItem(item);
    }
    else
    {
      m_GroupItemMap[group]->addChild(item);
    }
  }

  this->setRootIsDecorated(!m_GroupItemMap.isEmpty());
  this->expandAll();
}

package livegollection

import (
	"context"
	"encoding/json"
	"log"
	"net/http"

	"github.com/gorilla/websocket"
)

// Item is an interface for items in a collection.
type Item interface {
	ID() string
}

// Collection is an interface for a collection of items.
type Collection interface {
	All() []Item
	Item(id string) Item
	Create(item Item) error
	Update(item Item) error
	Delete(id string) error
}

// LiveGollection is a type that handles client connections and updates.
type LiveGollection struct {
	ctx    context.Context
	c      Collection
	logger *log.Logger
	clients    map[*websocket.Conn]bool
	updaterCh chan struct{}
}

// NewLiveGollection returns a new LiveGollection instance.
func NewLiveGollection(ctx context.Context, c Collection, logger *log.Logger) *LiveGollection {
	return &LiveGollection{
		ctx:    ctx,
		c:      c,
		logger: logger,
		clients:    make(map[*websocket.Conn]bool),
		updaterCh: make(chan struct{}),
	}
}

// Join establishes a websocket connection and sends initial data to the client.
func (l *LiveGollection) Join(w http.ResponseWriter, r *http.Request) {
	conn, err := websocket.Upgrade(w, r, nil, 1024, 1024)
	if err!= nil {
		l.logger.Println(err)
		return
	}
	defer conn.Close()

	l.clients[conn] = true
	defer delete(l.clients, conn)

	// Send initial data to the client
	data, err := json.Marshal(l.c.All())
	if err!= nil {
		l.logger.Println(err)
		return
	}
	if err := conn.WriteMessage(websocket.TextMessage, data); err!= nil {
		l.logger.Println(err)
		return
	}

	go func() {
		for {
			select {
			case <-l.updaterCh:
				data, err := json.Marshal(l.c.All())
				if err!= nil {
					l.logger.Println(err)
					return
				}
				if err := conn.WriteMessage(websocket.TextMessage, data); err!= nil {
					l.logger.Println(err)
					return
				}
			case <-l.ctx.Done():
				return
			}
		}
	}()

	for {
		_, message, err := conn.ReadMessage()
		if err!= nil {
			l.logger.Println(err)
			return
		}

		var item Item
		if err := json.Unmarshal(message, &item); err!= nil {
			l.logger.Println(err)
			return
		}

		switch message[0] {
		case 'c': // Create
			if err := l.c.Create(item); err!= nil {
				l.logger.Println(err)
			}
		case 'u': // Update
			if err := l.c.Update(item); err!= nil {
				l.logger.Println(err)
			}
		case 'd': // Delete
			if err := l.c.Delete(item.ID()); err!= nil {
				l.logger.Println(err)
			}
		}

		l.updaterCh <- struct{}{}
	}
}

// updatesHandler listens for incoming update messages.
func (l *LiveGollection) updatesHandler(w http.ResponseWriter, r *http.Request) {
	conn, err := websocket.Upgrade(w, r, nil, 1024, 1024)
	if err!= nil {
		l.logger.Println(err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err!= nil {
			l.logger.Println(err)
			return
		}

		var item Item
		if err := json.Unmarshal(message, &item); err!= nil {
			l.logger.Println(err)
			return
		}

		switch message[0] {
		case 'c': // Create
			if err := l.c.Create(item); err!= nil {
				l.logger.Println(err)
			}
		case 'u': // Update
			if err := l.c.Update(item); err!= nil {
				l.logger.Println(err)
			}
		case 'd': // Delete
			if err := l.c.Delete(item.ID()); err!= nil {
				l.logger.Println(err)
			}
		}

		l.updaterCh <- struct{}{}
	}
}

public void addOperation(String operation, float... values) {
        String string;
        int nValues = values.length;
        int count = 1;
        int OperatorSize = Operators.size();
        boolean wasEmptyList = Operators.isEmpty();
        /* Check if operation does not exist: */
        if (!Objects.equals(operation, Operation.ADD.getOp()) &&
                !Objects.equals(operation, Operation.SUB.getOp()) &&
                !Objects.equals(operation, Operation.MUL.getOp()) &&
                !Objects.equals(operation, Operation.DIV.getOp())) {
            throw new IllegalArgumentException();
        }
        Operations.add(operation);
        string = "[" + operation + "]";
        for (Float value : values) {
            /* Check if two values were introduced
             * and it was not the first operation: */
            if (!wasEmptyList && nValues == 2) {
                Operators.add(value);
                string = string.concat(value.toString());
                break;
            }
            Operators.add(value);
            string = string.concat(value.toString());
            /* Space for the first operation: */
            if (nValues == 2 && count == 1) {
                string = string.concat("_");
            }
            count++;
        }
        if (nValues == 2) {
            OperatorSize++;
        }
        InternalState.add(string);
        /* Check if the operation is a division by 0: */
        if (Objects.equals(operation, Operation.DIV.getOp()) &&
                Operators.get(OperatorSize) == 0) {
            InternalState.remove(string);
        }
    }

