def binary_search(nums, target):
    left = 0
    right = len(nums) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] > target:
            right = mid - 1
        else:
            left = mid + 1
    return -1


def findFirst(nums, target):
    left = 0
    right = len(nums) - 1
    result = len(nums)
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            result = min(result, mid)
            right = mid - 1
        else:
            left = mid + 1
    return result


def findLast(nums, target):
    left = 0
    right = len(nums) - 1
    result = -1
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            result = max(result, mid)
            left = mid + 1
        else:
            right = mid - 1
    return result

def searchRange(nums, target):
    return [findFirst(nums, target), findLast(nums, target)]
