class Solution:
    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
        a = l1
        b = l2
        c = ListNode(0)
        node = c
        while a or b:
            if a:
                c.val += a.val
                a = a.next
            if b:
                c.val += b.val
                b = b.next
            c.next = ListNode(c.val // 10)
            c.val %= 10
            c = c.next
        if c.val:
            return node
        else:
            return node.next
