        Class<?> patchedGeneratorClass = createPatchedGenerator(generatorClass, generatorName);
        Constructor<?> patchedConstructor = patchedGeneratorClass.getConstructor(long.class);
        Object patchedGenerator = patchedConstructor.newInstance(world.getSeed());

        Field field = world.getClass().getDeclaredField("a"); //This reflects to a private field in World class. May need adjustment depending on obfuscation.
