        Method registerMethod = worldGenRegistry.getClass().getDeclaredMethod("a", Class.class, Object.class); //a is likely the register method
        registerMethod.setAccessible(true);
        registerMethod.invoke(worldGenRegistry, generatorClass, patchedGenerator);
    }



