const debug = require('debug')('accessLogger');
const { performance } = require('perf_hooks');

const accessLogger = (req, res, next) => {
    const startTime = performance.now();
    const accessToken = req.headers['accessToken'];

    if (accessToken) {
        debug(`Request Method: ${req.method}`);
        debug(`Request URL: ${req.originalUrl}`);
        debug(`Access Token: ${accessToken}`);
    }

    const logResponseTime = () => {
        const duration = performance.now() - startTime;
        debug(`Response Status: ${res.statusCode} - Duration: ${duration.toFixed(3)} ms`);
        res.removeListener('finish', logResponseTime);
    };

    res.on('finish', logResponseTime);
    next();
};

module.exports = accessLogger;

