			throws PersistenceException, SQLException, TransactionException {

		super.beginTransaction(entityManager, definition);
		if (!definition.isReadOnly() && !this.lazyDatabaseTransaction) {
			// This is the magic bit. As with the existing Spring TopLink integration,
			// begin an early transaction to force EclipseLink to get a JDBC Connection
			// so that Spring can manage transactions with JDBC as well as EclipseLink.
			UnitOfWork uow = (UnitOfWork) getSession(entityManager);
			uow.beginEarlyTransaction();
		}
		// Could return the UOW, if there were any advantage in having it later.
		return null;
	}

import React from 'react';
import {
  Card,
  CardHeader,
  CardTitle,
} from 'reactstrap';

import Form from './form';
import { ComponentLoading } from "components/loading";

class QuickAddProgram extends React.Component {
  componentDidMount() {
    const {
      optionsProgramTemplates,
      fetchProgramTemplates,
      isFetchingProgramTemplates,
    } = this.props;

    if (!optionsProgramTemplates && isFetchingProgramTemplates !== true) {
      fetchProgramTemplates();
    }
  }
  render() {
    const { schoolCode, year, optionsProgramTemplates, onAddProgram,
      isFetchingProgramTemplates,
      title = 'Add another',
      onSubmitSuccess,
    } = this.props;

    return (



          {isFetchingProgramTemplates !== false ?
            <ComponentLoading /> :
            <Form optionsPrograms={optionsProgramTemplates}
                  onSubmit={onAddProgram}
                  model={{
                    schoolCode,
                    year,
                  }}
                  onSubmitSuccess={onSubmitSuccess}
            />
          }


    )
  }
}

