setrecursionlimit(10 ** 7)
MOD = 10 ** 9 + 7

def main():
    t = int(stdin.readline().strip())
    for _ in range(t):
        n = int(stdin.readline().strip())
        arr = []
        for _ in range(n):
            arr.append(int(stdin.readline().strip()))
        if isComplete(arr):
            print(" ".join(map(str, arr)))
        else:
            print("Impossible")

def isComplete(arr):
    if len(arr) == 1:
        return True
    for i in range(len(arr)):
        for j in range(len(arr)):
            if i != j:
                for k in range(len(arr)):
                    if k != i and k != j:
                        if arr[i] + arr[j] != arr[k]:
                            return False
    return True

if __name__ == '__main__':
    main()

static Map<String, Object> mergeParameters(BrokerConfig brokerConfig, ServiceDefinitionProxy service, PlanProxy plan, Map<String, Object> requestParameters) {
        Map<String, Object> ret = new HashMap<>(brokerConfig.getSettings());
        if (requestParameters != null) ret.putAll(requestParameters);
        ret.putAll(plan.getServiceSettings());
        ret.putAll(service.getServiceSettings());
        List<Map<String, String>> tags = mergeBucketTags(service, plan, requestParameters);
        if (tags != null) {
            ret.put(TAGS, tags);
        }
        List<Map<String, String>> searchMetadata = mergeSearchMetadata(service, requestParameters);
        if (searchMetadata != null) {
            ret.put(SEARCH_METADATA, searchMetadata);
        }
        return ret;
    }

func (c *Consumer) sendTopicClaimsLoop() {
	defer close(c.topicClaimsChan)
	lastClaims := make(map[string]bool)
	keepRunning := true
	for keepRunning {
		select {
		case <-c.topicClaimsUpdated:
		case <-c.stopChan:
			keepRunning = false
		}
		claims, err := c.GetCurrentTopicClaims()
		if err != nil {
			log.Errorf("Failed to send topic claims update: %s", err)
			continue
		}
		anyUpdates := false
		for topic, claimed := range lastClaims {
			stillClaimed, ok := claims[topic]
			if !ok {
				anyUpdates = true
			} else if claimed != stillClaimed {
				anyUpdates = true
			}
		}
		for topic := range claims {
			if _, ok := lastClaims[topic]; !ok {
				anyUpdates = true
			}
		}
		lastClaims = claims
		if !anyUpdates {
			continue
		}
		select {
		case <-c.topicClaimsChan:
		default:
		}
		c.topicClaimsChan <- claims
	}
}

