inline dx::d3dfmt remap_four_cc(dx::d3dfmt FourCC)
	{
		switch(FourCC)
		{
		default:
			return FourCC;
		case dx::D3DFMT_BC4U:
			return dx::D3DFMT_ATI1;
		case dx::D3DFMT_BC4S:
			return dx::D3DFMT_AT1N;
		case dx::D3DFMT_BC5U:
			return dx::D3DFMT_ATI2;
		case dx::D3DFMT_BC5S:
			return dx::D3DFMT_AT2N;
		}
	}

import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter output = new BufferedWriter(new OutputStreamWriter(System.out));
        int testCount = Integer.parseInt(input.readLine());
        for (int testIndex = 0; testIndex < testCount; testIndex++) {
            String[] s = input.readLine().split(" ");
            int n = Integer.parseInt(s[0]);
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = Integer.parseInt(s[i + 1]);
            }
            if (check(a) == true) {
                output.write("0");
            } else {
                output.write("1");
            }
        }
        output.flush();
    }

    public static boolean check(int[] a) {
        boolean flag = false;
        int sum = 0;
        int[] new_a = new int[a.length];
        for (int i = 0; i < a.length; i++) {
            sum += a[i];
            if (sum == 0) {
                flag = true;
            }
        }
        if (flag == true) {
            return true;
        } else {
            return false;
        }
    }
}




