// Tests ReRegisterForFinalize()

using System;

public class Test
{
    public class Dummy
    {
        public static int flag;

        ~Dummy()
        {
            Console.WriteLine("In Finalize() of Dummy");
            if (flag == 0)
                flag = 1; // one object has visited;
            else
                flag = 0; //error-- both objects have visited
        }
    }

    public class CreateObj
    {
        Dummy obj1;
        Dummy obj2;

        public CreateObj()
        {
            obj1 = new Dummy();
            obj2 = new Dummy();

            GC.SuppressFinalize(obj1); // should not call the Finalize() for obj1
            GC.SuppressFinalize(obj2); // should not call the Finalize() for obj2
        }

        public bool RunTest()
        {
            GC.ReRegisterForFinalize(obj1); // should call Finalize() for obj1 now.

            obj1 = null;
            obj2 = null;

            GC.Collect();

            GC.WaitForPendingFinalizers(); // call all Finalizers.

            if (Dummy.flag == 1)
            {
                return true;
            }
            else
            {
                return false;
            }
        }
    }

    public static int Main()
    {
        CreateObj temp = new CreateObj();
        bool passed = temp.RunTest();

        if (passed)
        {
            Console.WriteLine("Test for ReRegisterForFinalize() passed!");
            return 100;
        }
        else
        {
            Console.WriteLine("Test for ReRegisterForFinalize() failed!");
            return 1;
        }
    }
}

ssize_t GSOInplacePacketBatchWriter::write(
    folly::AsyncUDPSocket& sock,
    const folly::SocketAddress& address) {
  ScopedBufAccessor scopedBufAccessor(conn_.bufAccessor);
  CHECK(lastPacketEnd_);
  auto& buf = scopedBufAccessor.buf();
  CHECK(!buf->isChained());
  CHECK(lastPacketEnd_ >= buf->data() && lastPacketEnd_ <= buf->tail())
      << "lastPacketEnd_=" << (long)lastPacketEnd_
      << " data=" << (long long)buf->data()
      << " tail=" << (long long)buf->tail();
  uint64_t diffToEnd = buf->tail() - lastPacketEnd_;
  CHECK(
      diffToEnd <= conn_.udpSendPacketLen ||
      (nextPacketSize_ && diffToEnd == nextPacketSize_))
      << "diffToEnd=" << diffToEnd << ", pktLimit=" << conn_.udpSendPacketLen
      << ", nextPacketSize_=" << nextPacketSize_;
  if (diffToEnd >= conn_.udpSendPacketLen + kPacketSizeViolationTolerance) {
    LOG(ERROR) << "Remaining buffer contents larger than udpSendPacketLen by "
               << (diffToEnd - conn_.udpSendPacketLen);
  }
  uint64_t diffToStart = lastPacketEnd_ - buf->data();
  buf->trimEnd(diffToEnd);
  auto bytesWritten = (numPackets_ > 1)
      ? sock.writeGSO(address, buf, static_cast<int>(prevSize_))
      : sock.write(address, buf);
  if (diffToEnd) {
    buf->trimStart(diffToStart);
    buf->append(diffToEnd);
    buf->retreat(diffToStart);
    auto bufLength = buf->length();
    CHECK_EQ(diffToEnd, bufLength)
        << "diffToEnd=" << diffToEnd << ", bufLength=" << bufLength;
    CHECK(
        bufLength <= conn_.udpSendPacketLen ||
        (nextPacketSize_ && bufLength == nextPacketSize_))
        << "bufLength=" << bufLength << ", pktLimit=" << conn_.udpSendPacketLen
        << ", nextPacketSize_=" << nextPacketSize_;
    CHECK(0 == buf->headroom()) << "headroom=" << buf->headroom();
  } else {
    buf->clear();
  }
  reset();
  return bytesWritten;
}

class Solution {
public:
    vector<vector<int>> p;
    long long jl(int x, int y){
        return labs(p[x][0] - p[y][0]) + labs(p[x][1] - p[y][1]);
    }

    int minCostConnectPoints(vector<vector<int>>& pp) {
        p = pp;
        long long f[1010], res = 0;
        bool done[1010];
        int i, j;
        int n=p.size();
        for (i = 0; i< n;++i){
            done[i] = false;
            f[i] = jl(0, i);
        }
        f[0] = 0;        
        for (int w = 0; w < n; ++w){
            j = -1;
            for (i = 0; i < n; ++i){
                if (done[i]) continue;
                if (j == -1 || f[i] < f[j]) j = i;
            }

            res += f[j];
            done[j] = true;
            for (i = 0; i < n; ++i){
                if (done[i]) continue;
                f[i] = min(f[i], jl(j, i));
            }
        }

        return res;
    }
};

