			int result = 0;
			result = userDao.checkrepeat(userBean,"userName");
			out.print(result);
		}else if(method.equals("checkEmail")){
			int result = 0;
			result = userDao.checkrepeat(userBean,"email");
			out.print(result);
		}else if(method.equals("checkLogin")){
			int result = 0;
			result = userDao.checkrepeat(userBean,"loginName");
			out.print(result);
