private bool ScanVersionLine ( String line ) {
			if ( !string.IsNullOrEmpty ( line ) ) {
				Match matcher = Regex.Match ( line, ADB_VERSION_PATTERN );
				if ( matcher.Success ) {
					int majorVersion = int.Parse ( matcher.Groups[1].Value );
					int minorVersion = int.Parse ( matcher.Groups[2].Value );
					int microVersion = int.Parse ( matcher.Groups[3].Value );
					if ( microVersion < ADB_VERSION_MICRO_MIN ) {
						String message = String.Format ( "Required minimum version of adb: {0}.{1}.{2}. Current version is {0}.{1}.{3}",
										majorVersion, minorVersion, ADB_VERSION_MICRO_MIN, microVersion );
						Log.LogAndDisplay ( LogLevel.Error, ADB, message );
					} else if ( ADB_VERSION_MICRO_MAX != -1 && microVersion > ADB_VERSION_MICRO_MAX ) {
						String message = String.Format ( "Required maximum version of adb: {0}.{1}.{2}. Current version is {0}.{1}.{3}", 
										majorVersion, minorVersion, ADB_VERSION_MICRO_MAX, microVersion );
						Log.LogAndDisplay ( LogLevel.Error, ADB, message );
					} else {
						VersionCheck = true;
					}
					return true;
				}
			}
			return false;
		}

class ParserDocHandler : public HandlerBase {
  private:
  int trigger = 0; 
  string dd; 
  string hh; 
  string vv; 
  string csvFileName = "csv.txt"; 
  XMLCh* gasDay = XMLString::transcode("gasDay"); 
  XMLCh* date = XMLString::transcode("date"); 
  XMLCh* time = XMLString::transcode("time"); 
  XMLCh* hour = XMLString::transcode("hour"); 
  XMLCh* amtP = XMLString::transcode("amountOfPower"); 
  XMLCh* value = XMLString::transcode("value"); 
  ofstream csv;
  string doubleHH(string HH) 
  {
    if (HH.length() == 1) {
      HH = "0" + HH;
    }
    return HH;
  }
  public:
    ParserDocHandler()
    {
      cout << "Start Parser..." << endl;
    }
    void startElement(const XMLCh* const name, AttributeList& atts)
    {
      if (XMLString::equals(name, gasDay)) { 
	char* message = XMLString::transcode(atts.getValue(date));
	dd = message;
	XMLString::release(&message);
      }
      else if (XMLString::equals(name, time)) {
	char* message = XMLString::transcode(atts.getValue(hour));
	hh = message;
	XMLString::release(&message);
      }
      else if (XMLString::equals(name, amtP)) {
	char* message = XMLString::transcode(atts.getValue(value));
	vv = message;
	XMLString::release(&message);
	trigger = 1; 
      }
      if (trigger == 1) { 
	csv.open(csvFileName, fstream::app);
	csv << dd << "; " << doubleHH(hh) << "; " << vv << "\n";
	csv.close();
	cout << dd << "; " << doubleHH(hh) << "; " << vv << "\n";
	trigger = 0;
      }
    }
    ~ParserDocHandler()
    {
      cout << "Write to CSV completed. Values were written to " << csvFileName << "." << endl;
      XMLString::release(&gasDay);
      XMLString::release(&date);
      XMLString::release(&time);
      XMLString::release(&hour);
      XMLString::release(&amtP);
      XMLString::release(&value);
    }
}

