int main()
{
	int x,n;
	string s;
	cin>>x>>s;
	n = s.length();
	int dp[n][11];
	memset(dp,0,sizeof dp);
	dp[0][x%11] = 1;
	FOR(i,1,n)
	{
		FOR(k,0,11)
		{
			int x = dp[i-1][k];
			dp[i][k] = x;
			if(s[i] == '?')
			{
				FOR(j,0,10)
				{
					dp[i][(k*10+j)%11] = x + dp[i-1][(k*10+j)%11];
				}
			}
			else
			{
				if(s[i] != '?')
				{
					dp[i][(k*10+s[i]-'0')%11] = dp[i-1][k];
				}
			}
		}
	}
	cout<<dp[n-1][0]<<endl;
