public bool ModifyStackSize(object? user, int slot, int quantity) {
			Item item = Items[slot];
			if ((quantity > 0 && !CanInteract(slot, Operation.Insert, user)) ||
			    (quantity < 0 && !CanInteract(slot, Operation.Remove, user)) ||
			    quantity == 0 || item.IsAir)
				return false;
			if (quantity < 0) {
				if (item.stack + quantity < 0) return false;
				item.stack += quantity;
				if (item.stack <= 0) item.TurnToAir();
			}
			else {
				int limit = MaxStackFor(slot, item);
				if (item.stack + quantity > limit) return false;
				item.stack += quantity;
			}
			return true;
		}

def keep_variables(sampleset: 'SampleSet', variables: Iterable[Variable]) -> 'SampleSet':
    if isinstance(variables, abc.Sequence):
        sort_labels = False  
    elif isinstance(variables, abc.Iterator):
        variables = list(variables)
        sort_labels = False
    else:
        variables = list(variables)
        sort_labels = True  
    try:
        return SampleSet.from_samples(
            (sampleset.samples(sorted_by=None)[:, variables], variables),
            vartype=sampleset.vartype,
            **sampleset.data_vectors,
            info=copy.deepcopy(sampleset.info),
            sort_labels=sort_labels,
            )
    except KeyError:
        v = next(v for v in variables if v not in sampleset.variables)
        raise ValueError(f'variables contains at least one variable, {v!r}, '
                         'not present in the sampleset')

TEST_P(SimpleURLLoaderTest, CloseClientPipeOrder) {
  enum class ClientCloseOrder {
    kBeforeData,
    kDuringData,
    kAfterData,
    kAfterBufferClosed,
  };
  const ClientCloseOrder kClientCloseOrder[] = {
      ClientCloseOrder::kBeforeData, ClientCloseOrder::kDuringData,
      ClientCloseOrder::kAfterData, ClientCloseOrder::kAfterBufferClosed,
  };
  const TestLoaderEvent kClientCloseEvents[] = {
      TestLoaderEvent::kResponseComplete,
      TestLoaderEvent::kResponseCompleteFailed,
      TestLoaderEvent::kResponseCompleteTruncated,
      TestLoaderEvent::kClientPipeClosed,
  };
  for (const auto close_client_order : kClientCloseOrder) {
    for (const auto close_client_event : kClientCloseEvents) {
      for (uint32_t bytes_received = 0; bytes_received < 3; bytes_received++) {
        for (int allow_partial_results = 0; allow_partial_results < 2;
             allow_partial_results++) {
          if (close_client_order == ClientCloseOrder::kDuringData &&
              bytes_received < 2) {
            continue;
          }
          MockURLLoaderFactory loader_factory(&scoped_task_environment_);
          std::vector<TestLoaderEvent> events;
          events.push_back(TestLoaderEvent::kReceivedResponse);
          events.push_back(TestLoaderEvent::kBodyBufferReceived);
          if (close_client_order == ClientCloseOrder::kBeforeData)
            events.push_back(close_client_event);
          for (uint32_t i = 0; i < bytes_received; ++i) {
            events.push_back(TestLoaderEvent::kBodyDataRead);
            if (i == 0 && close_client_order == ClientCloseOrder::kDuringData)
              events.push_back(close_client_event);
          }
          if (close_client_order == ClientCloseOrder::kAfterData)
            events.push_back(close_client_event);
          events.push_back(TestLoaderEvent::kBodyBufferClosed);
          if (close_client_order == ClientCloseOrder::kAfterBufferClosed)
            events.push_back(close_client_event);
          loader_factory.AddEvents(events);
          std::unique_ptr<SimpleLoaderTestHelper> test_helper =
              CreateHelperForURL(GURL("foo://bar/"));
          test_helper->SetAllowPartialResults(allow_partial_results);
          loader_factory.RunTest(test_helper.get());
          EXPECT_EQ(200, test_helper->GetResponseCode());
          if (close_client_event != TestLoaderEvent::kResponseComplete) {
            if (close_client_event ==
                TestLoaderEvent::kResponseCompleteFailed) {
              EXPECT_EQ(net::ERR_TIMED_OUT,
                        test_helper->simple_url_loader()->NetError());
            } else {
              EXPECT_EQ(net::ERR_FAILED,
                        test_helper->simple_url_loader()->NetError());
            }
            if (!allow_partial_results) {
              EXPECT_FALSE(test_helper->response_body());
            } else {
              ASSERT_TRUE(test_helper->response_body());
              EXPECT_EQ(std::string(bytes_received, 'a'),
                        *test_helper->response_body());
            }
          } else {
            EXPECT_EQ(net::OK, test_helper->simple_url_loader()->NetError());
            ASSERT_TRUE(test_helper->response_body());
            EXPECT_EQ(std::string(bytes_received, 'a'),
                      *test_helper->response_body());
          }
        }
      }
    }
  }
}

public class SerializerFormatter : SerializerAsync<byte[]>
    {
        public IFormatter Formatter { get; }
        private static ProfilerMarker m_markerSerialize;
        private static ProfilerMarker m_markerDeserialize;
#if ENABLE_PROFILER
        static SerializerFormatter()
        {
            m_markerSerialize = new ProfilerMarker("SerializerFormatter.Serialize");
            m_markerDeserialize = new ProfilerMarker("SerializerFormatter.Deserialize");
        }
#endif
        public SerializerFormatter()
        {
            Formatter = new BinaryFormatter();
        }
        public SerializerFormatter(IFormatter formatter)
        {
            Formatter = formatter ?? throw new ArgumentNullException(nameof(formatter));
        }
        protected override object OnSerialize(object target, IContext context)
        {
            return InternalSerialize(Formatter, target);
        }
        protected override object OnDeserialize(Type targetType, byte[] data, IContext context)
        {
            return InternalDeserialize(Formatter, targetType, data);
        }
        protected override Task<byte[]> OnSerializeAsync(object target, IContext context)
        {
            return Task.Run(() => InternalSerialize(Formatter, target));
        }
        protected override Task<object> OnDeserializeAsync(Type targetType, byte[] data, IContext context)
        {
            return Task.Run(() => InternalDeserialize(Formatter, targetType, data));
        }
        private static byte[] InternalSerialize(IFormatter formatter, object target)
        {
            m_markerSerialize.Begin();
            using var stream = new MemoryStream();
            formatter.Serialize(stream, target);
            byte[] result = stream.ToArray();
            m_markerSerialize.End();
            return result;
        }
        private static object InternalDeserialize(IFormatter formatter, Type targetType, byte[] data)
        {
            m_markerDeserialize.Begin();
            object result;
            if (data.Length > 0)
            {
                using var stream = new MemoryStream(data);
                result = formatter.Deserialize(stream);
            }
            else
            {
                result = Activator.CreateInstance(targetType);
            }
            m_markerDeserialize.End();
            return result;
        }
    }

