@ThreadSafe
public class PathDeltaRetriever implements DeltaRetriever<PathsUpdate> {

  private final SentryStoreInterface sentryStore;

  PathDeltaRetriever(SentryStoreInterface sentryStore) {
    this.sentryStore = sentryStore;
  }

  @Override
  public List<PathsUpdate> retrieveDelta(long seqNum, long imgNum) throws Exception {
    try (final Context timerContext =
                 SentryHdfsMetricsUtil.getDeltaPathChangesTimer.time()) {
      List<MSentryPathChange> mSentryPathChanges =
              sentryStore.getMSentryPathChanges(seqNum);

      SentryHdfsMetricsUtil.getDeltaPathChangesHistogram.update(mSentryPathChanges.size());

      if (mSentryPathChanges.isEmpty()) {
        return Collections.emptyList();
      }

      List<PathsUpdate> updates = new ArrayList<>(mSentryPathChanges.size());
      for (MSentryPathChange mSentryPathChange : mSentryPathChanges) {
        // Gets the changeID from the persisted MSentryPathChange.
        long changeID = mSentryPathChange.getChangeID();
        // Creates a corresponding PathsUpdate and deserialize the
        // persisted delta update in JSON format to TPathsUpdate with
        // associated changeID.
        PathsUpdate pathsUpdate = new PathsUpdate();
        pathsUpdate.JSONDeserialize(mSentryPathChange.getPathChange());
        pathsUpdate.setSeqNum(changeID);
        pathsUpdate.setImgNum(imgNum);
        updates.add(pathsUpdate);
      }
      return updates;
    }
  }

  @Override
  public boolean isDeltaAvailable ( long seqNum) throws Exception {
    return sentryStore.pathChangeExists(seqNum);
  }

  @Override
  public long getLatestDeltaID () throws Exception {
    return sentryStore.getLastProcessedPathChangeID();
  }
}

public class AgingData<TheUnit extends Unit> {
    TheUnit mValue;
    private Date mBirthdate;

    /**
     * Construct an instance of AgingData with the value of unit.
     *
     * @param value The data value for this bit of AgingData.
     */
    public AgingData(TheUnit value) {
        this(new Date(), value);
    }

    public AgingData(Date birthdate, TheUnit value) {
        mValue = value;
        mBirthdate = birthdate;
    }

    /**
     * Return the value this instance wraps.
     *
     * @return The wrapped value (an instance of TheUnit)
     */
    public TheUnit getValue() {
        return mValue;
    }

    /**
     * Retrieve the age of this piece of data.
     *
     * @return the age of the data in milliseconds.
     */
    public long getAge() {
        return (new Date()).getTime() - mBirthdate.getTime();
    }

    public long getTimestamp() {
        return mBirthdate.getTime();
    }

    public void setTimestamp(long timestamp) {
        if(timestamp != 0) {
            mBirthdate = new Date(timestamp);
        }
    }

    @Override
    public String toString() {
        return MoreObjects.toStringHelper(this)
            .add("value", mValue)
            .add("birthdate", mBirthdate)
            .toString();
    }
}

package performance;

import java.text.MessageFormat;
import java.util.HashMap;
import java.util.Map;


public class StringConcatenation {

  private static final String CONCATENATION = "\nConcatenation:";
  private static final String EXCLAMATORY = "!";
  private static final String TEST = "Test ";
  private static final String HELLO = "Hello";
  private static final String STRING_BUILDER = "\nStringBuilder:";
  private static final String STRING_BUFFER = "\nStringBuffer:";
  private static final String MESSAGEFORMAT = "\nMessageFormat:";
  private static final String NS = " ns";

  private static Map<String, Statements> ssMap;
  private static Map<String, Long> timeMap;

  public static void main(String[] args) {

    createStatements();
    timeMap = new HashMap<String, Long>();

    long time = TimeUtil.measureExecutionTime(MESSAGEFORMAT, ssMap.get(MESSAGEFORMAT));
    timeMap.put(MESSAGEFORMAT, time);

    time = TimeUtil.measureExecutionTime(STRING_BUFFER, ssMap.get(STRING_BUFFER));
    timeMap.put(STRING_BUFFER, time);

    time = TimeUtil.measureExecutionTime(STRING_BUILDER, ssMap.get(STRING_BUILDER));
    timeMap.put(STRING_BUILDER, time);

    time = TimeUtil.measureExecutionTime(CONCATENATION, ssMap.get(CONCATENATION));
    timeMap.put(CONCATENATION, time);


    long maxTime = TimeUtil.calculateMaxTime(timeMap.values());

    System.out.println("\nHow many times faster the given method according to the slowest method?");
    TimeUtil.printExecutionTimesComparison(timeMap, maxTime);

  }

  private static void createStatements() {
    ssMap = new HashMap<String, Statements>();

    String key = MESSAGEFORMAT;
    Statements value = new Statements() {

      @Override
      public void runStatements() {
        MessageFormat.format("{0}{1}{2}", TEST, HELLO, EXCLAMATORY);
      }
    };
    ssMap.put(key, value);

    key = STRING_BUFFER;
    value = new Statements() {

      @Override
      public void runStatements() {
        new StringBuffer(TEST).append(HELLO).append(EXCLAMATORY).toString();
      }
    };
    ssMap.put(key, value);

    key = STRING_BUILDER;
    value = new Statements() {

      @Override
      public void runStatements() {
        new StringBuilder(TEST).append(HELLO).append(EXCLAMATORY).toString();
      }
    };
    ssMap.put(key, value);

    key = CONCATENATION;
    value = new Statements() {

      @Override
      public void runStatements() {
        new String(TEST + HELLO + EXCLAMATORY);
      }
    };
    ssMap.put(key, value);
  }
}

(function ($, undefined) {
    "use strict";

    function ShapeEditor() {
        this.init = function (e, args) {
            this.dropdown = $("<select></select>");
            this.shapes = ['circle', 'square', 'triangle'];
            this.dropdown.html(this.shapes.map(function (shape) {
                return "<option value=\"" + shape + "\">" + shape.charAt(0).toUpperCase() + shape.slice(1) + "</option>";
            }).join(""));
            args.grid.setCellContent(args.node, this.dropdown);
            args.grid.getCellEditor(args.node).setEditor(this);
        };

        this.destroy = function (e, args) {
            args.grid.setCellContent(args.node, args.grid.getCellValue(args.node));
        };

        this.focus = function (e, args) {
            args.grid.getCellEditor(args.node).setActive(true);
        };

        this.focusout = function (e, args) {
            args.grid.getCellEditor(args.node).setActive(false);
        };

        this.isValueChanged = function (e, args) {
            return args.value !== args.grid.getCellValue(args.node);
        };

        this.serializeValue = function (e, args) {
            return args.value;
        };

        this.loadValue = function (e, args) {
            args.grid.setCellContent(args.node, args.grid.getCellValue(args.node));
        };

        this.applyValue = function (e, args) {
            args.grid.setCellValue(args.node, args.value);
            args.grid.trigger("onCellChange", args);
        };

        this.validate = function (e, args) {
            return this.shapes.indexOf(args.value) !== -1;
        };
    }

    function ShapeFormatter() {
        this.format = function (e, args) {
            var cellValue = args.cell;
            if (cellValue === null || cellValue === undefined) {
                return "";
            }
            var option = $("<option></option>").val(cellValue).html(cellValue.charAt(0).toUpperCase() + cellValue.slice(1));
            if (option.length === 0) {
                option = $("<option></option>").val("");
            }
            return option.prop("selected", true) ? option.html() : "";
        };
    }

    SlickGrid.prototype.getEditorFactory = function () {
        return {
            getEditor: function (e, args) {
                if (args.column.customEditor) {
                    return new ShapeEditor();
                }
                return null;
            },
            getFormatter: function (e, args) {
                if (args.column.formatter === "shape") {
                    return new ShapeFormatter();
                }
                return null;
            }
        };
    };
})(jQuery);

public class MongoRestxSpecTestsRunner extends RestxSpecTestsRunner {

    private final TestRule rule;

    public MongoRestxSpecTestsRunner(Class<?> pTestClass) throws InitializationError, IllegalAccessException, InvocationTargetException, InstantiationException, NoSuchFieldException, IOException {
        super(pTestClass);
        MongoVersion mongoVersion = getTestClass().getJavaClass().getAnnotation(MongoVersion.class);
        if (mongoVersion != null) {
            rule = new MongoEmbedRule(mongoVersion.value());
        } else {
            rule = new MongoEmbedRule();
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    protected List<TestRule> classRules() {
        List<TestRule> rules = super.classRules();
        rules.add(rule);
        return rules;
    }

}

private void createTimeSlot (ArrayList<MAssignmentSlot> list,
		Timestamp startTime, Timestamp endTime)
	{
		GregorianCalendar cal = new GregorianCalendar(Language.getLoginLanguage().getLocale());
		cal.setTimeInMillis(m_startDate.getTime());
		GregorianCalendar calEnd = new GregorianCalendar(Language.getLoginLanguage().getLocale());
		calEnd.setTimeInMillis(m_endDate.getTime());
		while (cal.before(calEnd))
		{
			cal.set(Calendar.HOUR_OF_DAY, 0);
			cal.set(Calendar.MINUTE, 0);
			cal.set(Calendar.SECOND, 0);
			cal.set(Calendar.MILLISECOND, 0);
			Timestamp start = new Timestamp (cal.getTimeInMillis());
			GregorianCalendar cal_1 = new GregorianCalendar(Language.getLoginLanguage().getLocale());
			cal_1.setTimeInMillis(startTime.getTime());
			cal.set(Calendar.HOUR_OF_DAY, cal_1.get(Calendar.HOUR_OF_DAY));
			cal.set(Calendar.MINUTE, cal_1.get(Calendar.MINUTE));
			cal.set(Calendar.SECOND, cal_1.get(Calendar.SECOND));
			Timestamp end = new Timestamp (cal.getTimeInMillis());
			MAssignmentSlot	ma = new MAssignmentSlot (start, end,
				Msg.getMsg(m_ctx, "ResourceNotInSlotTime"), "",
				MAssignmentSlot.STATUS_NotInSlotTime);
			list.add(ma);
				endTime .. 00:00 next day
			cal_1.setTimeInMillis(endTime.getTime());
			cal.set(Calendar.HOUR_OF_DAY, cal_1.get(Calendar.HOUR_OF_DAY));
			cal.set(Calendar.MINUTE, cal_1.get(Calendar.MINUTE));
			cal.set(Calendar.SECOND, cal_1.get(Calendar.SECOND));
			start = new Timestamp (cal.getTimeInMillis());
			cal.set(Calendar.HOUR_OF_DAY, 0);
			cal.set(Calendar.MINUTE, 0);
			cal.set(Calendar.SECOND, 0);
			cal.add(Calendar.DAY_OF_YEAR, 1);
			end = new Timestamp (cal.getTimeInMillis());
			ma = new MAssignmentSlot (start, end,
				Msg.getMsg(m_ctx, "ResourceNotInSlotTime"), "",
				MAssignmentSlot.STATUS_NotInSlotTime);
			list.add(ma);
		}
	}

