import React from 'react';
import { LeaderBoard } from './LeaderBoard';
import { PlayersByRole } from './PlayersByRole';

const rankPlayers = (players) => {
  const sortedPlayers = players.sort((a, b) => b.gold - a.gold);
  const rankedPlayers = sortedPlayers.map((player, index) => ({ ...player, rank: index + 1 }));
  return rankedPlayers;
};

const groupBy = (array, key) => {
  return array.reduce((acc, obj) => {
    const group = acc[obj[key]] || [];
    group.push(obj);
    acc[obj[key]] = group;
    return acc;
  }, {});
};

const useGameStatus = () => {
  const { currentRound, status } = useContext(GameContext);
  return { currentRound, status };
};

const Game = ({ game }) => {
  const { currentRound, status } = useGameStatus();
  const rankedPlayers = rankPlayers(game.players);
  const groupedPlayers = groupBy(rankedPlayers, 'rank');

  return (
    <div>
      {game.status === 'COMPLETED' && (
        <LeaderBoard players={rankedPlayers} />
      )}
      {game.status === 'COMPLETED' ? (
        groupedPlayers[1]?.map((player) => (
          <PlayersByRole key={player.id} player={player} />
        ))
      ) : (
        groupedPlayers[1]?.map((player) => (
          <PlayersByRole key={player.id} player={player} />
        )) &&
        game.players.map((player) => (
          <PlayersByRole key={player.id} player={player} />
        ))
      )}
      {currentRound >= game.totalRounds && (
        <button onClick={() => game.startNextRound()}>Start Next Round</button>
      )}
    </div>
  );
};

