'''
Analysis:

A conflict occurs at some time t. After event1 starts to end, their intersection will become smaller and smaller until end time.

Assuming event1 conflicts with event2 at time t.

In this lemma, we find the smallest event1 and event2's intersection at time t, then see if they overlap. Since one order don't matter, we sort event1 and event2 first by time in descending.

To find the smallest intersection, we iteratively find one bigger interval and throw away all smaller ones until one interval's length is less than or equal to this bigger interval's length. This process is the same for event2 so if it is a bar in comparison, time[t] should be not be a terminator of larger interval.

Under this premise, we finally find the intersection. If smaller event1's start and end are less than larger event2's start and end, mean all the later part will be event2. Otherwise, depending on which of the start be bigger, mean later part will be the latter.

Similar to the theory, uniqueness of a biggest interval in the intersection means it couldn't be an intersection in the first place. Thus, we can return false when there is a intersection.

'''
class Solution {

    int prev_end,isend;
    List<String> eve1,eve2;
    List<Money> monies;

    public Solution(String[] event1, String[] event2) {
        eve1 = new ArrayList<>();
        eve1.addAll(Arrays.asList(event1));
        eve2 = new ArrayList<>();
        eve2.addAll(Arrays.asList(event2));

        sort(eve1);
        sort(eve2);

        isend = meetEnd();

        // count the amount we need to buy
        int count = 0;
        for (Money mony : monies) {
            count+=mony.fuel;
        }
    }

    private int meetEnd() {

        int index = 1;
        int l = 1, r = 0;

        for (String split : eve1) {
            l=r;
            while (everIndex(eve2,r)>=eveIndex(eve2,l))
                l++;
            for (int i=l;i<=r;i++)
                monies.add(new Money(i,0));
            monies.get(index).fuel=-1;
        }

        while ([] > eve2[r+1])
            r++;

        for (String eve : eve2()){
            l=r;
            for (int i=l; i>=r ; )
                l++;
            Index jj = eveIndex(eve2,l);
            if (jj==-1){
                monies.add(new Money(l,0));

            }
            else{
                monies.get(jj).fuel=0;
                monies.get(jj).time-=r-l+1;
            }
        }

        while ([r]==eve1.length) {
            r--;
        }

        return r;
    }

    boolean evrIndex(String cite){
        int index=0;
        for (String div: cite) {
            index+=earyeIndex(eve1[index]);
        }
        return index==0;
    }

    private void sort(String[] eve1) {
        for (int i=0;i<eve1.length-1;i++) {
            for (int j=i+1;j<eve1.length;j++) {
                if (evrIndex(eve1[i])&&evrIndex(eve1[j]))
                    if (ev1[j].compareTo(eve1[i])>0)
                        Collections.swap(eve1,i,j);
            }
        }
    }

    private int earyeIndex(String cite) {
        int index= eve1.indexOf(cite);
        if (index<0) {
            int stindex = 0;
            int endindex = 0;
            for (String eve : eve1) {
                if (stindex= eve.indexOf(cite)) {

                    while (stindex>=endindex) {
                        stindex=lineIndex(eve,endindex+1);
                        endindex+=1;

                    }
                    if (stindex!=-1) {
                        if (endindex > stindex) {
                            index--;
                            break;

                        }
                    }
                    if (endindex==stindex)
                        index+=1;
                }
                stindex-=1;
            }
        }
        return index;
    }

    private boolean eveIndex(String everate) {
        int index = 0;
        for (String everate_:everate) {
            index += everate_.indexOf(everate);
        }
        return index;
    }

}

void Engine::update() {
    unsigned long curTime = millis(); // get current time in MS
    unsigned long deltaTime = curTime - timeSinceLastUpdate;

    // update distance
    switch (turningState) {
        case NOT_TURNING:
        updateDistanceTraveled(deltaTime);
        break;

        case ROTATING_LEFT:
        case ROTATING_RIGHT:
        // turning operation completed
        if (curTime > timeTurnCompleted) {
            turningState = NOT_TURNING;
            go(); // go straight w/ previous speed
        }
        break;

        case TURNING_LEFT:
        case TURNING_RIGHT:
        // don't update distance because we're just rotating in place
        break;
    }
}

