import sqlite3
from datetime import datetime
from elasticsearch import Elasticsearch, NotFoundError
import logging

def fetch(es_host, es_index, sqlite_db):
    es = Elasticsearch([es_host])
    conn = sqlite3.connect(sqlite_db)
    cursor = conn.cursor()

    # Create table if it doesn't exist
    cursor.execute('''CREATE TABLE IF NOT EXISTS complaints (
                        id INTEGER PRIMARY KEY,
                        complaint_date TEXT,
                        details TEXT)''')
    conn.commit()

    # Fetch the last fetched date
    cursor.execute('SELECT MAX(complaint_date) FROM complaints')
    last_fetched_date = cursor.fetchone()[0]

    if last_fetched_date is None:
        last_fetched_date = '1970-01-01T00:00:00'  # Start from the oldest record

    last_fetched_date = datetime.fromisoformat(last_fetched_date)

    while True:
        query = {
            "query": {
                "range": {
                    "complaint_date": {
                        "gt": last_fetched_date.isoformat()
                    }
                }
            },
            "size": 1000
        }

        try:
            response = es.search(index=es_index, body=query)
        except NotFoundError:
            logging.error("Index not found.")
            break

        hits = response['hits']['hits']
        if not hits:
            break

        complaints = []
        for hit in hits:
            complaint_date = hit['_source']['complaint_date']
            details = hit['_source']['details']
            complaints.append((hit['_id'], complaint_date, details))

        try:
            cursor.executemany('INSERT OR IGNORE INTO complaints (id, complaint_date, details) VALUES (?, ?, ?)', complaints)
            conn.commit()
        except sqlite3.IntegrityError as e:
            logging.error(f"Integrity error occurred: {e}")

        last_fetched_date = max(datetime.fromisoformat(hit['_source']['complaint_date']) for hit in hits)
        logging.info(f"Fetched {len(hits)} complaints. Last fetched date updated to {last_fetched_date.isoformat()}.")

    conn.close()

[Serializable]
    public class ExecutionError : Exception
    {
        public ExecutionError(string message)
            : base(message)
        {
        }
        public ExecutionError(string message, IDictionary data)
            : base(message)
        {
            SetData(data);
        }
         Sets the
        public ExecutionError(string message, Exception exception)
            : base(message, exception)
        {
            SetCode(exception);
            SetData(exception);
        }
        public List<ErrorLocation> Locations { get; private set; }
        public string Code { get; set; }
        public IEnumerable<object> Path { get; set; }
        public void AddLocation(int line, int column)
        {
            (Locations ??= new List<ErrorLocation>()).Add(new ErrorLocation(line, column));
        }
        private void SetCode(Exception exception)
        {
            if (exception != null)
                Code = ErrorInfoProvider.GetErrorCode(exception);
        }
        private void SetData(Exception exception)
        {
            if (exception?.Data != null)
                SetData(exception.Data);
        }
        private void SetData(IDictionary dict)
        {
            if (dict != null)
            {
                foreach (DictionaryEntry keyValuePair in dict)
                {
                    Data[keyValuePair.Key] = keyValuePair.Value;
                }
            }
        }
    }

import "time"

// CheckDates checks that the date range is entirely within the constrained
// range. Both ends are inclusive.
func CheckDates(start, end, constraintStart, constraintEnd time.Time) bool {
	return start.After(constraintStart) || start.Equal(constraintStart) &&
		end.Before(constraintEnd) || end.Equal(constraintEnd)
}

private String getBaseMessage() {
		String desc = this.getDescription();
		int index = this.getIndex();
		String pattern = this.getPattern();

		StringBuffer sb = new StringBuffer();
		sb.append(desc);
		if (index >= 0) {
			sb.append(" near index ");
			sb.append(index);
		}
		sb.append(this.nl);
		sb.append(pattern);
		if (index >= 0) {
			sb.append(this.nl);
			for (int i = 0; i < index; i++) {
				// Output character based on respective character in pattern
				// (allows line wrapping to occur similarly in pattern and caret position,
				// in the case that line wrapping occurs on error message -
				// like if put in text box like in RegExPlus Tasker plug-in)

				char c = pattern.charAt(i);

				if (Character.isWhitespace(c)) {
					sb.append(c);
				} else {
					// Non-break space
					sb.append((char) 160);
				}

			}
			sb.append('^');
		}
		return sb.toString();
	}

