import android.Manifest;
import android.content.pm.PackageManager;
import android.os.Bundle;
import android.widget.Toast;
import androidx.annotation.NonNull;
import androidx.annotation.StringRes;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;

public class MainActivity extends PermissionCheckerActivity {

    private static final int PERMISSION_REQUEST_CODE = 123;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
        requestPermission();
    }

    private void requestPermission() {
        String[] permissions = {
                Manifest.permission.CAMERA,
                Manifest.permission.SYSTEM_ALERT_WINDOW,
                Manifest.permission.WRITE_SETTINGS,
                Manifest.permission.READ_PHONE_STATE
        };

        for (String permission : permissions) {
            if (ContextCompat.checkSelfPermission(this, permission) != PackageManager.PERMISSION_GRANTED) {
                ActivityCompat.requestPermissions(this, permissions, PERMISSION_REQUEST_CODE);
                return;
            }
        }

        // All permissions already granted
        showToast(R.string.permissions_granted);
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);

        if (requestCode == PERMISSION_REQUEST_CODE) {
            boolean allPermissionsGranted = true;
            for (int grantResult : grantResults) {
                if (grantResult != PackageManager.PERMISSION_GRANTED) {
                    allPermissionsGranted = false;
                    break;
                }
            }

            if (allPermissionsGranted) {
                showToast(R.string.permissions_granted);
            } else {
                showToast(R.string.permissions_denied);
            }
        }
    }

    private void showToast(@StringRes int messageResId) {
        Toast.makeText(this, messageResId, Toast.LENGTH_SHORT).show();
    }
}

func readOutput(output string) (map[int]float64, error) {
	hourToValue := make(map[int]float64)
	contents, err := ioutil.ReadFile(output)
	if err != nil {
		return nil, fmt.Errorf("could not read output file %s", output)
	}
	lines := strings.Split(string(contents), "\n")
	for _, line := range lines {
		if line == "" {
			continue
		}
		elements := strings.Split(line, " ")
		if len(elements) != 2 {
			return nil, fmt.Errorf("got %d number of elements in line %q, expected 2", len(elements), line)
		}
		hour, err := strconv.Atoi(elements[0])
		if err != nil {
			return nil, fmt.Errorf("could not convert hour %s to int: %v", elements[0], err)
		}
		value, err := strconv.ParseFloat(elements[1], 64)
		if err != nil {
			return nil, fmt.Errorf("could not convert value %s to float64: %v", elements[1], err)
		}
		hourToValue[hour] = value
	}
	return hourToValue, nil
}

using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Threading.Tasks;
using OpenCvSharp;

public class ImageProcessor
{
    public string CleanUpImage(string rawDataUrl, out string intermediateUrl)
    {
        // Load image from URL
        var imageBytes = Convert.FromBase64String(rawDataUrl);
        using var ms = new MemoryStream(imageBytes);
        var mat = Cv2.ImreadMat(ms);

        // Apply contrast stretch
        mat = ContrastStretch(mat);

        // Detect faces
        var faceCascade = new CascadeClassifier("haarcascade_frontalface_default.xml");
        var faces = faceCascade.DetectMultiScale(mat);

        // Create a copy of the original image for marking faces
        var markedMat = mat.Clone();

        // Mark faces in parallel
        Parallel.ForEach(faces, faceRect =>
        {
            Cv2.Rectangle(markedMat, new Point(faceRect.X, faceRect.Y), new Point(faceRect.X + faceRect.Width, faceRect.Y + faceRect.Height), new Scalar(0, 255, 0), 2);
        });

        // Save marked image to memory stream and convert to base64
        using var markedMs = new MemoryStream();
        Cv2.Imwrite(markedMs, markedMat, new ImageWriteParams { CompressionQuality = 100 });
        intermediateUrl = Convert.ToBase64String(markedMs.ToArray());

        // Convert original image to JPEG and return as base64
        using var outputMs = new MemoryStream();
        Cv2.Imwrite(outputMs, mat, new ImageWriteParams { CompressionQuality = 100 });
        return Convert.ToBase64String(outputMs.ToArray());
    }

    private Mat ContrastStretch(Mat image)
    {
        // Apply contrast stretch
        var lab = image.CvtColor(ColorConversion.BgrToLab);
        var lChannel = new Mat();
        var aChannel = new Mat();
        var bChannel = new Mat();
        lab.Split(out lChannel, out aChannel, out bChannel);

        var clahe = Cv2.CreateCLAHE(clipLimit: 2.0, tileGridSize: new Size(8, 8));
        lChannel = clahe.Apply(lChannel);

        var contrastStretched = new Mat();
        Cv2.Merge(new[] { lChannel, aChannel, bChannel }, contrastStretched);
        return contrastStretched.CvtColor(ColorConversion.LabToBgr);
    }
}

public class RedactProcessor : IAnonymizerProcessor
    {
        private readonly RedactFunction _redactFunction;
        private readonly ILogger _logger = AnonymizerLogging.CreateLogger<RedactProcessor>();
        public RedactProcessor(JObject settingObject)
        {
            EnsureArg.IsNotNull(settingObject, nameof(settingObject));
            var settingFactory = new AnonymizerSettingsFactory();
            var redactSetting = settingFactory.CreateAnonymizerSetting<RedactSetting>(settingObject);
            _redactFunction = new RedactFunction(redactSetting);
        }
        public void Process(DicomDataset dicomDataset, DicomItem item, ProcessContext context = null)
        {
            EnsureArg.IsNotNull(dicomDataset, nameof(dicomDataset));
            EnsureArg.IsNotNull(item, nameof(item));
            var redactedValues = new List<string>();
            if (item.ValueRepresentation == DicomVR.AS)
            {
                var values = ((DicomAgeString)item).Get<string[]>();
                foreach (var value in values)
                {
                    var result = _redactFunction.Redact(DicomUtility.ParseAge(value));
                    if (result != null)
                    {
                        redactedValues.Add(DicomUtility.GenerateAgeString(result));
                    }
                }
            }
            else if (item.ValueRepresentation == DicomVR.DA)
            {
                var values = DicomUtility.ParseDicomDate((DicomDate)item);
                foreach (var value in values)
                {
                    var result = _redactFunction.Redact(value);
                    if (result != null)
                    {
                        redactedValues.Add(DicomUtility.GenerateDicomDateString((DateTimeOffset)result));
                    }
                }
            }
            else if (item.ValueRepresentation == DicomVR.DT)
            {
                DateTimeObject[] values = DicomUtility.ParseDicomDateTime((DicomDateTime)item);
                foreach (var value in values)
                {
                    DateTimeObject result = _redactFunction.Redact(value);
                    if (result != null)
                    {
                        redactedValues.Add(DicomUtility.GenerateDicomDateTimeString(result));
                    }
                }
            }
            else if (item.ValueRepresentation == DicomVR.SQ)
            {
                dicomDataset.AddOrUpdate<DicomDataset>(DicomVR.SQ, item.Tag);
                return;
            }
            if (redactedValues.Count != 0)
            {
                dicomDataset.AddOrUpdate(item.ValueRepresentation, item.Tag, redactedValues.ToArray());
            }
            else
            {
                dicomDataset.AddOrUpdate<string>(item.ValueRepresentation, item.Tag, values: null);
            }
            _logger.LogDebug($"The value of DICOM item '{item}' is redacted.");
        }
        public bool IsSupported(DicomItem item)
        {
            return true;
        }
    }

bool TypedWritable::
encode_to_bam_stream(vector_uchar &data, BamWriter *writer) const {
  data.clear();
  DatagramBuffer buffer;
  if (writer == nullptr) {
    if (!buffer.write_header(_bam_header)) {
      return false;
    }
    BamWriter writer(&buffer);
    if (!writer.init()) {
      return false;
    }
    if (!writer.write_object(this)) {
      return false;
    }
  } else {
    writer->set_target(&buffer);
    bool result = writer->write_object(this);
    writer->set_target(nullptr);
    if (!result) {
      return false;
    }
  }
  buffer.swap_data(data);
  return true;
}

def cropped_image(img: np.ndarray, percent_white_thr: float = CROP_THRESHOLD) -> np.ndarray:
	min_x: int = 0
	max_x: int = img.shape[1]  
	min_y: int = 0
	max_y: int = img.shape[0]
	while min_x < img.shape[1] and (img[:, min_x].sum() / img.shape[0]) >= (255 * percent_white_thr):
		min_x += 1
	while max_x > 0 and (img[:, max_x - 1].sum() / img.shape[0]) >= (255 * percent_white_thr):
		max_x -= 1
	while min_y < img.shape[0] and (img[min_y, :].sum() / img.shape[1]) >= (255 * percent_white_thr):
		min_y += 1
	while max_y > 0 and (img[max_y - 1, :].sum() / img.shape[1]) >= (255 * percent_white_thr):
		max_y -= 1
	return img[min_y:max_y, min_x:max_x]

