// toPostfix converts an infix expression to postfix notation using Dijkstra's Shunting Yard algorithm.
func toPostfix(expression string) (string, error) {
	var output []string
	var operators []string

	precedence := map[string]int{
		"+": 1, "-": 1, "*": 2, "/": 2,
	}

	parentheses := map[string]bool{
		"(": true, ")": true,
	}

	tokens := strings.FieldsFunc(expression, func(r rune) bool {
		return r == ' '
	})

	for _, token := range tokens {
		if strings.Contains("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", token[0]) {
			output = append(output, token)
		} else if precedence[token] != 0 {
			for len(operators) > 0 && precedence[operators[len(operators)-1]] >= precedence[token] {
				output = append(output, operators[len(operators)-1])
				operators = operators[:len(operators)-1]
			}
			operators = append(operators, token)
		} else if token == "(" {
			operators = append(operators, token)
		} else if token == ")" {
			for len(operators) > 0 && operators[len(operators)-1] != "(" {
				output = append(output, operators[len(operators)-1])
				operators = operators[:len(operators)-1]
			}
			operators = operators[:len(operators)-1] // remove the "("
		}
	}

	for len(operators) > 0 {
		output = append(output, operators[len(operators)-1])
		operators = operators[:len(operators)-1]
	}

	return strings.Join(output, " "), nil
}

func main() {
	expression := "3 + 4 * 2 / ( 1 - 5 )"
	postfix, err := toPostfix(expression)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println("Postfix:", postfix)
}

