def update(self):
        if len(self.neighbors) < 1:
            warn("Can not update GameOfLifeCell with 0 neighbors")
            return
        num_live_neighbors = 0
        num_dead_neighbors = 0
        for n in self.neighbors:
            if n.type == self.ALIVE: num_live_neighbors += 1
            elif n.type == self.DEAD: num_dead_neighbors += 1
        if self.type == self.ALIVE and num_live_neighbors < 2:
            self.type = self.DEAD
            self.population.update_type_count(self.ALIVE, self.DEAD)            
        elif self.type == self.ALIVE and num_live_neighbors > 3:
            self.type = self.DEAD
            self.population.update_type_count(self.ALIVE, self.DEAD)            
        elif self.type == self.DEAD and num_live_neighbors == 3:
            self.type = self.ALIVE
            self.population.update_type_count(self.DEAD, self.ALIVE)

public Iterator<Integer> iterator(boolean useTranscriptDirection)
			{
			final IntIter iter=new IntIter();
			if(useTranscriptDirection && this.isNegativeStrand())
				{
				iter.beg=this.getEnd()-1;
				iter.end=this.getStart()-1;
				iter.shift=-1;
				}
			else
				{
				iter.beg=this.getStart();
				iter.end=this.getEnd();
				iter.shift=1;
				}
			return iter;
			}

// Define
const size = 128
const generations = 1024
const grid = []

// Generate
for (let y = 0; y < size; y++) {
  grid.push([])
  for (let x = 0; x < size; x++) {
    grid[y].push(Math.round(Math.random()))
  }
}

// Iterate
for (let g = 0; g < generations; g++) {
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const n = ((x + 1 < size) ? grid[y][x + 1] : 0)
        + ((y + 1 < size) ? grid[y + 1][x] : 0)
        + (y ? grid[y - 1][x] : 0)
        + (x ? grid[y][x - 1] : 0)
        + ((y + 1 < size && x + 1 < size) ? grid[y + 1][x + 1] : 0)
        + ((y && x + 1 < size) ? grid[y - 1][x + 1] : 0)
        + ((y && x) ? grid[y - 1][x - 1] : 0)
        + ((x && y + 1 < size) ? grid[y + 1][x - 1] : 0)
      grid[y][x] = (((n & 2) >> 1) && (grid[y][x] || (n == 3))) | 0
    }
  }
}

// Display
const pattern = " █"
for (let y = 0; y < size; y++) {
  let line = '';
  for (let x = 0; x < size; x++) {
    line += pattern[grid[y][x]]
  }
  console.log(line)
}

func (f *Facade) HandleTodayTopLinksViewsExtraction() (*[]entity.LinkView, error) {
	todayDate := time.Now().Format("2006-01-02")
	dateSplit := strings.Split(todayDate, "-")
	year := dateSplit[0]
	month := dateSplit[1]
	day := dateSplit[2]
	topLinkViews, err := f.redisCache.GetCachedTopViews(todayDate)
	if err != cache.ErrCacheMiss && topLinkViews != nil {
		return topLinkViews, nil
	}
	topLinkViews, err = f.query.QueryTodayTopLinksViews(year, month, day)
	if err != nil {
		return nil, err
	}
	if len(*topLinkViews) > 0 {
		go f.redisCache.CacheTopViews(todayDate, *topLinkViews) 
	}
	return topLinkViews, err
}

