func TestGetEnforcementActions(t *testing.T) {
    // Arrange
    // Create a mock connector for testing
    connectorMock := &ConnectorMock{
        // Define the output for "fraud-detection" purpose
        OutputForPurpose: map[string][]byte{
            "fraud-detection": []byte(`{"action": "block"}`),
            "marketing":       []byte(`{"action": "allow"}`),
        },
    }

    // Create a policy compiler with the mock connector
    policyCompiler := NewPolicyCompiler(connectorMock)

    // Test for "fraud-detection" purpose
    actions, err := policyCompiler.GetEnforcementActions("fraud-detection")
    if err != nil {
        t.Errorf("expected no error, got %v", err)
    }
    if len(actions) != 1 || actions[0] != "block" {
        t.Errorf("expected action 'block' for purpose 'fraud-detection', got %v", actions)
    }

    // Test for "marketing" purpose
    actions, err = policyCompiler.GetEnforcementActions("marketing")
    if err != nil {
        t.Errorf("expected no error, got %v", err)
    }
    if len(actions) != 1 || actions[0] != "allow" {
        t.Errorf("expected action 'allow' for purpose 'marketing', got %v", actions)
    }
}

