private void buildFormattedNameFeature(StringBuilder sb, FormattedNameFeature formattedNameFeature) throws VCardBuildException {
		try {
			if(formattedNameFeature != null) {
				String formattedName = formattedNameFeature.getFormattedName();
				StringBuilder tmpSb = new StringBuilder();
				if(formattedNameFeature.hasGroup()) {
					tmpSb.append(formattedNameFeature.getGroup());
					tmpSb.append(".");
				}
				tmpSb.append(formattedNameFeature.getTypeString());
				tmpSb.append(":");
				tmpSb.append(VCardUtils.escapeString(formattedName));
				String tmpFormattedNameLine = tmpSb.toString();
				String foldedFormattedNameLine = VCardUtils.foldLine(tmpFormattedNameLine, foldingScheme);
				sb.append(foldedFormattedNameLine);
				sb.append(VCardUtils.CRLF);
			}
			else {
				throw new VCardBuildException("FormattedNameFeature ("+VCardType.FN.getType()+") cannot be left null.");
			}
		}
		catch(Exception ex) {
			throw new VCardBuildException("FormattedNameFeature ("+VCardType.FN.getType()+") ["+ex.getClass().getName()+"] "+ex.getMessage(), ex);
		}
	}

func (r *renamer) checkInLexicalScope(from types.Object, info *loader.PackageInfo) {
	b := from.Parent() 
	if b != nil {
		toBlock, to := b.LookupParent(r.to, from.Parent().End())
		if toBlock == b {
			r.errorf(from.Pos(), "renaming this %s %q to %q",
				objectKind(from), from.Name(), r.to)
			r.errorf(to.Pos(), "\tconflicts with %s in same block",
				objectKind(to))
			return
		} else if toBlock != nil {
			forEachLexicalRef(info, to, func(id *ast.Ident, block *types.Scope) bool {
				_, obj := lexicalLookup(block, from.Name(), id.Pos())
				if obj == from {
					r.errorf(from.Pos(), "renaming this %s %q to %q",
						objectKind(from), from.Name(), r.to)
					r.errorf(id.Pos(), "\twould shadow this reference")
					r.errorf(to.Pos(), "\tto the %s declared here",
						objectKind(to))
					return false 
				}
				return true
			})
		}
	}
	forEachLexicalRef(info, from, func(id *ast.Ident, block *types.Scope) bool {
		fromBlock, _ := lexicalLookup(block, from.Name(), id.Pos())
		toBlock, to := lexicalLookup(block, r.to, id.Pos())
		if to != nil {
			if deeper(toBlock, fromBlock) {
				r.errorf(from.Pos(), "renaming this %s %q to %q",
					objectKind(from), from.Name(), r.to)
				r.errorf(id.Pos(), "\twould cause this reference to become shadowed")
				r.errorf(to.Pos(), "\tby this intervening %s definition",
					objectKind(to))
				return false 
			}
		}
		return true
	})
	if _, ok := from.(*types.TypeName); ok {
		for id, obj := range info.Uses {
			if obj == from {
				if field := info.Defs[id]; field != nil {
					r.check(field)
				}
			}
		}
	}
}

RsslInt32 rwsIntTotalUsedOutputBuffers(RsslSocketChannel *rsslSocketChannel, RsslError *error)
{
	RsslInt32 		num = 0, largeMsgBufCnt = 0;
	rtr_msgb_t		*bufPtr = 0;
	if (rsslSocketChannel->workState & RIPC_INT_SHTDOWN_PEND)
	{
		_rsslSetError(error, NULL, RSSL_RET_FAILURE, errno);
		snprintf(error->text, MAX_RIPC_ERROR_TEXT,"<%s:%d> rwsIntTotalUsedOutputBuffers() failed due to session shutdown.", __FILE__,__LINE__);
		return(-1);
	}
	bufPtr = rsslSocketChannel->rwsLargeMsgBufferList;
	while (bufPtr != 0)
	{
		largeMsgBufCnt++;
		bufPtr = (rtr_msgb_t*)bufPtr->internal;
	}
	num = rsslSocketChannel->guarBufPool->numRegBufsUsed + rsslSocketChannel->guarBufPool->numPoolBufs + largeMsgBufCnt;
	return(num);
}

def run(self, input_files, input_metadata, output_files):  
        bamin = input_files[0]
        if not os.path.isfile(bamin.replace('.bam', '.bam.bai')):
            logger.info('Creating bam index')
            _cmd = ['samtools', 'index', bamin]
            out, err = Popen(_cmd, stdout=PIPE, stderr=PIPE).communicate()
            logger.info(out)
            logger.info(err)
        biases = None
        if len(input_files) > 1:
            biases = input_files[1]
        resolution = 100000
        if 'resolution' in input_metadata:
            resolution = int(input_metadata['resolution'])
        coord1 = coord2 = norm = None
        ncpus = 1
        if 'ncpus' in input_metadata:
            ncpus = input_metadata['ncpus']
        if 'coord1' in input_metadata:
            coord1 = input_metadata['coord1']
        if 'coord2' in input_metadata:
            coord2 = input_metadata['coord2']
        if 'norm' in input_metadata:
            norm = input_metadata['norm']
        root_name = os.path.dirname(os.path.abspath(bamin))
        if 'workdir' in input_metadata:
            root_name = input_metadata['workdir']
        project_metadata = {}
        project_metadata["species"] = input_metadata["species"]
        project_metadata["assembly"] = input_metadata["assembly"]
        output_files, output_metadata = self.tb_bin(bamin, biases, resolution,
                                                    coord1, coord2, norm, root_name,
                                                    ncpus, project_metadata)
        return (output_files, output_metadata)

def evaluate_many(self, preds, save_file_name = None, results_individual = None):
		min_requirement = 5
		if len(preds) < min_requirement:
			return ValueError("Must have predictions from at least " + str(min_requirement) + " runs for leaderboard submission")
		if results_individual is None:
			individual_results = []
			for pred in preds:
				retval = self.evaluate(pred)
				individual_results.append(retval)
		else:
			individual_results = results_individual
		given_dataset_names = list(individual_results[0].keys())
		aggregated_results = {}
		for dataset_name in given_dataset_names:
			my_results = []
			for individual_result in individual_results:
				my_result = list(individual_result[dataset_name].values())[0]
				my_results.append(my_result)
			u = np.mean(my_results)
			std = np.std(my_results)
			aggregated_results[dataset_name] = [round(u, 3), round(std, 3)]
		return aggregated_results

@Override
  public Collection<HivePartitionVersion> findDatasetVersions(Dataset dataset)
      throws IOException {
    List<HivePartitionVersion> versions = new ArrayList<>();
    if (!(dataset instanceof HivePartitionDataset)) {
      return versions;
    }
    HivePartitionDataset hivePartitionDataset = (HivePartitionDataset) dataset;
    this.owner = hivePartitionDataset.getOwner();
    Preconditions.checkArgument(!this.patterns.isEmpty(),
        "No patterns to find versions for the dataset " + dataset.datasetURN());
    versions
        .addAll(findVersions(hivePartitionDataset.getName(), hivePartitionDataset.datasetURN()));
    return versions;
  }

private async ValueTask<bool> ReadPipeLoop0(ReadPipeState state)
        {
            HConsole.WriteLine(this, 2, "Pipe reader awaits data from the pipe");
            var result = await state.Reader.ReadAsync().CfAwait();
            state.Buffer = result.Buffer;
            if (state.Buffer.Length == 0)
            {
                HConsole.WriteLine(this, 2, "Pipe reader received no data");
                return false;
            }
            HConsole.WriteLine(this, 2, $"Pipe reader received data, buffer size is {state.Buffer.Length} bytes");
            while (await ReadPipeLoop1(state).CfAwait()) { }
            state.Reader.AdvanceTo(state.Buffer.Start, state.Buffer.End);
            if (state.Failed)
                return false;
            if (result.IsCompleted)
            {
                HConsole.WriteLine(this, "Pipe is completed (in reader)");
                return false;
            }
            return true;
        }

[System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Design", "CA1062:ValidateArgumentsOfPublicMethods",
            Justification = "Will throw if battlescape or combatant is null")]
        public override ActionError IsLocationOk(Battle battlescape, Item item, Combatant combatant, Vector3 target)
        {
            if ((range * range) < Vector3.DistanceSquared(combatant.Position, target))
            {
                return ActionError.OutOfRange;
            }
            Vector3 dummy = new Vector3();
            if (!battlescape.Terrain.IsLineOfSight(combatant.Position, target, VisibilityChecks.LineOfFire, ref dummy))
            {
                return ActionError.NoLineOfSight;
            }
            Vector3 diff = target - combatant.Position;
            diff.Y = 0;
            diff.Normalize();
            if (Vector3.Dot(diff, combatant.HeadingVector) < Combatant.DotFieldOfView)
            {
                return ActionError.WrongDirection;
            }
            return ActionError.None;
        }

const httpStatus = require('http-status');

const {
  HeroNFT
} = require('../models')

const {
  COMMON_HERO,
  RARE_HERO,
  EPIC_HERO,
  LEGENDARY_HERO
} = require('../models/hero.model');

const listHeroes = async (req, res) => {
  const {
    type
  } = req.body;
  const convertObjectToArray=(obj)=>{
    let data=[]
    for (const key in obj) {
      data.push(obj[key])
    }
    return data
  }
  let heroes;
  if(type){
    switch (type.toLowerCase()) {
      case 'common':
        heroes = convertObjectToArray(COMMON_HERO);
        break;
      case 'rare':
        heroes = convertObjectToArray(RARE_HERO);
        break;
      case 'epic':
        heroes = convertObjectToArray(EPIC_HERO);
        break;
      case 'legend':
        heroes = convertObjectToArray(LEGENDARY_HERO);
        break;
    }
  }
  else{
    heroes=[
      ...convertObjectToArray(COMMON_HERO),
      ...convertObjectToArray(RARE_HERO),
      ...convertObjectToArray(EPIC_HERO),
      ...convertObjectToArray(LEGENDARY_HERO),
    ]
  }

  res.status(200).json({
    status: true,
    code: httpStatus[200],
    message: '',
    data: heroes
  })
}

const listHeroesUser = async (req, res) => {
  const address = req.wallet.Address;
