STDMETHODIMP
CPhone::get_Tone(
            OUT   PHONE_TONE * pTone
            )
{
    LOG((TL_TRACE, "get_Tone - "
                                "enter"));

    if ( TAPIIsBadWritePtr( pTone, sizeof( PHONE_TONE ) ) )
    {
        LOG((TL_ERROR, "get_Tone - "
                                 "bad parameter - exit E_POINTER"));

        return E_POINTER;
    }

    Lock();

    //
    // Make sure the phone is open
    //

    if ( m_hPhone == NULL )
    {
        LOG((TL_ERROR, "get_Tone - phone is not open - "
                                 "exit TAPI_E_PHONENOTOPEN"));

        Unlock();

        return TAPI_E_PHONENOTOPEN;
    }

    *pTone = m_Tone;

    Unlock();

    LOG((TL_TRACE, "get_Tone - "
                                "exit S_OK"));

    return S_OK;
}

Status parse(uint32_t buflen)
		{
			_prevbuflen = _buflen;
			_buflen = buflen;
			_num_headers = sizeofarr(_headers);
			int rc = phr_parse_request(_buf, _buflen, 
				&_method, &_method_len, &_path, &_path_len,
				&_minor_version, _headers, &_num_headers, _prevbuflen);
			if (rc > 0)
			{
				_data = (uint8_t*)_buf + rc;
				_data_len = _buflen - rc;
				return Success;
			}
			if (rc == -1)
				return Error;
			return Incomplete;
		}

def task_trim_func_images() -> Dict:
    for subject in SUBJECTS:
        sources = [
            fname.afniproc_onsets(subject=subject),
            fname.resampled_func(subject=subject),
        ]
        targets = [
            fname.trimmed_func(subject=subject),
        ]
        kwargs = dict(
            onsets_path=fname.afniproc_onsets(subject=subject),
            func_path=fname.resampled_func(subject=subject),
            out_prefix=get_prefix(fname.trimmed_func(subject=subject)),
        )
        yield dict(
            name=f"subject--{subject}",
            actions=[(trim_func_images.main, [], kwargs)],
            file_dep=sources,
            targets=targets,
        )

public static void main(String[] args) throws IOException
    {
        if (args.length != 1)
        {
            usage();
        }
        try (PDDocument document = Loader.loadPDF(new File(args[0])))
        {
            AccessPermission ap = document.getCurrentAccessPermission();
            if (!ap.canExtractContent())
            {
                throw new IOException("You do not have permission to extract text");
            }
            PDFTextStripper stripper = new PDFTextStripper();
            stripper.setSortByPosition(true);
            for (int p = 1; p <= document.getNumberOfPages(); ++p)
            {
                stripper.setStartPage(p);
                stripper.setEndPage(p);
                String text = stripper.getText(document);
                String pageStr = String.format("page %d:", p);
                System.out.println(pageStr);
                for (int i = 0; i < pageStr.length(); ++i)
                {
                    System.out.print("-");
                }
                System.out.println();
                System.out.println(text.trim());
                System.out.println();
            }
        }
    }

