TEST_CASE("tst_pregel1", "[pregel][mmap]") {
  MappedFileBuffer mapped(1024);
  int *ptr = mapped.data();
  for (int i = 0; i < 1024; i++) {
    *(ptr+i) = i;
  }
  for (int i = 0; i < 1024; i++) {
    REQUIRE(*(ptr+i) == i);
  }

#ifdef __linux__
  mapped.resize(2048);
  REQUIRE(mapped.size() == 2048);
  ptr = mapped.data();
  for (int i = 0; i < 1024; i++) {
    REQUIRE(*(ptr+i) == i);
  }
#endif

  mapped.resize(512);
  ptr = mapped.data();
  REQUIRE(mapped.size() == 512);
  for (int i = 0; i < 512; i++) {
    REQUIRE(*(ptr+i) == i);
  }

  mapped.close();
  REQUIRE(mapped.data() == nullptr);
}

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class RationalTest {

    @Test
    public void testAddition() {
        Rational r1 = new Rational(1, 2);
        Rational r2 = new Rational(1, 3);
        Rational expected = new Rational(5, 6);
        assertEquals(expected, r1.add(r2));
    }

    @Test
    public void testSubtraction() {
        Rational r1 = new Rational(1, 2);
        Rational r2 = new Rational(1, 3);
        Rational expected = new Rational(1, 6);
        assertEquals(expected, r1.subtract(r2));
    }

    @Test
    public void testMultiplication() {
        Rational r1 = new Rational(1, 2);
        Rational r2 = new Rational(3, 4);
        Rational expected = new Rational(3, 8);
        assertEquals(expected, r1.multiply(r2));
    }

    @Test
    public void testDivision() {
        Rational r1 = new Rational(1, 2);
        Rational r2 = new Rational(3, 4);
        Rational expected = new Rational(2, 3);
        assertEquals(expected, r1.divide(r2));
    }

    @Test
    public void testSimplification() {
        Rational r1 = new Rational(4, 6);
        Rational expected = new Rational(2, 3);
        assertEquals(expected, r1);
    }
}

