def lis():
    return [int(i) for i in input().split()]

def solve(n, r):
    p = []
    i = 2
    while i*i <= n:
        if n%i == 0:
            p.append(i)
            while n%i == 0:
                n //= i
        i += 1

    if n > 1:
        p.append(n)

    s = 0

    for mask in range(1, 1<<len(p)):
        mult = 1
        bits = 0
        for i in range(len(p)):
            if mask & (1<<i):
                bits += 1
                mult *= p[i]


        curr = r//mult
        if bits%2 == 1:
            s += curr
        else:
            s -= curr

    return r-s


