@Entity
@Table(name = "integration_entity")
@Inheritance(strategy = InheritanceType.JOINED)
public abstract class APIIntegrationEntity {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	@Column(name = "integration_id")
	private long integrationId;

	@Column(name = "api_label")
	private String apiLabel;

	@Column(name = "api_endpoint")
	private String apiEndpoint;

	public long getIntegrationId() {
		return integrationId;
	}

	public void setIntegrationId(long integrationId) {
		this.integrationId = integrationId;
	}

	public String getApiLabel() {
		return apiLabel;
	}

	public void setApiLabel(String apiLabel) {
		this.apiLabel = apiLabel;
	}

	public String getApiEndpoint() {
		return apiEndpoint;
	}

	public void setApiEndpoint(String apiEndpoint) {
		this.apiEndpoint = apiEndpoint.toLowerCase();
	}

	public String getEndpointLink() {
		return String.format("/rest/scan/%s", getApiEndpoint());
	}

	/**
	 * Get the {@linkplain ApiType} for this Integration Entity
	 * 
	 * @return the {@linkplain ApiType}
	 */
	public abstract ApiType getApiType();

	/**
	 * Given a set of parameters from an HTTP request, populate the settings for this object
	 * 
	 * @param parameters the map of parameters to use to populate this object
	 * @throws ApiIntegrationException if the parameters are wrong or incomplete
	 */
	public abstract void configureEntityFromParameters(Map<String, String> parameters)
			throws ApiIntegrationException;

	/**
	 * Create an HTTP link to view the Pull Request for the given repository and pullRequestId
	 * 
	 * @param repository    the repository id
	 * @param pullRequestId the PR id
	 * @return an http link for this Pull Request, or null, if none could be made
	 */
	public abstract String makePRLink(String repository, String pullRequestId);
}

static updateArrays( positionArray, normalArray, uvArray, p0x, p0y, p0z, p1x, p1y, p1z, p2x, p2y, p2z, p3x, p3y, p3z, nx, ny, nz, offset = 0, offsetPosition = Vector3.ZERO ) {
    const writer = new TriangleArrayWriter( positionArray, normalArray, uvArray, offset, offsetPosition );
    writer.position( p0x, p0y, p0z );
    writer.position( p1x, p1y, p1z );
    writer.position( p2x, p2y, p2z );
    writer.position( p0x, p0y, p0z );
    writer.position( p2x, p2y, p2z );
    writer.position( p3x, p3y, p3z );
    writer.uv( 0, 0 );
    writer.uv( 1, 0 );
    writer.uv( 1, 1 );
    writer.uv( 0, 0 );
    writer.uv( 1, 1 );
    writer.uv( 0, 1 );
    writer.normal( nx, ny, nx );
    return writer.getOffset();
  }

public static string BuildWxs(Project project, string path, OutputType type)
        {
            if (ClientAssembly.IsEmpty())
                ClientAssembly = System.Reflection.Assembly.GetCallingAssembly().Location;
            XDocument doc = GenerateWixProj(project);
            IndjectCustomUI(project.CustomUI, doc);
            DefaultWixSourceGeneratedHandler(doc);
            AutoElements.InjectAutoElementsHandler(doc);
            AutoElements.NormalizeFilePaths(doc, project.SourceBaseDir, EmitRelativePaths);
            if (type == OutputType.MSM)
            {
                ConvertMsiToMsm(doc);
            }
            doc.AddDefaultNamespaces();
            project.InvokeWixSourceGenerated(doc);
            if (WixSourceGenerated != null)
                WixSourceGenerated(doc);
            doc.AddDefaultNamespaces();
            string xml = "";
            using (IO.StringWriter sw = new StringWriterWithEncoding(project.Encoding))
            {
                doc.Save(sw, SaveOptions.None);
                xml = sw.ToString();
            }
            DefaultWixSourceFormatedHandler(ref xml);
            project.InvokeWixSourceFormated(ref xml);
            if (WixSourceFormated != null)
                WixSourceFormated(ref xml);
            using (var sw = new IO.StreamWriter(path, false, project.Encoding))
                sw.WriteLine(xml);
            Console.WriteLine("\n----------------------------------------------------------\n");
            Console.WriteLine("Wix project file has been built: " + path + "\n");
            project.InvokeWixSourceSaved(path);
            if (WixSourceSaved != null)
                WixSourceSaved(path);
            return path;
        }

import "fmt"

func shortestPath(maze [][]string) int {
    //Initialize variables
    directions := [][]int{{0, 1}, {1, 0}, {0, -1}, {-1, 0}}
    dist := make([][]int, len(maze))
    for i := range dist {
        dist[i] = make([]int, len(maze[0]))
        for j := range dist[i] {
            dist[i][j] = -1
        }
    }

    //Define queue and add start point to it
    queue := [][2]int{{0, 0}}
    dist[0][0] = 0

    //Perform BFS
    for len(queue) > 0 {
        head := queue[0]
        queue = queue[1:]
        for _, dir := range directions {
            i, j := head[0] + dir[0], head[1] + dir[1]
            if i < 0 || j < 0 || i >= len(maze) || j >= len(maze[0]) || maze[i][j] == "X" || dist[i][j] != -1 {
                continue
            }
            dist[i][j] = dist[head[0]][head[1]] + 1
            queue = append(queue, [2]int{i, j})
        }
        if dist[len(maze) - 1][len(maze[0]) - 1] != -1 {
            return dist[len(maze) - 1][len(maze[0]) - 1]
        }
    }

    return -1
}

func main() {
    //Test our function
    maze := [][]string{
        {"S", "X", ".", "X", "X"},
        {"X", ".", "X", ".", "E"},
        {"X", "X", "X", "X", "X"},
        {"X", ".", ".", "X", "X"},
        {"X", "X", "X", "E", "X"},
    }
    fmt.Println(shortestPath(maze))
}

