// Error handling
void glCheckError(const char* file, int line, const char* function) {
    GLenum error = glGetError();
    if (error != GL_NO_ERROR) {
        std::cerr << "OpenGL Error (" << file << ":" << line << ") in " << function << ": ";
        switch (error) {
            case GL_INVALID_ENUM:
                std::cerr << "GL_INVALID_ENUM";
                break;
            case GL_INVALID_VALUE:
                std::cerr << "GL_INVALID_VALUE";
                break;
            case GL_INVALID_OPERATION:
                std::cerr << "GL_INVALID_OPERATION";
                break;
            case GL_INVALID_FRAMEBUFFER_OPERATION:
                std::cerr << "GL_INVALID_FRAMEBUFFER_OPERATION";
                break;
            case GL_OUT_OF_MEMORY:
                std::cerr << "GL_OUT_OF_MEMORY";
                break;
            case GL_STACK_UNDERFLOW:
                std::cerr << "GL_STACK_UNDERFLOW";
                break;
            case GL_STACK_OVERFLOW:
                std::cerr << "GL_STACK_OVERFLOW";
                break;
            default:
                std::cerr << "Unknown error";
                break;
        }
        std::cerr << std::endl;
    }
}

#define CHECK_GL_ERROR() glCheckError(__FILE__, __LINE__, __FUNCTION__)

// Texture Format Traits (Template Metaprogramming)
template <typename T>
struct TextureFormatTraits;

template <>
struct TextureFormatTraits<float> {
    static constexpr GLenum internalFormat = GL_RGBA32F;
    static constexpr GLenum format = GL_RGBA;
    static constexpr GLenum type = GL_FLOAT;
};

template <>
struct TextureFormatTraits<unsigned char> {
    static constexpr GLenum internalFormat = GL_RGBA8;
    static constexpr GLenum format = GL_RGBA;
    static constexpr GLenum type = GL_UNSIGNED_BYTE;
};

template <>
struct TextureFormatTraits<unsigned short> {
    static constexpr GLenum internalFormat = GL_RGBA16;
    static constexpr GLenum format = GL_RGBA;
    static constexpr GLenum type = GL_UNSIGNED_SHORT;
};


// Texture class
class Texture {
public:
    Texture() : id(0), width(0), height(0) {}
    ~Texture() {
        if (id != 0) {
            glDeleteTextures(1, &id);
            CHECK_GL_ERROR();
        }
    }

    bool isValid() const { return id != 0; }
    GLuint getId() const { return id; }
    GLint getWidth() const { return width; }
    GLint getHeight() const { return height; }

    // Create texture
    template <typename T>
    bool create(GLint width, GLint height) {
        if (width <= 0 || height <= 0) {
            std::cerr << "Error: Invalid texture dimensions." << std::endl;
            return false;
        }

        this->width = width;
        this->height = height;

        glGenTextures(1, &id);
        if (id == 0) {
            std::cerr << "Error: Failed to generate texture." << std::endl;
            return false;
        }
        CHECK_GL_ERROR();

        glBindTexture(GL_TEXTURE_2D, id);
        CHECK_GL_ERROR();

        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
        CHECK_GL_ERROR();

        glTexImage2D(GL_TEXTURE_2D, 0, TextureFormatTraits<T>::internalFormat, width, height, 0,
                     TextureFormatTraits<T>::format, TextureFormatTraits<T>::type, nullptr);
        CHECK_GL_ERROR();

        glBindTexture(GL_TEXTURE_2D, 0);
        CHECK_GL_ERROR();

        return true;
    }

    // Upload data
    template <typename T>
    bool uploadData(const std::vector<T>& data) {
        if (!isValid()) {
            std::cerr << "Error: Texture not created." << std::endl;
            return false;
        }

        if (data.size() != static_cast<size_t>(width * height * 4)) { // Assuming RGBA
            std::cerr << "Error: Data size mismatch. Expected " << width * height * 4 << ", got " << data.size() << std::endl;
            return false;
        }

        glBindTexture(GL_TEXTURE_2D, id);
        CHECK_GL_ERROR();

        glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, width, height,
                        TextureFormatTraits<T>::format, TextureFormatTraits<T>::type, data.data());
        CHECK_GL_ERROR();

        glBindTexture(GL_TEXTURE_2D, 0);
        CHECK_GL_ERROR();

        return true;
    }


    // Read back data
    template <typename T>
    bool readData(std::vector<T>& data) const {
        if (!isValid()) {
            std::cerr << "Error: Texture not created." << std::endl;
            return false;
        }

        data.resize(width * height * 4); // Assuming RGBA

        glBindTexture(GL_TEXTURE_2D, id);
        CHECK_GL_ERROR();

        glGetTexImage(GL_TEXTURE_2D, 0, TextureFormatTraits<T>::format, TextureFormatTraits<T>::type, data.data());
        CHECK_GL_ERROR();

        glBindTexture(GL_TEXTURE_2D, 0);
        CHECK_GL_ERROR();

        return true;
    }


    // Delete texture (already handled in destructor, but provided for completeness)
    void destroy() {
        if (id != 0) {
            glDeleteTextures(1, &id);
            CHECK_GL_ERROR();
            id = 0;
            width = 0;
            height = 0;
        }
    }

private:
    GLuint id;
    GLint width;
    GLint height;
};

