public class BufferedDataSet : DataSet, IEnumerator<DataSetRow> {
        private int bufferSize = 1000;
        private File file;
        private long fileLinesNumber;
        private long currentFileLineNumber;
        private int rowsLoaded;
        private string delimiter;
        internal FileReader fileReader = null;
        internal BufferedReader bufferedReader;
        internal List<DataSetRow> bufferedRows;
        internal IEnumerator<DataSetRow> bufferIterator;
        public DataSetRow Current {
            get {
                return bufferIterator.Current;
            }
        }
        object IEnumerator.Current {
            get {
                return bufferIterator.Current;
            }
        }
        public BufferedDataSet(File file, int inputSize, string delimiter) : base(inputSize) {
        }
        public BufferedDataSet(File file, int inputSize, int outputSize, string delimiter) : base(inputSize, outputSize) {
            this.delimiter = delimiter;
            this.file = file;
            this.fileReader = new FileReader(file);
            this.bufferedReader = new BufferedReader(fileReader);
            fileLinesNumber = countFileLines();
            loadNextBuffer();
        }
        private long countFileLines() {
            LineNumberReader lnr = new LineNumberReader(new FileReader(file));
            try {
                while (lnr.skip(long.MaxValue) > 0) {
                };
            } catch (IOException ex) {
            }
            return lnr.getLineNumber() + 1;
        }
        public override IEnumerator<DataSetRow> iterator() {
            return this;
        }
        public bool HasNext() {
            if (currentFileLineNumber < fileLinesNumber) {
                return true;
            }
            return false;
        }
        public DataSetRow Next() {
            if (!bufferIterator.MoveNext()) {
                this.loadNextBuffer(); 
            }
            currentFileLineNumber++; 
            return bufferIterator.Current; 
        }
        public void Remove() 
        {
            throw new System.NotSupportedException("Not supported yet."); 
        }
        private void loadNextBuffer() {
            try {
                string line = "";
                this.clear(); 
                rowsLoaded = 0;
                while (rowsLoaded < bufferSize) {
                    line = bufferedReader.readLine();
                    if (line == null) {
                        break;
                    }
                    rowsLoaded++;
                    double[] inputs = new double[InputSize];
                    double[] outputs = new double[OutputSize];
                    string[] values = line.Split(delimiter.ToCharArray(), StringSplitOptions.RemoveEmptyEntries);
                    if (values[0].Equals("")) {
                        continue; 
                    }
                    for (int i = 0; i < InputSize; i++) {
                        inputs[i] = Convert.ToDouble(values[i]);
                    }
                    for (int i = 0; i < OutputSize; i++) {
                        outputs[i] = Convert.ToDouble(values[InputSize + i]);
                    }
                    if (OutputSize > 0) {
                        this.addRow(new DataSetRow(inputs, outputs));
                    } else {
                        this.addRow(new DataSetRow(inputs));
                    }
                }
                bufferedRows = this.Rows;
                bufferIterator = bufferedRows.GetEnumerator();
            } catch (FileNotFoundException ex) {
                System.Console.WriteLine(ex.ToString());
                System.Console.Write(ex.StackTrace);
            } catch (IOException ex) {
                if (fileReader != null) {
                    try {
                        fileReader.close();
                    } catch (IOException) {
                    }
                }
                System.Console.WriteLine(ex.ToString());
                System.Console.Write(ex.StackTrace);
            } catch (java.lang.NumberFormatException ex) {
                if (fileReader != null) {
                    try {
                        fileReader.close();
                    } catch (IOException) {
                    }
                }
                System.Console.WriteLine(ex.ToString());
                System.Console.Write(ex.StackTrace);
                throw ex;
            }
        }
        public IEnumerator<DataSetRow> GetEnumerator() {
            return bufferIterator;
        }
        public void Dispose() {
            bufferIterator.Dispose();
        }
        public bool MoveNext() {
            return bufferIterator.MoveNext();
        }
        public void Reset() {
            bufferIterator.Reset();
        }
    }

func (c Checkpointer) Write(ctx context.Context, subscriptionName string, sequenceNumber int64) error {
	_, err := c.DB.ExecContext(
		ctx,
		`UPDATE subscriptions_checkpoints
		SET last_sequence_number = $1
		WHERE subscription_id = $2`,
		sequenceNumber,
		subscriptionName,
	)
	if err != nil {
		return fmt.Errorf("postgres.EventStore: failed to write subscription checkpoint: %w", err)
	}
	return nil
}

package main

import (
	"fmt"
	"log"
	"sync"

	"stargen" // Assuming stargen is a separate package
)

// Worker struct
type Worker struct {
	ID           int
	running      bool
	executions   int
	executionMax int
	display      Display
	stats        WorkerStats
	mu           sync.Mutex
}

// Display interface (for exporting)
type Display interface {
	Export(filename string, system *stargen.StellarSystem) error
}

// WorkerStats struct (for statistics)
type WorkerStats struct {
	TotalPlanets int
	HabitablePlanets int
}

// NewWorker creates a new worker
func NewWorker(id int, display Display, executionMax int) *Worker {
	return &Worker{
		ID:           id,
		running:      true,
		executions:   0,
		executionMax: executionMax,
		display:      display,
		stats:        WorkerStats{TotalPlanets: 0, HabitablePlanets: 0},
	}
}

// Stop stops the worker
func (w *Worker) Stop() {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.running = false
}

// Run starts the worker's main loop
func (w *Worker) Run() {
	for w.running {
		w.mu.Lock()
		if w.executions >= w.executionMax {
			w.running = false
			w.mu.Unlock()
			break
		}
		executionNumber := w.executions + 1
		w.mu.Unlock()

		// Generate stellar system
		system, err := stargen.GenerateStellarSystem(true, true, true)
		if err != nil {
			log.Printf("Worker %d: Error generating stellar system: %v", w.ID, err)
			w.Stop()
			break
		}

		// Export stellar system
		filename := fmt.Sprintf("system_worker_%d_execution_%d.txt", w.ID, executionNumber)
		err = w.display.Export(filename, system)
		if err != nil {
			log.Printf("Worker %d: Error exporting stellar system to %s: %v", w.ID, filename, err)
			w.Stop()
			break
		}

		// Update statistics
		w.updateStatistics(system)

		w.mu.Lock()
		w.executions++
		w.mu.Unlock()
	}
	log.Printf("Worker %d stopped after %d executions.", w.ID, w.executions)
}

// updateStatistics updates the worker's statistics
func (w *Worker) updateStatistics(system *stargen.StellarSystem) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.stats.TotalPlanets += len(system.Planets)
	for _, planet := range system.Planets {
		if planet.Habitable {
			w.stats.HabitablePlanets++
		}
	}
}

// GetStats returns the worker's statistics
func (w *Worker) GetStats() WorkerStats {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.stats
}

