def solve_candy_boxes(n, a):
    if n == 0:
        mean = sum(a) / len(a)
        for b in range(1, 1000001):
            if (sum(a) + b) / 4 == mean and max(a) - min(a) == b:
                return "YES", b
        return "NO"
    else:
        a.sort()
        mean = sum(a) / n
        for i in range(n):
            for j in range(1, 1000001):
                if j >= a[i] and j <= (4 * mean - sum(a[:i] + a[i+1:] + [j]) % 4 == 0 and
                                   a[i] + j >= a[i-1] if i > 0 else True and
                                   a[i] + j <= a[i+1] if i < n-1 else True and
                                   max(a[:i] + a[i+1:] + [j]) - min(a[:i] + a[i+1:] + [j]) == j):
                    return "YES", j
        return "NO"

def init_server_extensions(self):
        for modulename in self.server_extensions:
            try:
                mod = importlib.import_module(modulename)
                func = getattr(mod, 'load_jupyter_server_extension', None)
                if func is not None:
                    func(self)
            except Exception:
                if self.reraise_server_extension_failures:
                    raise
                self.log.warn("Error loading server extension %s", modulename,
