package com.timgroup.zmtp;

import java.io.FilterOutputStream;
import java.io.IOException;
import java.util.Iterator;

public class MessageOutputStream extends FilterOutputStream {

    public static final byte[] ANONYMOUS = {};

    public MessageOutputStream(FrameOutputStream out) throws IOException {
        super(out);
        writeGreeting(ANONYMOUS);
    }

    public MessageOutputStream(FrameOutputStream out, String identity) throws IOException {
        super(out);
        writeGreeting(identity.getBytes(Charsets.US_ASCII));
    }

    private void writeGreeting(byte[] identity) throws IOException {
        out().write(identity);
    }

    private FrameOutputStream out() {
        return (FrameOutputStream) this.out;
    }

    @Override
    public void write(int b) throws IOException {
        write(new byte[] {(byte) b});
    }

    @Override
    public void write(byte[] b, int off, int len) throws IOException {
        out().write(b, off, len);
    }

    public void write(Iterable frames) throws IOException {
        Iterator it = frames.iterator();
        while (it.hasNext()) {
            byte[] frame = it.next();
            out().writeFrame(frame, 0, frame.length, it.hasNext());
        }
    }

}

public class NetworkInputListener : InputListener
    {
        private MultiplayerController multiplayerController;
        private int blockWidth;
        private int blockHeight;
        public void Initialize(ControllerManager controllerManager, int blockWidth, int blockHeight)
        {
            base.Initialize(controllerManager);
            this.blockWidth = blockWidth;
            this.blockHeight = blockHeight;
            multiplayerController = MultiplayerController.GetInstance();
            multiplayerController.OnMessageReceived += ProcessNetworkData;
        }
        public void Stop()
        {
            multiplayerController.OnMessageReceived -= ProcessNetworkData;
        }
        private void ProcessNetworkData(byte[] message)
        {
            if (message[0] != 'M')
            {
                return;
            }
            if (message[1] == 'B')
            {
                var x = blockWidth - message[2] + 1;
                var y = blockHeight - message[3] + 1;
                base.ProcessBoardClick(x, y);
            }
            else if (message[1] == 'F')
            {
                base.ProcessFinishTurnClick();
            }
            else if (message[1] == 'S')
            {
                base.ProcessSplitButtonClick();
            }
        }
        public override void ProcessBoardClick(int x, int y)
        {
            byte[] message = {(byte)'M', (byte)'B', (byte) x, (byte) y};
            multiplayerController.SendMessage(message);
            base.ProcessBoardClick(x, y);
        }
        public override void ProcessSplitButtonClick()
        {
            byte[] message = {(byte) 'M', (byte) 'S'};
            multiplayerController.SendMessage(message);
            base.ProcessSplitButtonClick();
        }
        public override void ProcessFinishTurnClick()
        {
            byte[] message = {(byte) 'M', (byte) 'F'};
            multiplayerController.SendMessage(message);
            base.ProcessFinishTurnClick();
        }
    }

class OverlayContainer extends Component {
    /**
     * OverlayContainer component's property types.
     *
     * @static
     */
    static propTypes = {
        /**
         * The browser which is used currently.
         *
         * NOTE: Used by UserMediaPermissionsOverlay only.
         *
         * @private
         * @type {string}
         */
        _browser: React.PropTypes.string,

        /**
         * The indicator which determines whether the status of the
         * JitsiConnection object has been "established" or not.
         *
         * NOTE: Used by PageReloadOverlay only.
         *
         * @private
         * @type {boolean}
         */
        _connectionEstablished: React.PropTypes.bool,

        /**
         * The indicator which determines whether a critical error for reload
         * has been received.
         *
         * NOTE: Used by PageReloadOverlay only.
         *
         * @private
         * @type {boolean}
         */
        _haveToReload: React.PropTypes.bool,

        /**
         * The indicator which determines whether the GUM permissions prompt is
         * displayed or not.
         *
         * NOTE: Used by UserMediaPermissionsOverlay only.
         *
         * @private
         * @type {boolean}
         */
        _isMediaPermissionPromptVisible: React.PropTypes.bool,

        /**
         * The indicator which determines whether the reload was caused by
         * network failure.
         *
         * NOTE: Used by PageReloadOverlay only.
         *
         * @private
         * @type {boolean}
         */
        _isNetworkFailure: React.PropTypes.bool,

        /**
         * The reason for the error that will cause the reload.
         *
         * NOTE: Used by PageReloadOverlay only.
         *
         * @private
         * @type {string}
         */
        _reason: React.PropTypes.string,

        /**
         * The indicator which determines whether the GUM permissions prompt is
         * displayed or not.
         *
         * NOTE: Used by SuspendedOverlay only.
         *
         * @private
         * @type {string}
         */
        _suspendDetected: React.PropTypes.bool
    }

    /**
     * Initializes a new ReloadTimer instance.
     *
     * @param {Object} props - The read-only properties with which the new
     * instance is to be initialized.
     * @public
     */
    constructor(props) {
        super(props);

        this.state = {
            /**
             * Indicates whether the filmstrip only mode is enabled or not.
             *
             * @type {boolean}
             */
            filmstripOnly: interfaceConfig.filmStripOnly
        };
    }

    /**
     * React Component method that executes once component is updated.
     *
     * @inheritdoc
     * @returns {void}
     * @protected
     */
    componentDidUpdate() {
        // FIXME: Temporary workaround until everything is moved to react.
        APP.UI.overlayVisible
            = (this.props._connectionEstablished && this.props._haveToReload)
                || this.props._suspendDetected
                || this.props._isMediaPermissionPromptVisible;
    }

    /**
     * Implements React's {@link Component#render()}.
     *
     * @inheritdoc
     * @returns {ReactElement|null}
     * @public
     */
    render() {
        const { filmstripOnly } = this.state;
        let overlayComponent, props;

        if (this.props._connectionEstablished && this.props._haveToReload) {
            overlayComponent
                = filmstripOnly
                    ? PageReloadFilmstripOnlyOverlay
                    : PageReloadOverlay;
            props = {
                isNetworkFailure: this.props._isNetworkFailure,
                reason: this.props._reason
            };
        } else if (this.props._suspendDetected) {
            overlayComponent
                = filmstripOnly
                    ? SuspendedFilmstripOnlyOverlay
                    : SuspendedOverlay;
        } else if (this.props._isMediaPermissionPromptVisible) {
            overlayComponent
                = filmstripOnly
                    ? UserMediaPermissionsFilmstripOnlyOverlay
                    : UserMediaPermissionsOverlay;
            props = { browser: this.props._browser };
        }

        return (
            overlayComponent
                ? React.createElement(overlayComponent, props)
                : null);
    }
}

func (i *individual) selectOperator() operator {
	f := randFloat32()
	f0 := float32(0.0)
	for j, r := range i.rates {
		f1 := f0 + r
		if f < f1 {
			return i.ops[j]
		}
		f0 = f1
	}
	return i.ops[randIntn(len(i.ops))]
}

namespace SampleApi.Plumbing.OAuth
{
    using System;
    using System.Collections.Generic;
    using System.Net.Http;
    using System.Net.Http.Headers;
    using System.Security.Claims;
    using System.Threading.Tasks;
    using Microsoft.IdentityModel.Tokens;
    using SampleApi.Plumbing.Claims;
    using SampleApi.Plumbing.Configuration;
    using SampleApi.Plumbing.Errors;
    using SampleApi.Plumbing.Logging;
    using SampleApi.Plumbing.Utilities;

    /*
     * The class from which OAuth calls are initiated
     */
    public sealed class OAuthAuthenticator
    {
        private readonly OAuthConfiguration configuration;
        private readonly JsonWebKeyResolver jsonWebKeyResolver;
        private readonly HttpProxy httpProxy;
        private readonly LogEntry logEntry;

        public OAuthAuthenticator(
            OAuthConfiguration configuration,
            JsonWebKeyResolver jsonWebKeyResolver,
            HttpProxy httpProxy,
            ILogEntry logEntry)
        {
            this.configuration = configuration;
            this.jsonWebKeyResolver = jsonWebKeyResolver;
            this.httpProxy = httpProxy;
            this.logEntry = (LogEntry)logEntry;
        }

        /*
         * Validate the access token using the jose-jwt library
         */
        public async Task ValidateTokenAsync(string accessToken)
        {
            using (this.logEntry.CreatePerformanceBreakdown("validateToken"))
            {
                try
                {
                    // Read the token without validating it, to get its key identifier
                    var handler = new CustomJwtSecurityTokenHandler();
                    handler.InboundClaimTypeMap.Clear();
                    var token = handler.ReadJwtToken(accessToken);

                    // Get the token signing public key as a JSON web key
                    var jwk = await this.jsonWebKeyResolver.GetKeyForId(token.Header.Kid);
                    if (jwk == null)
                    {
                        var context = $"The access token kid was not found at the JWKS endpoint";
                        throw ErrorFactory.CreateClient401Error(context);
                    }

                    // Set token validation parameters, and note that Cognito does not provide an audience claim in access tokens
                    var tokenValidationParameters = new TokenValidationParameters
                    {
                        IssuerSigningKey = jwk,
                        ValidateIssuer = true,
                        ValidIssuer = this.configuration.Issuer,
                        ValidateAudience = string.IsNullOrWhiteSpace(this.configuration.Audience) ? false : true,
                        ValidAudience = this.configuration.Audience,
                    };

                    // The base JwtSecurityTokenHandler checks the above fields and the jose library validates the signature
                    SecurityToken result;
                    return handler.ValidateToken(accessToken, tokenValidationParameters, out result);
                }
                catch (Exception ex)
                {
                    throw ErrorUtils.FromTokenValidationError(ex);
                }
            }
        }

        /*
         * Perform OAuth user info lookup
         */
        public async Task GetUserInfoAsync(string accessToken)
        {
            using (this.logEntry.CreatePerformanceBreakdown("userInfoLookup"))
            {
                try
                {
                    using (var client = new HttpClient(this.httpProxy.GetHandler()))
                    {
                        // Send the request
                        client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
                        var request = new HttpRequestMessage(HttpMethod.Get, this.configuration.UserInfoEndpoint);
                        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", accessToken);
                        var response = await client.SendAsync(request);

                        // Report errors with a response
                        if (!response.IsSuccessStatusCode)
                        {
                            var status = (int)response.StatusCode;
                            var text = await response.Content.ReadAsStringAsync();
                            throw ErrorUtils.FromUserInfoError(status, text, this.configuration.UserInfoEndpoint);
                        }

                        // Convert from JSON data to an array of claims
                        var json = await response.Content.ReadAsStringAsync();
                        return ClaimsReader.UserInfoClaims(json);
                    }
                }
                catch (Exception ex)
                {
                    // Report connectity errors
                    throw ErrorUtils.FromUserInfoError(ex, this.configuration.UserInfoEndpoint);
                }
            }
        }
    }
}

