public IReadOnlyDictionary<string, IReadOnlyList<Commit>> GetCommitsForAllFilePaths(string commitHash)
        {
            Dictionary<string, List<string>> contentHashesByPath = GetFilePaths(commitHash).ToDictionary(x => x, x=> new List<string>());
            Dictionary<string, Commit> earliestCommit = new Dictionary<string, Commit>();
            Dictionary<string, IReadOnlyList<TreeEntry>> treeCache = new Dictionary<string, IReadOnlyList<TreeEntry>>();
            foreach (Commit commit in GetCommits())
            {
                foreach (string filePath in contentHashesByPath.Keys)
                {
                    if (TryGetContentHashForPath(commit.Tree, filePath, out string contentHash, treeCache))
                    {
                        if (!earliestCommit.ContainsKey(contentHash))
                        {
                            contentHashesByPath[filePath].Add(contentHash);
                            earliestCommit[contentHash] = commit;
                        }
                        else if (earliestCommit[contentHash].Timestamp > commit.Timestamp)
                        {
                            earliestCommit[contentHash] = commit;
                        }
                    }
                }
            }
            Dictionary<string, IReadOnlyList<Commit>> result = new Dictionary<string, IReadOnlyList<Commit>>();
            foreach (string filePath in contentHashesByPath.Keys)
            {
                result[filePath] = contentHashesByPath[filePath].Select(x => earliestCommit[x]).ToList();
            }
            return result;
        }

var maximumNumber = function(num, change) {
    const size = num.length;

    // Iterate through the string, replacing digits if necessary
    for (let i = 0; i < size; i++) {
        // If the digit from num is mapped to a smaller digit in change, replace it
        if (change[num[i]] !== num[i]) {
            // Replace the digit with the mapped digit in change
            num[i] = change[num[i]];
            break;
        }
    }

    // Return the modified string
    return num;
};

func (p *PrepPost) OnMessage(Message) (response Response) {
	if time.Since(p.last.checked) < p.checkDuration {
		return Response{}
	}
	defer func() {
		p.last.checked = time.Now()
	}()
	pi, err := p.recentPrepPost()
	if err != nil {
		if err != errNotPost {
			log.Printf("[WARN] failed to check for new post, %v", err)
		}
		return Response{}
	}
	defer func() {
		p.last.prepPost = pi
	}()
	if p.last.prepPost.URL != "" && pi.URL != p.last.prepPost.URL {
		log.Printf("[INFO] detected new prep topic %s", pi.URL)
		return Response{Send: true, Pin: true, Text: fmt.Sprintf("Сбор тем начался - %s", pi.URL)}
	}
	return Response{}
}

def shanum(filename, dmax=None, noprint=True):
    if isinstance(filename, Curve):
        curve = filename
        with tempfile.NamedTemporaryFile('w+b', delete=False) as f:
            curve.save(f)
            filename = f.name
    cmdline = ['shanum', filename]
    if dmax is not None:
        cmdline.append(str(float(dmax)))
    result = execute_command(cmdline, noprint=noprint)
    for l in result:
        l = l.strip()
        if l.startswith('Dmax='):
            dmax = float(l.split('=')[1])
        elif l.startswith('Smax='):
            qmax = float(l.split('=')[1])
        elif l.startswith('Nsh='):
            nsh = float(l.split('=')[1])
        elif l.startswith('Nopt='):
            nopt = float(l.split('=')[1])
        elif l.startswith('Sopt='):
            qmaxopt = float(l.split('=')[1])
    return dmax, nsh, nopt, qmaxopt

