#include <iostream>
#include <algorithm>
#include <vector>

class TripletQuartet {
private:
    int g1, g2, g3;
    double weight;
    std::string label;

    int binomial(int n, int k) {
        if (k > n || k < 0) return 0;
        if (k > n - k) k = n - k;
        int result = 1;
        for (int i = 1; i <= k; ++i) {
            result *= (n - i + 1);
            result /= i;
        }
        return result;
    }

public:
    TripletQuartet(int g1, int g2, int g3, double weight)
        : g1(g1), g2(g2), g3(g3), weight(weight) {
        std::vector<int> components{ g1, g2, g3 };
        std::sort(components.begin(), components.end(), std::greater<int>());
        g1 = components[0];
        g2 = components[1];
        g3 = components[2];
    }

    // Copy constructor
    TripletQuartet(const TripletQuartet& tq) : g1(tq.g1), g2(tq.g2), g3(tq.g3), weight(tq.weight), label(tq.label) {}

    // Assignment operator
    TripletQuartet& operator=(const TripletQuartet& tq) {
        g1 = tq.g1;
        g2 = tq.g2;
        g3 = tq.g3;
        weight = tq.weight;
        label = tq.label;
        return *this;
    }

    void setLabel(const std::string& lab) {
        label = lab;
    }

    int getIndex() const {
        int idx;
        if (g1 == g2 && g1 == g3) {
            idx = 0;
        } else if (g1 == g2 || g1 == g3 || g2 == g3) {
            idx = 1 + binomial(g1 - 1, g2 - g1);
        } else {
            idx = 1 + binomial(g1, g2) * (binomial(g2, g3) + binomial(g3 - 1, g2 - 1));
        }
        return idx;
    }

    // Getters and setters for g1, g2, g3, weight, and label can be added as per requirements.
};

int main() {
    TripletQuartet tq(5, 3, 4, 0.5);
    tq.setLabel("Triplet_1");
    std::cout << "Triplet index: " << tq.getIndex() << std::endl;
    return 0;
}

class Action:
    """
    Actions are based on pygame keys, even though we do not actually
    use those keys. They're a handy leftover to vectorise actions
    and make thinking with them and programming game dynamics easier.
    """

    def __init__(self, *args):
        self.keys = tuple(sorted(args))

    def as_vector(self):
        """
        Directional keys are used to encode directions.
        Opposite directions cancel eachother out.
        """
        return Vector2(-1 * (K_LEFT in self.keys) + 1 * (K_RIGHT in self.keys),
                       -1 * (K_UP in self.keys) + 1 * (K_DOWN in self.keys))

    def __str__(self):
        _key_name = lambda k: pygame.key.name(k) if pygame.key.name(k) != 'unknown key' else str(k)
        key_rep = ','.join(_key_name(k) for k in self.keys)
        if len(self.keys) <= 1:
            return key_rep or 'noop'
        else:
            return '[{}]'.format(key_rep)

    def __repr__(self):
        _key_name = lambda k: pygame.key.name(k) if pygame.key.name(k) != 'unknown key' else str(k)
        key_rep = ','.join(_key_name(k) for k in self.keys)
        return 'Action({})'.format(key_rep or 'noop')

    def __eq__(self, other):
        # if not hasattr(other, 'keys'):
        #     return False
        return isinstance(other, Action) and self.keys == other.keys

    def __hash__(self):
        return hash(self.keys)

    @classmethod
    def from_vectors(*v):
        pass

class ProcessOutputReader implements Runnable {
    private static final Log log = LogFactory.getLog(ProcessOutputReader.class);

    private final InputStream input;
    private final OutputStream output;

    /**
     * The size in bytes of the buffer used to transfer data from the stream to
     * the buffer.
     */
    private final static int BUFFER_SIZE = 4096;

    /**
     * Creates a reader for the given input stream and output stream. The output
     * stream may be null, and in that case the input stream is read and the
     * data discarded.
     *
     * @param input
     *        the stream to read input from (not null).
     * @param output
     *        the stream to write data to (may be null).
     */
    protected ProcessOutputReader(final InputStream input, final OutputStream output) {
        this.input = input;
        this.output = output;
    }

    @Override
    public void run() {
        final BufferedInputStream bis = new BufferedInputStream(input);
        long bytesRead = 0;
        long bytesWritten = 0;

        try {
            final byte[] buffer = new byte[BUFFER_SIZE];

            int bytesReadThisTime;
            try {
                if (Thread.currentThread().isInterrupted()) {
                    log.debug("Normal interruption"); //$NON-NLS-1$
                    return;
                }

                while ((bytesReadThisTime = bis.read(buffer)) != -1) {
                    bytesRead += bytesReadThisTime;

                    if (Thread.currentThread().isInterrupted()) {
                        log.debug("Normal interruption"); //$NON-NLS-1$
                        return;
                    }

                    if (output != null) {
                        output.write(buffer, 0, bytesReadThisTime);
                        bytesWritten += bytesReadThisTime;
                    }
                }
            } catch (final IOException e) {
                log.warn("Error writing to output stream", e); //$NON-NLS-1$
            }
        } finally {
            try {
                bis.close();
            } catch (final IOException e) {
                log.warn("Error closing buffered input stream", e); //$NON-NLS-1$
            }

            final String messageFormat = "Read {0} bytes from input, wrote {1} bytes to output"; //$NON-NLS-1$
            final String message = MessageFormat.format(messageFormat, bytesRead, bytesWritten);
            log.debug(message);
        }
    }
}

public class Fps {

    private static final int MAX_FPS = 30;
    private static final int MAX_DELAY = 1000 / MAX_FPS;

    private static long currentFps;
    private static long counter = 0, startTime = 0;
    private static long startTimeForMeasureDelay = 0;

    /**
     * Returns current FPS for an application. Note that if getFps hadn't been run before it will return zero.
     *
     * @return current FPS.
     */
    public static long getFps() {
	counter++;
	if (startTime == 0) {
	    startTime = System.currentTimeMillis();
	}
	if ((System.currentTimeMillis() - startTime) >= 1000) {
	    currentFps = counter;
	    counter = 0;
	    startTime = System.currentTimeMillis();
	}
	return currentFps;
    }

    public static void startMeasuringDelay() {
	startTimeForMeasureDelay = System.currentTimeMillis();
    }

    public static long getDelay() {
	long delay = System.currentTimeMillis() - startTimeForMeasureDelay;
	return (delay > MAX_DELAY ? 0 : MAX_DELAY - delay);
    }

    public static long getDelay(int maxfps) {
	final int maxDelay = 1000 / maxfps;
	long delay = System.currentTimeMillis() - startTimeForMeasureDelay;
	return (delay > maxDelay ? 0 : maxDelay - delay);
    }
}

