    //Other optional Boot Info
    uint64_t    rsdp_address;   // Address of the RSDP if ACPI is supported (optional)
    uint32_t    flags; // Flags to pass more data (optional)

    // Alignment to prevent false sharing
    uint32_t    padding[4];
} boot_params_t;



