import _ from 'lodash';
import { seriesList } from '../../../helpers/series_list';

function KueryDataSourceProvider(Private) {
  const Schemas = Private.Schemas;
  const api = Private("${ hostname }/api/data/kable");
  const KueryExpression = Private.KueryExpression;

  return {
    name: 'kable',
    id: 'kable',
    descriptions: ['Kable data source'],
    help: 'name of the index pattern to use for the data source',
    args: [
      {
        name: 'expression',
        types: ['kuery', 'lucene'],
        required: true,
        help: 'expression to filter the data',
      },
    ],
    serialize: (expression) => ({ expression }),
    template: function (args) {
      return [
        {
          template: '{{expression}}',
          label: 'Expression',
          default: args.expression,
        },
      ];
    },
    editor: function (args) {
      return {
        template: '<kuery-editor ng-model="current.args.expression"></kuery-editor>',
        controller: function ($scope) {
          $scope.current.args.expression = $scope.current.args.expression || '';
        },
      };
    },
    extract: function (expression) {
      return {
        expression: expression,
      };
    },
  };
}

export function KueryResponseHandler Private(Schemas) {
  return (expression, resp) => {
    if (!resp ||!resp.data) {
      throw new Error('Invalid Kable API response');
    }

    const header = resp.data[0];
    const timeColIndex = _.findIndex(header, (col) => col === 'time');
    if (timeColIndex === -1) {
      throw new Error('Time column not found in Kable API response');
    }

    const seriesList = _.compact(
      _.map(resp.data.slice(1), (row) => {
        const time = row[timeColIndex];
        const value = row[header.length - 1];
        if (time!== null && value!== null) {
          return { time, value };
        }
        return null;
      })
    );

    return {
      type: 'series_list',
      label: header[header.length - 1],
      data: seriesList,
    };
  };
}

