class AsyncWallet:
    def __init__(self, api_token, proxy=None, backend=AioHttpBackEnd):
        self.api = QiwiApi(api_token, backend=backend, proxy=proxy)
        self._profile = None

    @property
    def phone(self):
        if self._profile is None:
            raise ValueError("Profile not fetched. Call profile() first.")
        return self._profile.phone

    @property
    def username(self):
        if self._profile is None:
            raise ValueError("Profile not fetched. Call profile() first.")
        return self._profile.username

