        try:
            balance = await self.api.balance(currency=currency)
            return balance
        except Exception as e:
            print(f"Error fetching balance: {e}")
            return None

    async def profile(self):
        try:
            self._profile = await self.api.profile()
            return self._profile
        except Exception as e:
            print(f"Error fetching profile: {e}")
            return None

    async def history(self, rows=10, currency=643, operation=None):
        try:
            history = await self.api.history(rows=rows, currency=currency, operation=operation)
