				}
			}
		}

def create_sort_link(pretty_name, sort_field, get_params, sort, order):
    get_params.append(('sort', sort_field))
    if sort == sort_field and order == 'asc':
        get_params.append(('order', 'desc'))
    else:
        get_params.append(('order', 'asc'))
    url_class = ''
    if sort == sort_field:
        url_class = ' class="sort-icon ed-sprite-sort-%s"' % order
    return u'<a href="?%s"%s>%s</a>' % (urllib.urlencode(get_params),
                                        url_class, pretty_name)

public static ESValue evaluateExpression(ESExpression expression) 
	{
		List<ESToken> tokens = new LinkedList<>();
		List<ESToken> origtokens = expression.getList();
		for(ESToken token : origtokens)
		{
			ESToken newtoken;
			if(token instanceof ESExpression)
			{
				newtoken = evaluateExpression((ESExpression)token); 
			}
			else
			{
				newtoken = token;
			}
			tokens.add(newtoken);
		}
		for(ESPrecedence p : ESPrecedence.values()) 
		{
			System.err.println(p.name());
			for(int i = 0; i < tokens.size(); i++)
			{
				ESToken currToken = tokens.get(i);
				System.err.println(currToken.toString());
				if(currToken instanceof ESOperator && ((ESOperator)(currToken)).getPrecedence() == p)
				{
					System.err.println(currToken.getSymbol());
					if(currToken instanceof ESUnaryOperator)
					{
						ESValue result = null;
						ESUnaryOperator operator = (ESUnaryOperator)tokens.remove(i);
						ESToken op0token = tokens.remove(i);
						if(op0token instanceof ESVariableToken)
						{
						}
						else if(op0token instanceof ESValue)
						{
							result = operator.operate((ESValue)op0token);
						}
						else throw new ESEvaluationException();
						tokens.add(i, result);
					}
					else if(currToken instanceof ESBinaryOperator)
					{
						i--;
						ESToken op1token = tokens.remove(i);
						ESBinaryOperator operator = (ESBinaryOperator)tokens.remove(i);
						ESToken op2token = tokens.remove(i);
						ESValue op1value = (ESValue)op1token;
						ESValue op2value = (ESValue)op2token;
						ESValue result = operator.operate(op1value, op2value);
						tokens.add(i, result);
					}
					else if(currToken instanceof ESVariableOperator)
					{
					}
					else if(currToken instanceof ESUnaryVariableOperator)
					{
					}
					else throw new ESEvaluationException();
					System.err.println(tokens.toString() + " " + i);
				}
			}
		}
		if(tokens.size() > 1)
			throw new ESEvaluationException();
		return (ESValue)(tokens.size() > 0 ? tokens.get(0) : null);
	}

public void Encode(ImageHolder image, Stream stream)
        {
            ushort max = JpegConstants.MaxLength;
            if (image.Width >= max || image.Height >= max)
            {
                throw new ImageFormatException($"Image is too large to encode at {image.Width}x{image.Height}.");
            }
            this.outputStream = stream;
            int scale;
            if (this.quality < 50)
            {
                scale = 5000 / this.quality;       
            }
            else
            {
                scale = 200 - (this.quality * 2);  
            }
            InitQuantizationTable(0, scale, ref this.luminanceQuantTable);
            InitQuantizationTable(1, scale, ref this.chrominanceQuantTable);
            this.WriteApplicationHeader((short)HorizontalResolution, (short)HorizontalResolution);
            this.WriteDefineQuantizationTables();
            this.WriteStartOfFrame(image.Width, image.Height);
            this.WriteDefineHuffmanTables();
            var sosHeader = this.GetSosHeader();
            this.outputStream.Write(sosHeader, 0, sosHeader.Length);
            this.WriteImageData(image);
            this.Emit(0x7f, 7);
            this.buffer[0] = JpegConstants.Markers.XFF;
            this.buffer[1] = JpegConstants.Markers.EOI;
            stream.Write(this.buffer, 0, 2);
            stream.Flush();
        }

public boolean canAssignTo(Type destType) {
        if ( !(destType instanceof PointerType) ) return false;
        Type destTargetType = ((PointerType)destType).targetType;
        Type srcTargetType = this.targetType;
        if ( destTargetType instanceof ClassSymbol &&
             this.targetType instanceof ClassSymbol )
        {
            ClassSymbol thisClass   = (ClassSymbol)srcTargetType;
            ClassSymbol targetClass = (ClassSymbol)destTargetType;
            return thisClass.isInstanceof(targetClass);
        }
        return srcTargetType == destTargetType;
    }

def _GetAllShowList(self):
    today = datetime.date.today().strftime("%Y%m%d")
    saveFile = '_epguides_' + today + '.csv'
    saveFilePath = os.path.join(self._saveDir, saveFile)
    if os.path.exists(saveFilePath):
      with open(saveFilePath, 'r') as allShowsFile:
        self._allShowList = allShowsFile.read()
    else:
      self._allShowList = util.WebLookup(self.ALLSHOW_IDLIST_URL).strip()
      if self._ParseShowList(checkOnly=True):
        with open(saveFilePath, 'w') as allShowsFile:
          goodlogging.Log.Info("EPGUIDE", "Adding new EPGUIDES file: {0}".format(saveFilePath), verbosity=self.logVerbosity)
          allShowsFile.write(self._allShowList)
        globPattern = '_epguides_????????.csv'
        globFilePath = os.path.join(self._saveDir, globPattern)
        for filePath in glob.glob(globFilePath):
          if filePath != saveFilePath:
            goodlogging.Log.Info("EPGUIDE", "Removing old EPGUIDES file: {0}".format(filePath), verbosity=self.logVerbosity)
            os.remove(filePath)

import os

class Config:
    def __init__(self):
        self.data_provider = os.getenv('DATA_PROVIDER')
        self.s3_access_key = os.getenv('S3_ACCESS_KEY')
        self.s3_secret_key = os.getenv('S3_SECRET_KEY')
        self.s3_bucket_name = os.getenv('S3_BUCKET_NAME')
        self.azure_storage_account = os.getenv('AZURE_STORAGE_ACCOUNT')
        self.azure_storage_key = os.getenv('AZURE_STORAGE_KEY')
        self.azure_table_name = os.getenv('AZURE_TABLE_NAME')
        self.mongo_uri = os.getenv('MONGO_URI')
        self.mongo_db_name = os.getenv('MONGO_DB_NAME')

        if self.data_provider not in ['S3', 'Azure Tables', 'Mongo']:
            raise ValueError(f"Unsupported data provider: {self.data_provider}")

        if self.data_provider == 'S3':
            if not all([self.s3_access_key, self.s3_secret_key, self.s3_bucket_name]):
                raise ValueError("Missing required S3 configuration")
        elif self.data_provider == 'Azure Tables':
            if not all([self.azure_storage_account, self.azure_storage_key, self.azure_table_name]):
                raise ValueError("Missing required Azure Tables configuration")
        elif self.data_provider == 'Mongo':
            if not all([self.mongo_uri, self.mongo_db_name]):
                raise ValueError("Missing required MongoDB configuration")

struct ic_symbol *ic_type_param_mangled_name(struct ic_type_param *tparam) {
    struct ic_symbol *sym = 0;
    if (!tparam) {
        puts("ic_type_param_mangled_name: tparam was null");
        return 0;
    }
    if (tparam->tdecl) {
        sym = ic_decl_type_mangled_name(tparam->tdecl);
        if (!sym) {
            puts("ic_type_param_mangled_name: call to ic_decl_type_mangled_name failed");
            return 0;
        }
    } else {
        sym = &(tparam->name);
    }
    return sym;
}

