$(window).on('load', function() {
  // Click event listener for clickable rows
  $('.clickable-row').on('click', function() {
    alert('Row clicked!');
  });

  function updateFooterPosition() {
    const headerHeight = $('#header').outerHeight(true) || 0; // Include margin
    const contentHeight = $('#content').outerHeight(true) || 0; // Include margin
    const windowHeight = $(window).height();
    const combinedHeight = headerHeight + contentHeight;

    if (combinedHeight > windowHeight) {
      $('#footer').removeClass('absolute').addClass('relative');
    } else {
      $('#footer').removeClass('relative').addClass('absolute');
    }
  }

  // Initial footer position update
  updateFooterPosition();


  // Window resize event listener
  $(window).on('resize', function() {
    updateFooterPosition();
  });
});

