class Solution:

	def isDivisibleBy10(self, bin):
		n = len(bin)
		if bin[n - 1] == '1':
			return 0
		sum = 0
		for i in range(n - 2, -1, -1):
			if bin[i] == '1':
				posFromRight = n - i - 1
				if posFromRight % 4 == 1:
					sum = sum + 2
				elif posFromRight % 4 == 2:
					sum = sum + 4
				elif posFromRight % 4 == 3:
					sum = sum + 8
				else:
					sum = sum + 6
		if sum % 10 == 0:
			return 1
		return 0

@Test
    public void testShortFragmentClipping() throws Exception {
        final File output = File.createTempFile("testShortFragmentClipping", ".bam");
        output.deleteOnExit();
        doMergeAlignment(new File(TEST_DATA_DIR, "cliptest.unmapped.sam"),
                Collections.singletonList(new File(TEST_DATA_DIR, "cliptest.aligned.sam")),
                null, null, null, null,
                false, true, false, 1,
                "0", "1.0", "align!", "myAligner",
                true,
                new File(TEST_DATA_DIR, "cliptest.fasta"), output,
                SamPairUtil.PairOrientation.FR, null,
                null, null, null, null);
        final SamReader result = SamReaderFactory.makeDefault().open(output);
        final Map<String, SAMRecord> firstReadEncountered = new HashMap<>();
        for (final SAMRecord rec : result) {
            final SAMRecord otherEnd = firstReadEncountered.get(rec.getReadName());
            if (otherEnd == null) {
                firstReadEncountered.put(rec.getReadName(), rec);
            } else {
                final int fragmentStart = Math.min(rec.getAlignmentStart(), otherEnd.getAlignmentStart());
                final int fragmentEnd = Math.max(rec.getAlignmentEnd(), otherEnd.getAlignmentEnd());
                final String[] readNameFields = rec.getReadName().split(":");
                final int expectedFragmentStart = Integer.parseInt(readNameFields[1]);
                final int expectedFragmentEnd = Integer.parseInt(readNameFields[2]);
                Assert.assertEquals(fragmentStart, expectedFragmentStart, rec.getReadName());
                Assert.assertEquals(fragmentEnd, expectedFragmentEnd, rec.getReadName());
            }
        }
        result.close();
    }

def SetGroupUpdateMask(unused_ref, args, request):
  update_mask = []
  if (args.IsSpecified('display_name')
      or args.IsSpecified('clear_display_name')):
    update_mask.append('display_name')
  if (args.IsSpecified('description')
      or args.IsSpecified('clear_description')):
    update_mask.append('description')
  if not update_mask:
    raise exceptions.InvalidArgumentException(
        'Must specify at least one field mask.')
  request.updateMask = ','.join(update_mask)
  return request

abstract class ImmutableSortedMapTranslatorFactory<K extends Comparable<? super K>, V>
    implements TranslatorFactory<ImmutableSortedMap<K, V>> {

  private final TypeToken<K> keyType = new TypeToken<K>(getClass()) {};
  private final TypeToken<V> valueType = new TypeToken<V>(getClass()) {};
  private final String keyProperty;
  private final String valueProperty;

  ImmutableSortedMapTranslatorFactory() {
    this("key", "value");
  }

  /** Constructs a instance that's compatible with models migrated from {@code @Mapify}. */
  ImmutableSortedMapTranslatorFactory(String keyProperty, String valueProperty) {
    this.keyProperty = checkNotNull(keyProperty);
    this.valueProperty = checkNotNull(valueProperty);
  }

  /** Allows for changing the field data structure before it's written to the raw entity object. */
  ImmutableSortedMap<K, V> transformBeforeSave(ImmutableSortedMap<K, V> map) {
    return map;
  }

  @Override
  public final Translator<ImmutableSortedMap<K, V>>
      create(Path path, Property property, Type type, CreateContext ctx) {
    if (!ImmutableSortedMap.class.equals(erase(type))) {
      return null;  // skip me and try to find another matching translator
    }
    Type fieldKeyType = getTypeParameter(type, ImmutableSortedMap.class.getTypeParameters()[0]);
    Type fieldValueType = getTypeParameter(type, ImmutableSortedMap.class.getTypeParameters()[1]);
    if (fieldKeyType == null || fieldValueType == null) {
      return null;  // no type information is available
    }
    if (!keyType.isSupertypeOf(fieldKeyType) || !valueType.isSupertypeOf(fieldValueType)) {
      return null;  // this ImmutableSortedMap does not have the same concrete component types
    }
    ctx.enterCollection(path);
    ctx.enterEmbed(path);
    try {
      // The component types can also be translated by Objectify!
      TranslatorRegistry translators = ctx.getFactory().getTranslators();
      final Translator<K> keyTranslator =
          translators.create(path.extend(keyProperty), property, fieldKeyType, ctx);
      final Translator<V> valueTranslator =
          translators.create(path.extend(valueProperty), property, fieldValueType, ctx);
      return new ListNodeTranslator<ImmutableSortedMap<K, V>>() {
        @Override
        protected ImmutableSortedMap<K, V> loadList(Node node, LoadContext ctx) {
          ImmutableSortedMap.Builder<K, V> map =
              new ImmutableSortedMap.Builder<>(Ordering.natural());
          for (Node child : node) {
            try {
              map.put(keyTranslator.load(child.get(keyProperty), ctx),
                  valueTranslator.load(child.get(valueProperty), ctx));
            } catch (SkipException e) {
              // no problem, just skip that one
            }
          }
          return map.build();
        }

        @Override
        protected Node saveList(
            @Nullable ImmutableSortedMap<K, V> mapFromPojo,
            Path path,
            boolean index,
            SaveContext ctx) {
          checkState(!index, "At path %s: Index not allowed", path);
          ImmutableSortedMap<K, V> mapToSave = transformBeforeSave(
              ImmutableSortedMap.copyOfSorted(nullToEmpty(mapFromPojo)));
          if (mapToSave.isEmpty()) {
            throw new SkipException();  // Datastore doesn't store empty lists
          }
          Node node = new Node(path);
          for (Map.Entry<K, V> entry : mapToSave.entrySet()) {
            Node item = new Node(path);
            item.put(keyProperty,
                keyTranslator.save(entry.getKey(), path.extend(keyProperty), index, ctx));
            item.put(valueProperty,
                valueTranslator.save(entry.getValue(), path.extend(valueProperty), index, ctx));
            node.addToList(item);
          }
          return node;
        }
      };
    } finally {
      ctx.exitEmbed();
      ctx.exitCollection();
    }
  }
}

public class StopAtSameElementType implements ChangePropagationFunction {

	@Override
	public double isChangePropagated(FilterSettings filterSettings, KnowledgeElement currentElement, Link link) {
		KnowledgeElement traversedElement = link.getOppositeElement(currentElement);
		return traversedElement.getTypeAsString().equals(filterSettings.getSelectedElement().getTypeAsString()) ? 0.0
				: 1.0;
	}
}

public abstract class AbstractTabularSmileClassifier implements Function<TabularInstance, Integer> {
    private static final Logger LOGGER = LoggerFactory.getLogger(AbstractTabularSmileClassifier.class);

    private final boolean useDiscretizedValues;

    private SoftClassifier<double[]> classifier;


    /**
     * Creates the instance
     *
     * @param useDiscretizedValues if true, the model will be learned on transformed, i.e., original values.
     *                             Generally, this is to be preferred but not always possible.
     */
    AbstractTabularSmileClassifier(boolean useDiscretizedValues) {
        this.useDiscretizedValues = useDiscretizedValues;
    }

    private static Number toNumeric(Object obj) {
        Number result;
        if (Boolean.FALSE.equals(obj))
            result = 0D;
        else if (Boolean.TRUE.equals(obj))
            result = 1D;
        else if (obj instanceof Number)
            result = (Number) obj;
        else
            throw new IllegalArgumentException("Only numeric values may be used");

        return result;
    }

    private int getLabelValue(TabularInstance instance) {
        Object result = useDiscretizedValues ? instance.getDiscretizedLabel() : instance.getTransformedLabel();
        try {
            return toNumeric(result).intValue();
        } catch (IllegalArgumentException e) {
            // Is this good? For label try to use discretized instead
            if (!useDiscretizedValues)
                return toNumeric(instance.getDiscretizedLabel()).intValue();
            throw e;
        }
    }

    private Number[] getInstance(TabularInstance instance) {
        Object[] result = (useDiscretizedValues) ? instance.getInstance() : instance.getTransformedInstance();
        return Stream.of(result).map(AbstractTabularSmileClassifier::toNumeric).toArray(Number[]::new);
    }

    /**
     * Instantiates and fits new Random forest classifier using the tabular data
     *
     * @param trainingSet the set to train the model on
     */
    public void fit(TabularInstance[] trainingSet) {
        double[][] doubleTrainingSet = new double[trainingSet.length][];
        for (int i = 0; i < trainingSet.length; i++) {
            final Number[] column = getInstance(trainingSet[i]);
            double[] doubleColumn = new double[column.length];
            for (int j = 0; j < column.length; j++) {
                doubleColumn[j] = column[j].doubleValue();
            }
            doubleTrainingSet[i] = doubleColumn;
        }
        int[] labels = Stream.of(trainingSet).mapToInt(this::getLabelValue).toArray();

        this.classifier = fit(doubleTrainingSet, labels);
    }

    protected abstract SoftClassifier<double[]> fit(double[][] trainingSet, int[] labels);

    @Override
    public Integer apply(TabularInstance instance) {
        if (classifier == null)
            throw new IllegalStateException("The model must be fit in order to be used.");

        final double[] doubleColumn = new double[getInstance(instance).length];
        for (int j = 0; j < doubleColumn.length; j++)
            doubleColumn[j] = getInstance(instance)[j].doubleValue();

        return classifier.predict(doubleColumn);
    }
}

public class ModLoader implements IModLoader {
	/**
	 * Instance of current Mod Loader.
	 */
	public static final IModLoader INSTANCE = new ModLoader();

	/**
	 * A set of JAR files found in mods folder. NOTE: They don't need to be all
	 * mods.
	 */
	private Set<File> jarFiles = new HashSet<>();
	/**
	 * Holds an information about mods core classes. Classes which implements
	 * {@link IMod}.
	 */
	private Set<Class<?>> modCoreClasses = new HashSet<>();
	/**
	 * Holds an information about currently loaded mods.
	 */
	private Set<IMod> mods = new HashSet<>();

	private ModLoader() {
		Logger.info("Stating ModLoader...");

		Logger.info("Scanning for mod files...");
		this.scanForModFiles();

		Logger.info("Scanning JARs...");
		this.scanJars();

		Logger.info("Loading mods...");
		this.loadMods();

		Logger.info("Starting mods initialization...");
		this.runPreInitialization();
	}

	public void scanForModFiles() {
		Path modsFolder = Paths.get(FileUtils.MODS_DIR);
		try (DirectoryStream<Path> stream = Files.newDirectoryStream(modsFolder)) {
			for (Path file : stream) {
				File modFile = file.toFile();
				String fullName = modFile.getName();
				if (fullName.endsWith(".jar") || fullName.endsWith(".zip")) {
					jarFiles.add(modFile);
					Logger.info("Found JAR file: " + fullName);
				}
			}
		} catch (Exception x) {
			System.err.println(x);
		}
		Logger.info("Found: " + this.jarFiles.size() + " JAR files.");
	}

	public void scanJars() {
		try {
			for (File file : this.jarFiles) {
				JarFile jarFile = new JarFile(file);
				Collection<JarEntry> entries = this.getJarEntries(jarFile);
				URLClassLoader urlClassLoader = this.getUrlClassLoader(file);

				for (JarEntry entry : entries) {
					Class<?> modClass = this.loadClass(urlClassLoader, entry);

					if (modClass == null) {
						continue;
					}

					if (IMod.class.isAssignableFrom(modClass) && !Modifier.isAbstract(modClass.getModifiers())) {
						this.modCoreClasses.add(modClass);
						Logger.info("Found IMod class: " + modClass.getName());
					}
				}
			}
		} catch (Exception ex) {
			Logger.error(ex);
		}

		Logger.info("Total found IMod classes: " + this.modCoreClasses.size());
	}

	public void loadMods() {
		try {
			Logger.info("Searching for mods...");
			for (Class<?> modClass : this.modCoreClasses) {
				IMod modCoreClass = (IMod) modClass.newInstance();
				this.mods.add(modCoreClass);
				Logger.info("Found mod: " + modCoreClass.getModName());
			}
		} catch (Exception ex) {
			Logger.error(ex);
		}
	}

	public void runPreInitialization() {
		Logger.info("Entering PreInitialization stage...");
		for (IMod mod : this.mods) {
			Logger.info("Loading mod: " + mod.getModName());
			PreInitializationEvent event = new PreInitializationEvent();
			mod.preInit(event);
		}
	}

	public void runInitialization() {
		Logger.info("Entering Initialization stage...");
		for (IMod mod : this.mods) {
			Logger.info("Loading mod: " + mod.getModName());
			InitializationEvent event = new InitializationEvent();
			mod.init(event);
		}
	}

	public void runPostInitialization() {
		Logger.info("Entering PostInitialization stage...");
		for (IMod mod : this.mods) {
			Logger.info("Loading mod: " + mod.getModName());
			PostInitializationEvent event = new PostInitializationEvent();
			mod.postInit(event);
		}
	}

	public void runPostLoadSession(Object session) {
		Logger.info("Entering PostLoadSession stage...");
		for (IMod mod : this.mods) {
			Logger.info("Loading mod: " + mod.getModName());
			PostLoadSessionEvent event = new PostLoadSessionEvent(session);
			mod.postLoadSession(event);
		}
	}

	public Collection<JarEntry> getJarEntries(JarFile jarFile) {
		Collection<JarEntry> jarEntries = new HashSet<>();
		Enumeration<JarEntry> entries = jarFile.entries();

		while (entries.hasMoreElements()) {
			JarEntry entry = entries.nextElement();
			jarEntries.add(entry);
		}

		return jarEntries;
	}

	public URLClassLoader getUrlClassLoader(File file) throws MalformedURLException {
		URL[] urls = { new URL("jar:file:" + file.getAbsolutePath() + "!/") };
		URLClassLoader urlClassLoader = URLClassLoader.newInstance(urls);
		return urlClassLoader;
	}

	public Class<?> loadClass(URLClassLoader urlClassLoader, JarEntry entry) throws ClassNotFoundException {
		if (!entry.getName().endsWith(".class")) {
			return null;
		}

		String className = entry.getName().substring(0, entry.getName().length() - 6);
		className = className.replace('/', '.');
		Class<?> clazz = urlClassLoader.loadClass(className);
		return clazz;
	}
}

