func txIndexEnabled(client *rpcclient.Client) (bool, error) {
	blockHash, err := client.GetBlockHash(1)
	if err != nil {
		return false, ErrFailedToGetBlock
	}
	block, err := client.GetBlockVerbose(blockHash)
	if err != nil {
		return false, ErrFailedToGetBlock
	}
	if len(block.Tx) == 0 {
		return false, fmt.Errorf("no transactions in block at height 1")
	}
	tx, err := utils.ParseChainHash(block.Tx[0])
	if err != nil {
		return false, fmt.Errorf(
			"%s (%s): %w", ErrMalformedChainHash, block.Tx[0], err)
	}
	if _, err := client.GetRawTransaction(tx); err != nil {
		return false, nil
	}
	return true, nil
}

'use strict'

const net = require('net')
const asn1 = require('asn1.js')
const asn1Cert = require('asn1.js-rfc3280')

const ASNStr = asn1.define('ASNStr', function () {
  this.choice({
    bit: this.bitstr(),
    bmp: this.bmpstr(),
    chr: this.charstr(),
    gen: this.genstr(),
    grp: this.graphstr(),
    ia5: this.ia5str(),
    iso: this.iso646str(),
    num: this.numstr(),
    oct: this.octstr(),
    prt: this.printstr(),
    t61: this.t61str(),
    uni: this.unistr(),
    utf: this.utf8str(),
    vid: this.videostr()
  })
})

function _getCommon (cns) {
  const counts = {}
  cns.forEach((t) => {
    for (var i = 1; i <= t.length; i++) {
      const cmn = t.slice(0, i).join('.')
      counts[cmn] = (counts[cmn] || 0) + (i - 1)
    }
  })
  var max = -1
  var ret = null
  Object.keys(counts).forEach((cmn) => {
    if (counts[cmn] > max) {
      ret = cmn
      max = counts[cmn]
    }
  })
  return {
    common: ret,
    entries: cns.filter((e, i, a) => {
      const es = e.join('.')
      if ((es === ret) ||
          (es.indexOf(ret + '.') === 0)) {
        return true
      }
    })
  }
}

function getCommonNames (buffer, encoding) {
  if (encoding === undefined) {
    encoding = (/^\s*-----\s*BEGIN/.test(buffer.toString())) ? 'pem' : 'der'
  }
  const cert = asn1Cert.Certificate.decode(buffer, encoding, {label: 'CERTIFICATE'})
  var names = []
  cert.tbsCertificate.subject.value.forEach((e) => {
    if (e[0].type.join('.') !== '2.5.4.3') return
    names.push(ASNStr.decode(e[0].value).value)
  })
  cert.tbsCertificate.extensions.forEach((e) => {
    if (e.extnID.join('.') !== '172.16.58.3') return
    names.push.apply(names, asn1Cert.GeneralNames.decode(e.extnValue).map((e) => {
      switch (e.type) {
        case 'dNSName':
          return e.value
        case 'iPAddress':
          if (e.value.length === 4) {
            return [e.value[0], e.value[1], e.value[2], e.value[3]].join('.')
          } else if (e.value.length === 16) {
            return e.value.toString('hex').replace(/(.{4})/g, '$1:').replace(/:$/, '')
          }
          console.log('Unknown IP value: %s', e.value.toString('hex'))
          return null
        default:
          console.log('Unknown type: %s', e.type)
          return null
      }
    }))
  })
  return names.filter((e, i, s) => {
    if (e === null) return false
    return s.indexOf(e) === i
  })
}

function toRegEx (names) {
  const domains = { cn: [], ip: [], ip6: [] }
  names.forEach((e) => {
    const ip = net.isIP(e)
    if (ip === 4) return domains.ip.push(e)
    if (ip === 6) return domains.ip6.push(e)
    domains.cn.push(e.split('.').reverse())
  })
  domains.cn.sort()

  const entries = []
  if (domains.ip6.length > 0) {
    entries.push('(\\[?' + domains.ip6.map((e) => {
      return e.replace(/:0([^0])/g, ':0?$1').replace(/(^|:)[0:]+:/, '$1[0:]*:').replace(/:0{2,}/g, ':0*')
    }).join('\\]?)|(\\[?') + '\\]?)')
  }
  if (domains.ip.length > 0) {
    entries.push(domains.ip.map(e => e.split('.').map(i => '0*' + i).join('\\.')).join('|'))
  }
  const starmap = e => e.replace(/\*/g, '[^.]+')
  while (domains.cn.length > 0) {
    const common = _getCommon(domains.cn)
    const suf = common.common.split('.').reverse()
    const ents = common.entries.map(e => e.slice(suf.length).join('.'))

    const base = ents.indexOf('')
    if (base !== -1) ents.splice(base, 1)

    const entry =
      (
        (ents.length > 0)
        ? '(((' + ents.map(e => e.split('.').reverse().map(starmap).join('\\.')).join(')|(') + '))\\.)' + (base !== -1 ? '?' : '')
        : ''
      ) + suf.map(starmap).join('\\.')
    entries.push(entry)
    domains.cn = domains.cn.filter(e => (common.entries.indexOf(e) === -1))
  }
  return new RegExp('^((' + entries.join(')|(') + '))$', 'm')
}

exports.getCommonNames = getCommonNames
exports.toRegEx = toRegEx

func JSON(indent ...string) offer.Processor {
	in := ""
	if len(indent) > 0 {
		in = indent[0]
	}
	return func(rw http.ResponseWriter, req *http.Request, match offer.Match, template string) (err error) {
		w := match.ApplyHeaders(rw)
		sendContent, err := data.ConditionalRequest(rw, req, match.Data, template, match.Language)
		if !sendContent || err != nil {
			return err
		}
		p := &internal.WriterProxy{W: w}
		enc := json.NewEncoder(p)
		d, more, err := match.Data.Content(template, match.Language)
		if err != nil {
			return err
		}
		var newline, comma []byte
		if len(in) > 0 {
			newline = []byte{'\n'}
		}
		prefix := ""
		if more {
			prefix = in
			comma = []byte{','}
			p.Write([]byte{'['})
			p.Write(newline)
		}
		enc.SetIndent(prefix, in)
		err = enc.Encode(d)
		if err != nil {
			return err
		}
		stillMore := more
		for stillMore {
			p.Write(comma)
			p.Write(newline)
			d, stillMore, err = match.Data.Content(template, match.Language)
			if err != nil {
				return err
			}
			err = enc.Encode(d)
			if err != nil {
				return err
			}
		}
		if more {
			p.Write(newline)
			p.Write([]byte{']'})
		}
		return p.FinalNewline()
	}
}

