import junit.framework.Assert;

public abstract class TestThread extends Thread {
	private String error;

	public TestThread(String name) {
		super(name);
	}

	public void setError(String error) {
		this.error = error;
	}

	@Override
	public void run() {
		try {
			testableRun();
		} catch (Throwable e) {
			setError(e.getMessage());
		}
	}

	public abstract void testableRun() throws Throwable;

	public void assertThread() {
		if (error != null) Assert.fail(error);
	}

	public abstract T getResult();

}

int
_PyTuple_Resize(PyObject **pv, int newsize, int last_is_sticky)
{
	register PyTupleObject *v;
	register PyTupleObject *sv;
	int i;
	int sizediff;
	v = (PyTupleObject *) *pv;
	if (v == NULL || !PyTuple_Check(v) || v->ob_refcnt != 1 ||
             last_is_sticky) {
		*pv = 0;
		Py_XDECREF(v);
		PyErr_BadInternalCall();
		return -1;
	}
	sizediff = newsize - v->ob_size;
	if (sizediff == 0)
		return 0;
#ifdef Py_REF_DEBUG
	--_Py_RefTotal;
#endif
	_Py_ForgetReference((PyObject *) v);
	for (i = newsize; i < v->ob_size; i++) {
		Py_XDECREF(v->ob_item[i]);
		v->ob_item[i] = NULL;
	}
	PyObject_GC_Fini(v);
	v = (PyTupleObject *) PyObject_AS_GC(v);
	sv = (PyTupleObject *) PyObject_REALLOC((char *)v,
						sizeof(PyTupleObject)
						+ PyGC_HEAD_SIZE
						+ newsize * sizeof(PyObject *));
	if (sv == NULL) {
		*pv = NULL;
		PyObject_DEL(v);
		PyErr_NoMemory();
		return -1;
	}
	sv = (PyTupleObject *) PyObject_FROM_GC(sv);
	_Py_NewReference((PyObject *) sv);
	for (i = sv->ob_size; i < newsize; i++)
		sv->ob_item[i] = NULL;
	sv->ob_size = newsize;
	*pv = (PyObject *) sv;
	PyObject_GC_Init(sv);
	return 0;
}

public static DccdTreeRingData load(File file, String formatString) throws TreeRingDataFileServiceException {
		DccdTreeRingData data = new DccdTreeRingData();
		data.setFileName(file.getName()); 
		AbstractDendroFileReader reader = TridasIO.getFileReader(formatString);
	    try
		{
	    	String fileName = file.getName();
	    	String filePath = file.getParent();
	    	logger.debug("Start loading file: " + fileName + " from " + filePath );
	    	reader.loadFile(filePath, fileName);
	    	TridasProject[] projects = reader.getProjects();
	    	if(projects.length == 0)
	    	{
	    		throw new TreeRingDataFileServiceException("Conversion from file did not produce project data");
	    	}
	    	else if (projects.length > 1)
	    	{
	    		logger.warn("Conversion of the file: " + fileName + 
	    				"produced " + projects.length +
	    				" projects, taking the first and ignoring the rest");
	    	}
		    TridasProject project = projects[0];
		    data.setTridasProject(project);
		}
		catch (IOException e)
		{
			throw new TreeRingDataFileServiceException(e);
		}
		catch (InvalidDendroFileException e)
		{
		   ConversionWarning[] warnings = reader.getWarnings(); 
		   for(ConversionWarning warning : warnings)
		   {
			   logger.debug("warning: " + warning.getMessage());
		   }
			throw new TreeRingDataFileServiceException(e);
		}
		return data;
	}

public boolean checkMIME() {
        String msg = getText();
        String boundary;
        int contentsLoc = msg.indexOf("Content-Type: ");
        if (contentsLoc == -1) {
            return true;
        }
        StringSplitter header = new StringSplitter(msg.substring(0, body), "newline");
        String contents = getHeaderField(header, "Content-Type: ");
        int bound = contents.indexOf("boundary=");
        if (bound == -1) {
            return true;
        }
        if (contents.charAt(bound + 9) == '"') {
            contentsLoc += bound + 10;
            boundary = contents.substring(bound + 10, contents.length() - 1);
        } else {
            contentsLoc += bound + 9;
            boundary = contents.substring(bound + 9);
        }
        return (goodMSection(msg, contentsLoc + boundary.length(), boundary) != -1);
    }

TEST_F(GranularityStrategyTest, DirectionSwitchSideWordGranularityThenShrink) {
  dummyPageHolder().frame().settings()->setDefaultFontSize(12);
  String str = "ab cd efghijkl mnopqr iiin, abc";
  Text* text = document().createTextNode(str);
  document().body()->appendChild(text);
  document().updateStyleAndLayout();
  dummyPageHolder().frame().settings()->setSelectionStrategy(
      SelectionStrategy::Direction);
  parseText(text);
  selection().setSelection(
      SelectionInDOMTree::Builder()
          .setBaseAndExtent(Position(text, 18), Position(text, 21))
          .build());
  EXPECT_EQ_SELECTED_TEXT("pqr");
  selection().moveRangeSelectionExtent(m_wordMiddles[4]);
  EXPECT_EQ_SELECTED_TEXT("pqr iiin");
  int offset = m_letterPos[26].x() - m_wordMiddles[4].x();
  IntPoint p =
      IntPoint(m_wordMiddles[2].x() - offset - 1, m_wordMiddles[2].y());
  selection().moveRangeSelectionExtent(p);
  EXPECT_EQ_SELECTED_TEXT("efghijkl mno");
  p.move(m_letterPos[7].x() - m_letterPos[6].x(), 0);
  selection().moveRangeSelectionExtent(p);
  EXPECT_EQ_SELECTED_TEXT("fghijkl mno");
}

