def split_coins(n):
    coins = [2**i for i in range(1, n//2 + 1)]
    coins.sort()
    current_sum = sum(coins)
    current_sum -= coins[-1]

    for i in range(1, len(coins) - n//2):
        if current_sum == sum(coins[:n//2]) + sum(coins[-n//2 + 1:]):
            break
        current_sum -= coins[i]

    return abs(sum(coins[:n//2]) - sum(coins[-n//2 + 1:]))

