from abc import ABC, abstractmethod
from scipy.optimize import minimize

class AbstractPhase(ABC):
    @abstractmethod
    def run(self, **kwargs):
        pass

    @abstractmethod
    def make_result(self, **kwargs):
        pass

    @abstractmethod
    def phase_properties(self, **kwargs):
        pass

class NonLinearOptimizationPhase(AbstractPhase):
    def run(self, objective_function, initial_guess, bounds=None, **kwargs):
        # Use BFGS method for optimization
        result = minimize(objective_function, initial_guess, method='BFGS', bounds=bounds)
        return result

    def make_result(self, result, **kwargs):
        # Assuming result is a scipy OptimizeResult object
        return ModelResult(result.x)

    def phase_properties(self, objective_function=None, **kwargs):
        if objective_function is not None:
            return {"method": "BFGS", "objective_function": objective_function.__name__}
        else:
            return {"method": "BFGS"}

class ModelResult:
    def __init__(self, solution):
        self.solution = solution

    def __str__(self):
        return str(self.solution)

import argparse
