import static org.junit.Assert.assertEquals;

import java.util.concurrent.TimeUnit;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class IntervalCounterTest {

    @Before
    public void setUp() throws Exception {
    }

    @After
    public void tearDown() throws Exception {
    }

    @Test
    public void shouldWork() throws InterruptedException {
        IntervalCounter counter = new IntervalCounter(10, TimeUnit.MILLISECONDS);
        assertEquals(0, counter.get());
        assertEquals(1, counter.incrementAndGet());
        assertEquals(2, counter.incrementAndGet());
        assertEquals(2, counter.get());
        Thread.sleep(20);
        assertEquals(0, counter.get());
        assertEquals(1, counter.incrementAndGet());
        Thread.sleep(20);
        assertEquals(11, counter.incrementAndGet(11));
        assertEquals(11, counter.get());
    }

}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SocialPlatforms;
using System.Collections.Generic;
using System.Linq;
using Azure.Functions.Unity;
using TSTableView;

public class LeaderboardController : MonoBehaviour, ITableViewDataSource
{
    // Azure Functions client
    private AzureFunctionClient _azureFunctionClient;

    // Leaderboard table view
    public TSTableView leaderboardTableView;

    // Leaderboard data
    private List<LeaderboardEntry> _leaderboardData;

    // Authentication providers
    private SocialPlatform[] _authProviders = new SocialPlatform[] { Facebook, Twitter, Google, MicrosoftAccount };

    // Authentication state
    private bool _isAuthenticated = false;

    private void Start()
    {
        // Initialize Azure Functions client
        _azureFunctionClient = new AzureFunctionClient();

        // Initialize leaderboard table view
        leaderboardTableView.DataSource = this;

        // Load leaderboard data
        LoadLeaderboardData();
    }

    // Display leaderboard
    public void ShowLeaderboard()
    {
        leaderboardTableView.gameObject.SetActive(true);
    }

    // Hide leaderboard
    public void HideLeaderboard()
    {
        leaderboardTableView.gameObject.SetActive(false);
    }

    // Load leaderboard data
    private void LoadLeaderboardData()
    {
        // Check if user is authenticated
        if (!_isAuthenticated)
        {
            // Authenticate user
            AuthenticateUser();
            return;
        }

        // Call Azure Function to load leaderboard data
        _azureFunctionClient.Invoke("GetLeaderboard", (response) =>
        {
            // Parse leaderboard data
            _leaderboardData = JsonConvert.DeserializeObject<List<LeaderboardEntry>>(response);

            // Reload leaderboard table view
            leaderboardTableView.ReloadData();
        }, (error) =>
        {
            // Handle error
            Debug.LogError("Error loading leaderboard data: " + error.Message);
        });
    }

    // Submit new score
    public void SubmitScore(int score)
    {
        // Check if user is authenticated
        if (!_isAuthenticated)
        {
            // Authenticate user
            AuthenticateUser();
            return;
        }

        // Call Azure Function to submit new score
        _azureFunctionClient.Invoke("SubmitScore", new { score = score }, (response) =>
        {
            // Reload leaderboard data
            LoadLeaderboardData();
        }, (error) =>
        {
            // Handle error
            Debug.LogError("Error submitting score: " + error.Message);
        });
    }

    // Authenticate user
    private void AuthenticateUser()
    {
        // Loop through authentication providers
        foreach (SocialPlatform authProvider in _authProviders)
        {
            // Check if user is authenticated with provider
            if (authProvider.localUser.authenticated)
            {
                // Get user ID and token
                string userId = authProvider.localUser.id;
                string token = authProvider.localUser.accessToken;

                // Call Azure Function to authenticate user
                _azureFunctionClient.Invoke("AuthenticateUser", new { userId = userId, token = token }, (response) =>
                {
                    // Set authentication state
                    _isAuthenticated = true;

                    // Load leaderboard data
                    LoadLeaderboardData();
                }, (error) =>
                {
                    // Handle error
                    Debug.LogError("Error authenticating user: " + error.Message);
                });
                return;
            }
        }
    }

    // ITableViewDataSource implementation
    public int GetNumberOfRowsInSection(int section)
    {
        return _leaderboardData.Count;
    }

    public UITableViewCell GetCellForRow(int row)
    {
        // Create leaderboard entry cell
        LeaderboardEntryCell cell = leaderboardTableView.DequeueReusableCell("LeaderboardEntryCell") as LeaderboardEntryCell;

        // Set leaderboard entry data
        cell.SetData(_leaderboardData[row]);

        return cell;
    }
}

// Leaderboard entry data model
[System.Serializable]
public class LeaderboardEntry
{
    public string Name { get; set; }
    public int Score { get; set; }
    public int Rank { get; set; }
}

// Leaderboard entry cell
public class LeaderboardEntryCell : UITableViewCell
{
    // UI components
    public Text nameText;
    public Text scoreText;
    public Text rankText;

    // Set leaderboard entry data
    public void SetData(LeaderboardEntry data)
    {
        nameText.text = data.Name;
        scoreText.text = data.Score.ToString();
        rankText.text = data.Rank.ToString();
    }
}

public class DB2ImportAllTableWithSchemaManualTest extends ImportJobTestCase {

  public static final Log LOG = LogFactory.getLog(
		  DB2ImportAllTableWithSchemaManualTest.class.getName());

  static final String HOST_URL = System.getProperty(
          "sqoop.test.db2.connectstring.host_url",
          "jdbc:db2://9.30.245.234:60000");

  static final String DATABASE_NAME = System.getProperty(
          "sqoop.test.db2.connectstring.database",
          "TESTDB");
  static final String DATABASE_USER = System.getProperty(
          "sqoop.test.db2.connectstring.username",
          "DB2FENC1");
  static final String DATABASE_PASSWORD = System.getProperty(
          "sqoop.test.db2.connectstring.password",
          "DB2FENC1");

  static final String TABLE_NAME = "TEST.COMPANY";
  static final String TABLE_SCHEMA = "TEST";
  static final String CONNECT_STRING = HOST_URL
              + "/" + DATABASE_NAME;
  static String ExpectedResults =
      "1,doc1";


  String [] extraArgs = { "--",
    "--schema", TABLE_SCHEMA,
  };

  static {
    LOG.info("Using DB2 CONNECT_STRING HOST_URL is : "+HOST_URL);
    LOG.info("Using DB2 CONNECT_STRING: " + CONNECT_STRING);
  }

  // instance variables populated during setUp, used during tests
  private Db2Manager manager;

  protected String getTableName() {
    return  TABLE_NAME;
  }


  @Before
  public void setUp() {
    super.setUp();

    SqoopOptions options = new SqoopOptions(CONNECT_STRING, getTableName());
    options.setUsername(DATABASE_USER);
    options.setPassword(DATABASE_PASSWORD);

    manager = new Db2Manager(options);

    // Drop the existing table, if there is one.
    Connection conn = null;
    Statement stmt = null;
    try {
      conn = manager.getConnection();
      stmt = conn.createStatement();
      stmt.execute("DROP TABLE " + getTableName());
    } catch (SQLException sqlE) {
        LoggingUtils.logAll(LOG, "Table was not dropped: ", sqlE);
      } finally {
          try {
            if (null != stmt) {
            stmt.close();
            }
          } catch (Exception ex) {
              LOG.warn("Exception while closing stmt", ex);
            }
        }

    // Create and populate table
    try {
      conn = manager.getConnection();
      conn.setAutoCommit(false);
      stmt = conn.createStatement();

      // create the database table and populate it with data.
      stmt.executeUpdate("CREATE TABLE " + getTableName() + " ("
          + "ID int, "
          + "DOCNAME VARCHAR(20))");

      stmt.executeUpdate("INSERT INTO " + getTableName() + " VALUES("
          + "1,'doc1' "
          + " )");
      conn.commit();
    } catch (SQLException sqlE) {
        LoggingUtils.logAll(LOG, "Encountered SQL Exception: ", sqlE);
      } finally {
          try {
            if (null != stmt) {
            stmt.close();
            }
          } catch (Exception ex) {
              LOG.warn("Exception while closing connection/stmt", ex);
            }
        }
  }

  @After
  public void tearDown() {
    super.tearDown();
    try {
      manager.close();
    } catch (SQLException sqlE) {
        LoggingUtils.logAll(LOG, "Got SQLException: ", sqlE);
      }
  }

  @Test
  public void testDb2Import() throws IOException {

    runDb2Test(ExpectedResults);

  }

  private String [] getArgv() {
    ArrayList<String> args = new ArrayList<String>();

    CommonArgs.addHadoopFlags(args);
    args.add("--connect");
    args.add(CONNECT_STRING);
    args.add("--username");
    args.add(DATABASE_USER);
    args.add("--password");
    args.add(DATABASE_PASSWORD);
    args.add("--warehouse-dir");
    args.add(getWarehouseDir());

    args.add("--m");
    args.add("1");

    for (String arg : extraArgs) {
      args.add(arg);
    }

    return args.toArray(new String[0]);
  }

  private void runDb2Test(String expectedResults) throws IOException {

    Path warehousePath = new Path(this.getWarehouseDir());
    Path tablePath = new Path(warehousePath, getTableName());
    Path filePath = new Path(tablePath, "part-m-00000");

    File tableFile = new File(getTableName().toString());
    if (tableFile.exists() && tableFile.isDirectory()) {
      // remove the directory before running the import.
      FileListing.recursiveDeleteDir(tableFile);
    }

    String [] argv = getArgv();
    try {
      runImportAll(argv);
    } catch (IOException ioe) {
        LOG.error("Got IOException during import: " + ioe.getMessage());
      }

    File f = new File(filePath.toString());
    assertTrue("Could not find imported data file", f.exists());
    BufferedReader r = null;
    try {
      // Read through the file and make sure it's all there.
      r = new BufferedReader(new InputStreamReader(new FileInputStream(f)));
      assertEquals(expectedResults, r.readLine());
    } catch (IOException ioe) {
        LOG.error("Got IOException verifying results: " + ioe.getMessage());
      } finally {
          IOUtils.closeStream(r);
        }
  }

  private void runImportAll(SqoopTool tool,String [] argv) throws IOException {
  // run the tool through the normal entry-point.
    int ret;
    try {
      Configuration conf = getConf();
      SqoopOptions opts = getSqoopOptions(conf);
      Sqoop sqoop = new Sqoop(tool, conf, opts);
      ret = Sqoop.runSqoop(sqoop, argv);
      //ret = tool.run(opts);
    } catch (Exception e) {
        LOG.error("Got exception running Sqoop: " + e.toString());
        ret = 1;
      }

  // expect a successful return.
    if (0 != ret) {
      throw new IOException("Failure during job; return status " + ret);
    }
  }

  /** run an import using the default ImportTool. */
  protected void runImportAll(String [] argv) throws IOException {
    runImportAll(new ImportAllTablesTool(), argv);
  }
}

