def test_basic_text():
    assert(str(Input('text')) == "<input type=\"text\" class=\"form-control\">

def test_unknown_inputtype():
    with pytest.raises(ValueError) as err:
        Input('abc')
    assert('abc' in str(err.value))

def test_inputtype_missing():
