        Input()

def test_readonly_placeholder():
    assert(str(Input('email', readonly=True, placeholder="abc")) == "<input type=\"email\" class=\"form-control\" placeholder=\"abc\" readonly>

def test_size_large():
    assert(str(Input('password', size="large")) == "<input type=\"password\" class=\"form-control input-lg\">

def test_size_small():
    assert(str(Input('color', size="small")) == "<input type=\"color\" class=\"form-control input-sm\">

def test_help_text():
