class BNode(object):
    def __init__(self, left, right, aggregate, minimize):
        self.left = left
        self.right = right
        self.aggregate = aggregate
        self.minimize = minimize

class BTree(object):
    def __init__(self):
        self.Deep = 0
        self.Nodes = []
    def Aggregate(self, aggregate):
        return [[element if self.Nodes[element].aggregate() == 1 else element for element in subnode] for subnode in aggregate]
    def Minimize(self, tree):
        for node in self.Nodes:
            if node.aggregate == 0:
                tmp = tree.GetNode(node.minimize[0])
                node.left, node.minimize = tmp.left, [tmp.left[0]]
            elif node.aggregate == 1:
                tmp = tree.GetNode(node.minimize[0])
                node.left, node.minimize = tmp.right, [tmp.right[0]]

