public final class EncryptionInfo {
  public enum Type {
    /** Encryption type was not specified, though data at rest remains encrypted. */
    ENCRYPTION_TYPE_UNSPECIFIED(
        com.google.bigtable.admin.v2.EncryptionInfo.EncryptionType.ENCRYPTION_TYPE_UNSPECIFIED),
    /**
     * The data backing this resource is encrypted at rest with a key that is fully managed by
     * Google. No key version or status will be populated. This is the default state.
     */
    GOOGLE_DEFAULT_ENCRYPTION(
        com.google.bigtable.admin.v2.EncryptionInfo.EncryptionType.GOOGLE_DEFAULT_ENCRYPTION),
    /**
     * The data backing this resource is encrypted at rest with a key that is managed by the
     * customer. The in-use version of the key and its status are populated for CMEK-protected
     * tables. CMEK-protected backups are pinned to the key version that was in use at the time the
     * backup was taken. This key version is populated but its status is not tracked and is reported
     * as `UNKNOWN`.
     */
    CUSTOMER_MANAGED_ENCRYPTION(
        com.google.bigtable.admin.v2.EncryptionInfo.EncryptionType.CUSTOMER_MANAGED_ENCRYPTION),
    /** Type not known by the client, please upgrade your client */
    UNRECOGNIZED(com.google.bigtable.admin.v2.EncryptionInfo.EncryptionType.UNRECOGNIZED);

    private final com.google.bigtable.admin.v2.EncryptionInfo.EncryptionType proto;

    Type(EncryptionType proto) {
      this.proto = proto;
    }

    /** Wraps the EncryptionInfo protobuf. */
    public static Type fromProto(com.google.bigtable.admin.v2.EncryptionInfo.EncryptionType proto) {
      for (Type type : values()) {
        if (Objects.equal(type.proto, proto)) {
          return type;
        }
      }
      return UNRECOGNIZED;
    }
  }

  private com.google.bigtable.admin.v2.EncryptionInfo proto;

  public static EncryptionInfo fromProto(com.google.bigtable.admin.v2.EncryptionInfo proto) {
    return new EncryptionInfo(proto);
  }

  private EncryptionInfo(com.google.bigtable.admin.v2.EncryptionInfo proto) {
    this.proto = proto;
  }

  public Type getType() {
    return EncryptionInfo.Type.fromProto(proto.getEncryptionType());
  }

  public String getKmsKeyVersion() {
    return proto.getKmsKeyVersion();
  }

  public Status getStatus() {
    return Status.fromProto(proto.getEncryptionStatus());
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    EncryptionInfo that = (EncryptionInfo) o;
    return Objects.equal(proto, that.proto);
  }

  @Override
  public int hashCode() {
    return Objects.hashCode(proto);
  }

  @Override
  public String toString() {
    return proto.toString();
  }
}

public class BRadioButton extends Widget
{
  private RadioButtonGroup group;

  static
  {
    WidgetEncoder.setPersistenceDelegate(BRadioButton.class, new EventSourceDelegate(new String [] {"group"}));
  }

  /**
   * Create a new BRadioButton with no label, which is initially deselected.
   *
   * @param group     the RadioButtonGroup this radio button is part of
   */

  public BRadioButton(RadioButtonGroup group)
  {
    this(null, false, group);
  }

  /**
   * Create a new BRadioButton.
   *
   * @param text     the text to display on the BRadioButton
   * @param state    the initial selection state of the BRadioButton
   * @param group    the RadioButtonGroup this radio button is part of
   */

  public BRadioButton(String text, boolean state, RadioButtonGroup group)
  {
    component = createComponent(text, state);
    getComponent().addActionListener(new ActionListener() {
      public void actionPerformed(ActionEvent ev)
      {
        dispatchEvent(new ValueChangedEvent(BRadioButton.this));
      }
    });
    this.group = group;
    group.add(this);
  }

  /**
   * Create the JRadioButton which serves as this Widget's Component.  This method is protected so that
   * subclasses can override it.
   *
   * @param text     the text to display on the BRadioButton
   * @param state    the initial selection state of the BRadioButton
   */

  protected JRadioButton createComponent(String text, boolean state)
  {
    return new JRadioButton(text, state);
  }

  public JRadioButton getComponent()
  {
    return (JRadioButton) component;
  }

  /**
   * Get the selection state of this radio button.
   */

  public boolean getState()
  {
    return getComponent().isSelected();
  }

  /**
   * Set the selection state of this radio button.  If you set the selection state to true,
   * the state of every other member of its RadioButtonGroup will be set to false.
   */

  public void setState(boolean selected)
  {
    if (selected)
      group.setSelection(this);
    else
      getComponent().setSelected(selected);
  }

  /**
   * Get the text which appears on this radio button.
   */

  public String getText()
  {
    return getComponent().getText();
  }

  /**
   * Set the text which appears on this radio button.
   */

  public void setText(String text)
  {
    getComponent().setText(text);
    invalidateSize();
  }

  /**
   * Get the RadioButtonGroup this button is part of.
   */

  public RadioButtonGroup getGroup()
  {
    return group;
  }

  /**
   * Set the RadioButtonGroup this button is part of.
   */

  public void setGroup(RadioButtonGroup newGroup)
  {
    for (int i = 0; i < group.getRadioButtonCount(); i++)
      if (group.getRadioButton(i) == this)
      {
        group.remove(i);
        break;
      }
    group = newGroup;
    group.add(this);
  }

  /**
   * Get the largest size at which this Widget can reasonably be drawn.  When a WidgetContainer lays out
   * its contents, it will attempt never to make this Widget larger than its maximum size.
   */

  public Dimension getMaximumSize()
  {
    return new Dimension(32767, 32767);
  }
}

def remove_loader(self, name):
        if name not in self.loaders:
            returnValue(False)
        to_unload = []
        loader = self.loaders[name]
        for plugin in self.plugin_objects.itervalues():
            if plugin._loader == loader.name:
                to_unload.append(plugin.info.name)
        del loader
        for plugin in to_unload:
            _ = yield self.unload_plugin(plugin)
        del self.loaders[name]
        returnValue(True)

