private static void validateDataStreamsStillReferenced(ClusterState state, String templateName, ComposableIndexTemplate newTemplate) {
        final Set<String> dataStreams = state.metadata().dataStreams().keySet();
        Function<Metadata, Set<String>> findUnreferencedDataStreams = meta -> {
            final Set<String> unreferenced = new HashSet<>();
            for (String dataStream : dataStreams) {
                final String matchingTemplate = findV2Template(meta, dataStream, false);
                if (matchingTemplate == null) {
                    unreferenced.add(dataStream);
                } else {
                    if (meta.templatesV2().get(matchingTemplate).getDataStreamTemplate() == null) {
                        unreferenced.add(dataStream);
                    }
                }
            }
            return unreferenced;
        };
        final Set<String> currentlyUnreferenced = findUnreferencedDataStreams.apply(state.metadata());
        final Metadata updatedMetadata = Metadata.builder(state.metadata()).put(templateName, newTemplate).build();
        final Set<String> newlyUnreferenced = findUnreferencedDataStreams.apply(updatedMetadata);
        if (newlyUnreferenced.size() > currentlyUnreferenced.size()) {
            throw new IllegalArgumentException(
                "composable template ["
                    + templateName
                    + "] with index patterns "
                    + newTemplate.indexPatterns()
                    + ", priority ["
                    + newTemplate.priority()
                    + "] "
                    + (newTemplate.getDataStreamTemplate() == null ? "and no data stream configuration " : "")
                    + "would cause data streams "
                    + newlyUnreferenced
                    + " to no longer match a data stream template"
            );
        }
    }

def clean_atx_header_text(text):
    md_link_rule = MarkdownLinkRule()
    md_attribute_syntax_rule = MarkdownAttributeSyntax()
    if md_attribute_syntax_rule.match(text):
        for r in md_attribute_syntax_rule.extract_data(text):
            text = text.replace(r["full"], "")
        text = text.strip()
    if md_link_rule.match(text):
        for r in md_link_rule.extract_data(text):
            text = text.replace(r["full"], r["text"])
        text = text.strip()
    return text

def sdf_to_nx(sdf, keep_hydrogen=False):
    if not isinstance(sdf, list):
        sdf = [sdf]
    output = []
    for sdf_ in sdf:
        g = nx.Graph()
        for atom in sdf_['atoms']:
            if atom['atomic_num'] > 1 or keep_hydrogen:
                g.add_node(atom['index'], **atom)
        for bond in sdf_['bonds']:
            start_atom_num = sdf_['atoms'][bond['start_atom']]['atomic_num']
            end_atom_num = sdf_['atoms'][bond['end_atom']]['atomic_num']
            if (start_atom_num > 1 and end_atom_num > 1) or keep_hydrogen:
                g.add_edge(bond['start_atom'], bond['end_atom'], **bond)
        output.append(g)
    if len(output) == 1:
        return output[0]
    else:
        return output

public static IEnumerable<SerializedProperty> EnumerateChildProperties(SerializedProperty parent)
        {
            var copy = parent.Copy();
            var depth = copy.depth + 1;
            while (copy.Next(true))
            {
                if (copy.depth == depth)
                    yield return copy;
            }
        }

