public void preCompileDeclarations() {
    // Temporarily ignore external methods during compilation
    boolean originalIgnoreExternalMethods = IgnoreExternalMethods.IGNORE_EXTERNAL_METHODS;
    IgnoreExternalMethods.IGNORE_EXTERNAL_METHODS = true;

    // Process BNF Grammar declarations
    List<BNFGrammar> bnfGrammarDeclarations = getBNFGrammarDeclarations();
    while (!bnfGrammarDeclarations.isEmpty()) {
        BNFGrammar declaration = bnfGrammarDeclarations.remove(0);
        try {
            compile(declaration);
        } catch (CompilationException e) {
            if (e.isUndefinedVariableError()) {
                // Move problematic item to the end of the list and retry
                bnfGrammarDeclarations.add(declaration);
            } else {
                throw e;
            }
        }
    }

    // Process declaration sections
    List<DeclarationSection> declarationSections = getDeclarationSections();
    while (!declarationSections.isEmpty()) {
        DeclarationSection section = declarationSections.remove(0);
        try {
            compile(section);
        } catch (CompilationException e) {
            if (e.isUndefinedVariableError()) {
                // Move problematic item to the end of the list and retry
                declarationSections.add(section);
            } else {
                throw e;
            }
        }
    }

    // Restore original ignore status of external methods
    IgnoreExternalMethods.IGNORE_EXTERNAL_METHODS = originalIgnoreExternalMethods;
}

