public interface ICollectionViewSourceDelegate
{
    void OnItemSelected(UICollectionView collectionView, NSIndexPath indexPath, object item);
}

public class CustomCollectionViewSource : UICollectionViewSource
{
    private readonly string _cellIdentifier;
    private readonly UICollectionView _collectionView;
    private bool _animateSelection;
    private List<object> _items;

    public event EventHandler<ItemSelectedEventArgs> ItemSelected;

    public CustomCollectionViewSource(UICollectionView collectionView, string cellIdentifier)
    {
        _collectionView = collectionView ?? throw new ArgumentNullException(nameof(collectionView));
        _cellIdentifier = cellIdentifier ?? throw new ArgumentNullException(nameof(cellIdentifier));
        _items = new List<object>();
    }

    public List<object> Items
    {
        get => _items;
        set
        {
            _items = value ?? new List<object>();
            _collectionView.ReloadData();
        }
    }

    public bool AnimateSelection
    {
        get => _animateSelection;
        set => _animateSelection = value;
    }

    public override nint NumberOfSections(UICollectionView collectionView)
    {
        return 1; // Single section by default
    }

    public override nint GetItemsCount(UICollectionView collectionView, nint section)
    {
        return _items?.Count ?? 0;
    }

    public override UICollectionViewCell GetCell(UICollectionView collectionView, NSIndexPath indexPath)
    {
        var cell = (UICollectionViewCell)collectionView.DequeueReusableCell(_cellIdentifier, indexPath);
        var item = _items[indexPath.Row];

        // Configure the cell with item data (assumes cell has a Configure method)
        if (cell is IConfigurableCell configurableCell)
        {
            configurableCell.Configure(item);
        }

        return cell;
    }

    public override void ItemSelected(UICollectionView collectionView, NSIndexPath indexPath)
    {
        var selectedItem = _items[indexPath.Row];

        if (_animateSelection)
        {
            UIView.Animate(0.2, () =>
            {
                var cell = collectionView.CellForItem(indexPath);
                cell.Transform = CGAffineTransform.MakeScale(0.9f, 0.9f);
            }, () =>
            {
                UIView.Animate(0.2, () =>
                {
                    var cell = collectionView.CellForItem(indexPath);
                    cell.Transform = CGAffineTransform.MakeIdentity();
                });
            });
        }

        ItemSelected?.Invoke(this, new ItemSelectedEventArgs(collectionView, indexPath, selectedItem));
    }
}

public class ItemSelectedEventArgs : EventArgs
{
    public UICollectionView CollectionView { get; }
    public NSIndexPath IndexPath { get; }
    public object SelectedItem { get; }

    public ItemSelectedEventArgs(UICollectionView collectionView, NSIndexPath indexPath, object selectedItem)
    {
        CollectionView = collectionView;
        IndexPath = indexPath;
        SelectedItem = selectedItem;
    }
}

public interface IConfigurableCell
{
    void Configure(object item);
}

