static kern_return_t
vfs_drt_get_cluster(void **cmapp, off_t *offsetp, u_int *lengthp)
{
	struct vfs_drt_clustermap *cmap;
	u_int64_t	offset;
	u_int		length;
	u_int32_t	j;
	int		index, i, fs, ls;
	if ((cmapp == NULL) || (*cmapp == NULL))
		return(KERN_FAILURE);
	cmap = *cmapp;
	for (offset = 0, j = 0; j < cmap->scm_modulus; offset += (DRT_BITVECTOR_PAGES * PAGE_SIZE), j++) {
	        index = DRT_HASH(cmap, offset);
	        if (DRT_HASH_VACANT(cmap, index) || (DRT_HASH_GET_COUNT(cmap, index) == 0))
			continue;
		fs = -1;
		for (i = 0; i < DRT_BITVECTOR_PAGES; i++) {
		        if (DRT_HASH_TEST_BIT(cmap, index, i)) {
			        fs = i;
				break;
			}
		}
		if (fs == -1) {
		        panic("vfs_drt: entry summary count > 0 but no bits set in map, cmap = %p, index = %d, count = %lld",
			      cmap, index, DRT_HASH_GET_COUNT(cmap, index));
		}
		for (ls = 0; i < DRT_BITVECTOR_PAGES; i++, ls++) {
			if (!DRT_HASH_TEST_BIT(cmap, index, i))
			        break;
		}
		offset = DRT_HASH_GET_ADDRESS(cmap, index) + (PAGE_SIZE * fs);
		length = ls * PAGE_SIZE;
		vfs_drt_do_mark_pages(cmapp, offset, length, NULL, 0);
		cmap->scm_lastclean = index;
		*offsetp = (off_t)offset;
		*lengthp = length;
		vfs_drt_trace(cmap, DRT_DEBUG_RETCLUSTER, (int)offset, (int)length, 0, 0);
		return(KERN_SUCCESS);
	}
	vfs_drt_trace(cmap, DRT_DEBUG_SCMDATA,
		      cmap->scm_modulus,
		      cmap->scm_buckets,
		      cmap->scm_lastclean,
		      cmap->scm_iskips);
	vfs_drt_free_map(cmap);
	*cmapp = NULL;
	return(KERN_FAILURE);
}

HRESULT UpdateSpatialAudioObject(IsacSpatialSourceInternal* source)
{
    ComPtr<ISpatialAudioObject> audioObject = source->GetSpatialAudioObject();
    RETURN_HR_IF_NULL(E_NOT_VALID_STATE, audioObject);
    BOOL isActive = FALSE;
    RETURN_IF_FAILED(audioObject->IsActive(&isActive));
    RETURN_HR_IF(E_NOT_VALID_STATE, !isActive);
    BYTE* buffer = nullptr;
    UINT32 byteCount = 0;
    RETURN_IF_FAILED(audioObject->GetBuffer(&buffer, &byteCount));
    if (source->AreEnoughSamplesBuffered(byteCount / sizeof(float)))
    {
        auto params = source->GetParameters();
        RETURN_IF_FAILED(audioObject->SetPosition(
            params.PrimaryArrivalDirection.x, params.PrimaryArrivalDirection.y, params.PrimaryArrivalDirection.z));
        RETURN_IF_FAILED(audioObject->SetVolume(DbToAmplitude(params.PrimaryArrivalDistancePowerDb)));
        source->ReadSamplesFromCircularBuffer(reinterpret_cast<float*>(buffer), byteCount / sizeof(float));
    }
    else
    {
        memset(buffer, 0, byteCount);
    }
    return S_OK;
}

