import java.util.List;

public class ElementManager {

    private DeleteListener deleteListener;

    public ElementManager(DeleteListener deleteListener) {
        this.deleteListener = deleteListener;
    }

    public void deleteElementAtIndex(List<?> elements, int index) {
        try {
            if (elements == null) {
                throw new IllegalArgumentException("Element list cannot be null");
            }
            if (index < 0 || index >= elements.size()) {
                throw new IndexOutOfBoundsException("Index " + index + " is out of bounds");
            }
            elements.remove(index);
            deleteListener.onDeleteUpdateSuccess();
        } catch (Exception e) {
            deleteListener.onDeleteUpdateFailure(e.getMessage());
        }
    }

    public interface DeleteListener {
        void onDeleteUpdateSuccess();
        void onDeleteUpdateFailure(String error);
    }
}

