void
USBRingBufWrite(tUSBRingBufObject *ptUSBRingBuf, const unsigned char *pucData,
                unsigned int ulLength)
{
    unsigned int ulTemp;

    //
    // Check the arguments.
    //
    ASSERT(ptUSBRingBuf != NULL);
    ASSERT(pucData != NULL);
    ASSERT(ulLength != 0);

    //
    // Verify that space is available in the buffer.
    //
    ASSERT(ulLength <= USBRingBufFree(ptUSBRingBuf));

    //
    // Write the data into the ring buffer.
    //
    for(ulTemp = 0; ulTemp < ulLength; ulTemp++)
    {
        USBRingBufWriteOne(ptUSBRingBuf, pucData[ulTemp]);
    }
}

def _delete_staging_masking_views(
            self, array, masking_view_list, os_host_name):
        delete_mv_list = list()
        safe_to_delete = False
        for masking_view_name in masking_view_list:
            if os_host_name in masking_view_name:
                safe_to_delete = True
            else:
                delete_mv_list.append(masking_view_name)
        if safe_to_delete:
            for delete_mv in delete_mv_list:
                self.rest.delete_masking_view(array, delete_mv)
                LOG.info("MIGRATE - Masking view %(delete_mv)s has been "
                         "successfully deleted.",
                         {'delete_mv': delete_mv})
        return safe_to_delete

def ppc(headline, capture, limit=10):
    if not capture:
        return headline
    result = headline + "\n"
    count = 1
    for p in capture:
        result.append(ppp("Packet #%s:" % count, p))
        count += 1
        if count >= limit:
            break
    if limit < len(capture):
        result.append(
            "Capture contains %s packets in total, of which %s were printed" %
            (len(capture), limit))

void Spinner::getSizes( float outSizes[SW_NumSubWidgets] ) const
	{
		outSizes[SW_Decrement] = m_arrowSize.x + m_arrowMargin * 2.0f;
		outSizes[SW_OptionLabel] = m_sizeOptionLabel;
		outSizes[SW_Increment] = m_arrowSize.x + m_arrowMargin * 2.0f;

		// For some unknown reason we have to sub two extra arrow margin from remainingSize
		if( m_label )
		{
			const float remainingSize =
				std::max( 0.0f, m_size.x - outSizes[SW_Decrement] - outSizes[SW_Increment] -
									outSizes[SW_OptionLabel] - m_arrowMargin * 2.0f );
			outSizes[SW_Label] = std::min( m_sizeLabel, remainingSize );
			outSizes[SW_Space] = remainingSize - outSizes[SW_Label];
		}
		else
		{
			const float remainingSize =
				std::max( 0.0f, m_size.x - outSizes[SW_Decrement] - outSizes[SW_Increment] -
									m_arrowMargin * 2.0f );

			outSizes[SW_OptionLabel] = std::max( outSizes[SW_OptionLabel], remainingSize );
			outSizes[SW_Label] = 0.0f;
			outSizes[SW_Space] = 0.0f;
		}
	}

public String updatePassword(PasswordResetRequest passwordResetRequest) {
        Optional<User> userOptional = userJpaRepository.findByEmail(passwordResetRequest.getEmail());
        if(userOptional.isPresent()){
            if(passwordResetRequest.getPassword().equals(passwordResetRequest.getPasswordVerify())){
                passwordResetRequest.setPassword(passwordEncoder.encode(passwordResetRequest.getPassword()));
                User user = userMapper.toEntity(userOptional.get().getId(), userOptional.get().getUsername(), userOptional.get().getIsEnable(), userOptional.get().getRoles(), passwordResetRequest);
                userJpaRepository.save(user);
                passwordResetJpaRepository.deleteByEmail(passwordResetRequest.getEmail());
                return "Password reset successfully";
            }else{
                throw new ApiConflict("Password doesn't match");
            }
        }else{
            throw new ApiNotFound("User no found with email: "+passwordResetRequest.getEmail());
        }
    }

