namespace LineIntersectionTests
{
    public class Point
    {
        public double X { get; set; }
        public double Y { get; set; }

        public Point(double x, double y)
        {
            X = x;
            Y = y;
        }

        public override string ToString()
        {
            return $"({X}, {Y})";
        }
    }

    public class Line
    {
        public Point P1 { get; set; }
        public Point P2 { get; set; }

        public Line(Point p1, Point p2)
        {
            P1 = p1;
            P2 = p2;
        }
    }

    public static class LineIntersection
    {
        public static Point? Find(Line line1, Line line2)
        {
            double x1 = line1.P1.X;
            double y1 = line1.P1.Y;
            double x2 = line1.P2.X;
            double y2 = line1.P2.Y;
            double x3 = line2.P1.X;
            double y3 = line2.P1.Y;
            double x4 = line2.P2.X;
            double y4 = line2.P2.Y;

            double denominator = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);

            if (denominator == 0)
            {
                return null; // Lines are parallel
            }

            double numeratorX = (x1 * y2 - y1 * x2) * (x3 - x4) - (x1 - x2) * (x3 * y4 - y3 * x4);
            double numeratorY = (x1 * y2 - y1 * x2) * (y3 - y4) - (y1 - y2) * (x3 * y4 - y3 * x4);

            double x = numeratorX / denominator;
            double y = numeratorY / denominator;

            return new Point(x, y);
        }
    }

    public class PointComparer
    {
        private readonly double tolerance;

        public PointComparer(double tolerance = 1e-6)
        {
            this.tolerance = tolerance;
        }

        public bool Equals(Point p1, Point p2)
        {
            if (p1 == null && p2 == null) return true;
            if (p1 == null || p2 == null) return false;

            return Math.Abs(p1.X - p2.X) < tolerance && Math.Abs(p1.Y - p2.Y) < tolerance;
        }

        public int GetHashCode(Point p)
        {
            if (p == null) return 0;
            return p.X.GetHashCode() ^ p.Y.GetHashCode();
        }
    }

