def rescale(img, scale, interpolation_order=3, anti_aliasing=False, channel_pos="first"):
    if channel_pos == "first":
        input_shape = img.shape[1:]
    else:
        input_shape = img.shape[:2]
    size = np.round(scale * input_shape)
    out = resize(img, size, interpolation_order=interpolation_order, anti_aliasing=anti_aliasing, channel_pos=channel_pos)
    return out

public class Observable : INotifyPropertyChanged
	{
		public event PropertyChangedEventHandler PropertyChanged;
		protected bool SetValue<T>(ref T storage, T value, [CallerMemberName]string name = null)
		{
			if (Equals(storage, value))
			{
				return false;
			}
			storage = value;
			OnPropertyChanged(name);
			return true;
		}
		protected virtual void OnPropertyChanged(string name)
		{
			PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
		}
	}

static inline uint64_t
mrvl_desc_to_ol_flags(struct pp2_ppio_desc *desc)
{
	uint64_t flags;
	enum pp2_inq_desc_status status;
	status = pp2_ppio_inq_desc_get_l3_pkt_error(desc);
	if (unlikely(status != PP2_DESC_ERR_OK))
		flags = PKT_RX_IP_CKSUM_BAD;
	else
		flags = PKT_RX_IP_CKSUM_GOOD;
	status = pp2_ppio_inq_desc_get_l4_pkt_error(desc);
	if (unlikely(status != PP2_DESC_ERR_OK))
		flags |= PKT_RX_L4_CKSUM_BAD;
	else
		flags |= PKT_RX_L4_CKSUM_GOOD;
	return flags;
}

void DayTable::Summary::RemoveDayRows(WallTime timestamp) {
  DCHECK_EQ(timestamp, int(timestamp));
  SummaryRow start_row;
  start_row.set_day_timestamp(timestamp);
  start_row.set_identifier(0);
  SummaryRow end_row;
  end_row.set_day_timestamp(timestamp - kDayInSeconds);
  end_row.set_identifier(0);
  SummaryRowArray::pointer_iterator start_it =
      std::lower_bound(summary_.mutable_rows()->pointer_begin(),
                       summary_.mutable_rows()->pointer_end(),
                       &start_row, SummaryRowGreaterThan());
  SummaryRowArray::pointer_iterator end_it =
      std::lower_bound(summary_.mutable_rows()->pointer_begin(),
                       summary_.mutable_rows()->pointer_end(),
                       &end_row, SummaryRowGreaterThan());
  const int count = end_it - start_it;
  for (SummaryRowArray::pointer_iterator iter = start_it; iter != end_it; ++iter) {
    // Set timestamp to -1 so removed rows sort to end.
    (*iter)->set_day_timestamp(-1);
  }
  // Sort removed values to end and truncate.
  std::sort(summary_.mutable_rows()->pointer_begin(),
            summary_.mutable_rows()->pointer_end(),
            SummaryRowGreaterThan());
  for (int i = 0; i < count; ++i) {
    DCHECK_EQ(summary_.rows(summary_.rows_size() - 1).day_timestamp(), -1);
    if (summary_.rows(summary_.rows_size() - 1).day_timestamp() == -1) {
      summary_.mutable_rows()->RemoveLast();
    }
  }
}

import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVParser;
import org.apache.commons.csv.CSVRecord;
import org.apache.commons.compress.compressors.xz.XZCompressorInputStream;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class DataParser implements AutoCloseable {
    private BufferedReader reader;

    public DataParser(String filePath) throws IOException {
        if (filePath.endsWith(".xz")) {
            this.reader = new BufferedReader(new InputStreamReader(new XZCompressorInputStream(new FileInputStream(filePath))));
        } else {
            this.reader = new BufferedReader(new FileReader(filePath));
        }
    }

    public List<Point[]> parseData() throws IOException {
        List<Point[]> dataPoints = new ArrayList<>();
        try (CSVParser csvParser = new CSVParser(reader, CSVFormat.DEFAULT)) {
            for (CSVRecord record : csvParser) {
                List<Point> points = new ArrayList<>();
                for (int i = 0; i < record.size(); i += 2) {
                    int x = Integer.parseInt(record.get(i));
                    int y = Integer.parseInt(record.get(i + 1));
                    points.add(new Point(x, y));
                }
                dataPoints.add(points.toArray(new Point[0]));
            }
        }
        return dataPoints;
    }

    @Override
    public void close() throws IOException {
        if (reader != null) {
            reader.close();
        }
    }

    public static class Point {
        private final int x;
        private final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }
    }
}

