		(n, m) = inlt()
		all_pos = True
		nums = []
		for i in range(n):
			in_nums = inlt()
			for num in in_nums:
				if num < 0:
					all_pos = not all_pos
				nums.append(abs(num))
		nums.sort()
		if not all_pos:
			nums[0] = -nums[0]
		print(sum(nums))
