def delete_and_respond(self, request, contribution, file):
        user = request.user
        is_owner = not user.is_anonymous() and file.creator == user
        can_moderate = contribution.project.can_moderate(user)
        if is_owner or can_moderate:
            file.delete()
            return Response(status=status.HTTP_204_NO_CONTENT)
        else:
            raise PermissionDenied(
                'You are neither the creator if this file nor a project '
                'moderator and therefore not eligable to delete it.'
            )

private class MetaDataMonitorTask implements Runnable {

    private final SimpleKafkaConsumer ref;

    private transient final SetMultimap<Broker, KafkaPartition> deltaPositive = HashMultimap.create();

    private MetaDataMonitorTask(SimpleKafkaConsumer ref) {
      this.ref = ref;
    }

    @Override public void run() {
      try {
        monitorMetadata();
        monitorException.set(null);
        monitorExceptionCount.set(0);
      } catch (Throwable ex) {
        logger.error("Exception {}", ex);
        monitorException.set(ex);
        monitorExceptionCount.incrementAndGet();
      }
    }

    /**
     * Monitor kafka topic metadata changes.
     */
    private void monitorMetadata()
    {
      if (isAlive && (metadataRefreshRetryLimit == -1 || retryCounter.get() < metadataRefreshRetryLimit)) {
        logger.debug("{}: Update metadata for topic {}", Thread.currentThread().getName(), topic);
        Map<String, List<PartitionMetadata>> pms = KafkaMetadataUtil.getPartitionsForTopic(brokers, topic);
        if (pms == null) {
          // retrieve metadata fail add retry count and return
          retryCounter.getAndAdd(1);
          return;
        }

        for (Entry<String, List<PartitionMetadata>> pmLEntry : pms.entrySet()) {
          if (pmLEntry.getValue() == null)
            continue;
          for (PartitionMetadata pm : pmLEntry.getValue()) {
            KafkaPartition kp = new KafkaPartition(pmLEntry.getKey(), topic, pm.partitionId());
            if (!kps.contains(kp)) {
              // Out of this consumer's scope
              continue;
            }
            Broker b = pm.leader();
            if (b == null) {
              logger.info("No Leader broker for Kafka Partition {}. Skipping it for time until new leader is elected", kp.getPartitionId());
              continue;
            }
            Broker oldB = partitionToBroker.put(kp, b);
            if (b.equals(oldB)) {
              continue;
            }
            // add to positive
            deltaPositive.put(b, kp);

            // always update the latest connection information
            stats.updatePartitionStats(kp, pm.leader().id(), pm.leader().host() + ":" + pm.leader().port());
          }
        }

        // remove from map if the thread is done (partitions on this broker has all been reassigned to others(or temporarily not available) for
        // example)
        for (Iterator<Entry<Broker, ConsumerThread>> iterator = simpleConsumerThreads.entrySet().iterator(); iterator.hasNext(); ) {
          Entry<Broker, ConsumerThread> item = iterator.next();
          if (item.getValue().getThreadItSelf().isDone()) {
            iterator.remove();
          }
        }

        for (Broker b : deltaPositive.keySet()) {
          if (!simpleConsumerThreads.containsKey(b)) {
            // start thread for new broker
            ConsumerThread ct = new ConsumerThread(b, deltaPositive.get(b), ref);
            ct.setThreadItSelf(kafkaConsumerExecutor.submit(ct));
            simpleConsumerThreads.put(b, ct);

          } else {
            simpleConsumerThreads.get(b).addPartitions(deltaPositive.get(b));
          }
        }

        deltaPositive.clear();

        // reset to 0 if it reconnect to the broker which has current broker metadata
        retryCounter.set(0);
      }
    }

  }

def run_program(args: dict):
    """
    Executes commands based on the provided arguments.

    Args:
        args (dict): A dictionary containing the command and its arguments.
    """

    command = args.get("command")

    if not command:
        print("Error: 'command' not provided.")
        return

    if command == "exchange-device-token-for-service-account-token":
        if not all(key in args for key in ["device_token", "service_account_id"]):
            print("Error: 'device_token' and 'service_account_id' are required for 'exchange-device-token-for-service-account-token'.")
            return
        exchange_device_token_for_service_account_token(args["device_token"], args["service_account_id"])

    elif command == "generate-access-token":
        if not all(key in args for key in ["scopes", "service_account_id"]):
            print("Error: 'scopes' and 'service_account_id' are required for 'generate-access-token'.")
            return
        generate_access_token(args["scopes"], args["service_account_id"])

    elif command == "publish-pubsub-message":
        if not all(key in args for key in ["topic", "message"]):
            print("Error: 'topic' and 'message' are required for 'publish-pubsub-message'.")
            return
        publish_pubsub_message(args["topic"], args["message"])

    elif command == "send-command-to-iot-device":
        if not all(key in args for key in ["device_id", "command_payload"]):
            print("Error: 'device_id' and 'command_payload' are required for 'send-command-to-iot-device'.")
            return
        send_command_to_iot_device(args["device_id"], args["command_payload"])

    elif command == "download-cloud-storage-file":
        if not all(key in args for key in ["bucket_name", "file_path", "destination_path"]):
            print("Error: 'bucket_name', 'file_path', and 'destination_path' are required for 'download-cloud-storage-file'.")
            return
        download_cloud_storage_file(args["bucket_name"], args["file_path"], args["destination_path"])
    else:
        print("Invalid command.")


