package cn.eric.basiclib.utils;

import android.content.Context;

import cn.eric.basiclib.global.Configurator;
import io.reactivex.schedulers.Schedulers;
import retrofit2.Retrofit;
import retrofit2.adapter.rxjava2.RxJava2CallAdapterFactory;
import retrofit2.converter.gson.GsonConverterFactory;

/**
 * Created by hyx on 2017/2/16.
 */

public class Retrofit2Util {
    private static Retrofit sRetrofit;

    public static Retrofit getInstance(Context context) {
        if (sRetrofit == null) {
            synchronized (Retrofit2Util.class) {
                if (sRetrofit == null) {
                    String baseUrl = Configurator.get().getBaseUrl();
                    sRetrofit = new Retrofit.Builder().baseUrl(baseUrl)
                            .client(OkHttp3Util.getOkHttpClient(context))
                            .addConverterFactory(Configurator.get().getConverterFactory())
                            .addConverterFactory(GsonConverterFactory.create(GsonContext.getGson()))
                            .addCallAdapterFactory(RxJava2CallAdapterFactory.createWithScheduler(Schedulers.io()))
                            .build();
                }
            }
        }
        return sRetrofit;
    }
}

private static Object readBinary(String path, Object val, boolean isBinary) {
        if (!isBinary) {
            return val;
        }
        if (!(val instanceof String)) {
            log.error("binary property did not have a string value");
        }
        /* if it's a temporary file, then we need to look for it in the
         * temporary folder, otherwise look in the resource folder */
        String filename = (String) val;
        Path folder = (filename.contains(FSPConstants.FILENAME_FRAGMENT_TEMPORARY))
                ? Util.getTemporaryDirectory() : Paths.get(Util.getAbsPath(path));
        Path file = Paths.get(folder.toAbsolutePath().toString(), filename);
        try {
            return new FileBinary(file);
        } catch (IOException e) {
            log.error("Unable to create Binary representation from {}", file.toAbsolutePath(), e);
            return null;
        }
    }

public class ConvertingRetriever<R> extends DataRetriever<R>{

    private final Converter<SOData, R> converter;

    /**
     *
     * @param lApi {@link LApi}
     * @param query {@link Query} for the HttpRequest
     * @param converter {@link Converter} to convert from {@link SOData} to {@link R}
     */
    public ConvertingRetriever(@NotNull LApi lApi, @NotNull Query query, @NotNull Converter<SOData, R> converter) {
        super(lApi, query);
        this.converter = converter;
    }

    @Override
    protected @Nullable R processData(@NotNull SOData data) throws InvalidDataException {
        return converter.convert(lApi, data);
    }
}

