using System;

public abstract class ArrayWriter
{
    public abstract int EmitSizeEstimator(WriterEmitContext context);

    public void EmitWrite(WriterEmitContext context, Action<object> loadElement)
    {
        context.PushLoadElement(loadElement);
        for (int i = 0; i < context.ArrayLength; i++)
        {
            context.Emit(OpCodes.Ldarg, i);
            context.Emit(OpCodes.Stloc, i);
        }
        context.Emit(OpCodes.Ret);
    }
}

public class BoundedSizeArrayWriter : ArrayWriter, IBoundedSizeWriter
{
    public override int EmitSizeEstimator(WriterEmitContext context)
    {
        context.Emit(OpCodes.Ldarg_0);
        context.Emit(OpCodes.Ldarg_1);
        context.Emit(OpCodes.Callvirt, typeof(ArrayWriter).GetMethod(nameof(EmitSizeEstimator)));
        return context.Emit(OpCodes.Ldc_I4_1); // Size estimation for bounded arrays
    }
}

public class VarSizeArrayWriter : ArrayWriter, IVarSizeWriter
{
    public override int EmitSizeEstimator(WriterEmitContext context)
    {
        context.Emit(OpCodes.Ldarg_0);
        context.Emit(OpCodes.Ldarg_1);
        context.Emit(OpCodes.Callvirt, typeof(ArrayWriter).GetMethod(nameof(EmitSizeEstimator)));
        return context.Emit(OpCodes.Ldc_I4_1); // Size estimation for variable-sized arrays
    }
}

public interface IBoundedSizeWriter
{
    int Size { get; }
}

public interface IVarSizeWriter
{
    int Size { get; }
}

