// Require implementations
bool UARTInit(UARTDev_t * const pDev, const UARTCfg_t *pCfgData);
void UARTSetCtrlLineState(UARTDev_t * const pDev, uint32_t LineState);
UARTDev_t * const UARTGetInstance(int DevNo);

static inline int UARTGetRate(UARTDev_t * const pDev) { return DeviceIntrfGetRate(&pDev->DevIntrf); }
static inline int UARTSetRate(UARTDev_t * const pDev, int Rate) { return DeviceIntrfSetRate(&pDev->DevIntrf, Rate); }
static inline void UARTEnable(UARTDev_t * const pDev) { DeviceIntrfEnable(&pDev->DevIntrf); }
static inline void UARTDisable(UARTDev_t * const pDev) { DeviceIntrfDisable(&pDev->DevIntrf); }
static inline int UARTRx(UARTDev_t * const pDev, uint8_t *pBuff, int Bufflen) {
	return DeviceIntrfRx(&pDev->DevIntrf, 0, pBuff, Bufflen);
}
static inline int UARTTx(UARTDev_t * const pDev, uint8_t *pData, int Datalen) {
	return DeviceIntrfTx(&pDev->DevIntrf, 0, pData, Datalen);
}
void UARTprintf(UARTDev_t * const pDev, const char *pFormat, ...);
void UARTvprintf(UARTDev_t * const pDev, const char *pFormat, va_list vl);
void UARTRetargetEnable(UARTDev_t * const pDev, int FileNo);
void UARTRetargetDisable(UARTDev_t * const pDev, int FileNo);

#ifdef __cplusplus
}

// C++ class wrapper

/// UART base class
class UART: public DeviceIntrf {
public:
	UART() {
		memset(&vDevData, 0, sizeof(vDevData));
		vDevData.pObj = this;
	}
	virtual ~UART() {}
	UART(UART&);

	virtual bool Init(const UARTCfg_t &CfgData) {
		return UARTInit(&vDevData, &CfgData);
	}

	operator DevIntrf_t * const () { return &vDevData.DevIntrf; }
	operator UARTDev_t *  const () { return &vDevData; }

	// Set data baudrate
	virtual uint32_t Rate(uint32_t DataRate) { return UARTSetRate(&vDevData, DataRate); }
	// Get current data baudrate
	virtual uint32_t Rate(void) { return UARTGetRate(&vDevData); }
    void Enable(void) { DeviceIntrfEnable(&vDevData.DevIntrf); }
    void Disable(void) { DeviceIntrfDisable(&vDevData.DevIntrf); }
	virtual void SetCtrlLineState(int LineState) { UARTSetCtrlLineState(&vDevData, LineState); }
	virtual int Rx(uint8_t *pBuff, int Len) { return DeviceIntrfRx(&vDevData.DevIntrf, 0, pBuff, Len); }
	// Initiate receive
	virtual bool StartRx(uint32_t DevAddr) { return DeviceIntrfStartRx(&vDevData.DevIntrf, DevAddr); }
	// Receive Data only, no Start/Stop condition
	virtual int RxData(uint8_t *pBuff, int BuffLen) {
		return DeviceIntrfRxData(&vDevData.DevIntrf, pBuff, BuffLen);
	}
	// Stop receive
	virtual void StopRx(void) { DeviceIntrfStopRx(&vDevData.DevIntrf); }
	virtual int Tx(uint8_t *pData, uint32_t Len) { return DeviceIntrfTx(&vDevData.DevIntrf, 0, pData, Len); }
	// Initiate transmit
	virtual bool StartTx(uint32_t DevAddr) { return DeviceIntrfStartTx(&vDevData.DevIntrf, DevAddr); }
	// Transmit Data only, no Start/Stop condition
	virtual int TxData(uint8_t *pData, int DataLen) {
		return DeviceIntrfTxData(&vDevData.DevIntrf, pData, DataLen);
	}
	// Stop transmit
	virtual void StopTx(void) { DeviceIntrfStopTx(&vDevData.DevIntrf); }
	void printf(const char *pFormat, ...) {
		va_list vl;
	    va_start(vl, pFormat);
	    UARTvprintf(&vDevData, pFormat, vl);
	    va_end(vl);
	}

    virtual bool RequestToSend(int NbBytes) {
        if (CFifoAvail(vDevData.hTxFifo) < NbBytes)
            return false;
        return true;
    }

private:
	UARTDev_t	vDevData;
};


