void AuxFunc(const dTensor1& xpts, 
	     dTensor2& auxvals)
{
  const int numpts=xpts.getsize();
  double x,gamma;
  char buffer[256];
  ifstream read_file("param.data", ios::in);
  read_file >> gamma;
  read_file.getline(buffer,256);
  read_file.close();
  for (int i=1; i<=numpts; i++)
    {
      x = xpts.get(i);
      auxvals.set(i,1, gamma );
    }
}

import sys
from collections import Counter

def solve(N, B):
	counts = Counter(B)
	if any((v > 1 for v in counts.values())):
		return -1
	C = []
	for x in range(1, 2 * N + 1):
		if x not in counts:
			C.append(x)
	if any((b > c for (b, c) in zip(sorted(B), C))):
		return -1

	def gen(index=0):
		if index == N:
			yield C
			return
		for (c, i) in sorted(zip(C[index:N], range(index, N))):
			if B[index] < c:
				(C[index], C[i]) = (C[i], C[index])
				yield from gen(index + 1)
				(C[index], C[i]) = (C[i], C[index])
	for sol in gen():
		A = []
		for (b, c) in zip(B, C):
			A.append(str(b))
			A.append(str(c))
		return ' '.join(A)
	return -1
input = sys.stdin.readline
T = int(input())
for t in range(T):
	(N,) = map(int, input().split())
	B = [int(x) for x in input().split()]
	ans = solve(N, B)
	print(ans)
